INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a8c6852d-28fc-4f08-87ce-45560d6e4b5b', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h1>General Business Conditions</h1>', 'cc15b654-d163-48d9-b253-b75592433f1e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a82fac86-f766-4bc9-aa98-54849990db69', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h1>Condiciones Generales de Contratación</h1>', 'cc15b654-d163-48d9-b253-b75592433f1e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2a7892d1-6819-4fc3-b90c-7315eb79c5ae', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p><strong>Esta traducción se suministra exclusivamente para información del cliente. En caso de divergencia, solamente el texto original alemán de las Condiciones Generales de Contratación será legalmente vinculante.</strong></p>', '8dc17aef-30b8-435d-9c85-c4700c9e3fe6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fe0d889c-c5db-4496-ba7a-b15423af8f45', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p><strong>Esta traducción se suministra exclusivamente para información del cliente. En caso de divergencia, solamente el texto original alemán de las Condiciones Generales de Contratación será legalmente vinculante.</strong></p>', '8dc17aef-30b8-435d-9c85-c4700c9e3fe6');
