INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('022b6b4f-7f76-4b81-9ed0-231493c2f392', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Grundregeln für die Beziehung zwischen Kunde und Bank</p>', 'a9aca66c-765b-4582-80bb-88cc253a1318');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('990b20a0-0ea2-48db-b4bb-8004b5f9bbb7', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Basic Rules Governing the Relationship Between the Customer and the Bank</p>', 'a9aca66c-765b-4582-80bb-88cc253a1318');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('06365e97-5108-443d-9820-65f04b83875a', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Reglas básicas que regulan las relaciones contractuales entre el cliente y el banco.</p>', 'a9aca66c-765b-4582-80bb-88cc253a1318');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('358f80d7-8f3a-4bc3-8932-c46feac589d7', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>1. Geltungsbereich und Änderungen dieser Geschäftsbedingungen und der Sonderbedingungen für einzelne Geschäftsbeziehungen</h2>', '186658b7-b09b-4968-a7e9-546c70bc6fcd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5c194092-683b-40c3-bbe1-5c268e90660e', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>1. Scope of application and amendments of these Business Conditions and the Special Conditions for particular business relations.</h2>', '186658b7-b09b-4968-a7e9-546c70bc6fcd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3460a87b-3147-4b3a-891c-74e3d40fd634', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>1. Ámbito de aplicación y modificaciones de las presentes Condiciones de Contratación y de cláusulas específicas para determinados tipos de operaciones</h2>', '186658b7-b09b-4968-a7e9-546c70bc6fcd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('328db153-9f8b-4df3-889d-89ff5fb4fc3f', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>1.1 Geltungsbereich</h2>', '8d6f253e-1a48-4c91-88c5-6d50b10594db');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('301507e2-857e-42f9-95a7-109987b037b0', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>1.1 Scope of application</h2>', '8d6f253e-1a48-4c91-88c5-6d50b10594db');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('554a4852-de62-4366-91d3-00b563d0bf09', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>1.1 Ámbito de aplicación</h2>', '8d6f253e-1a48-4c91-88c5-6d50b10594db');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8d6e005d-22ef-4629-992c-2ba91cec30c3', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Allgemeinen Geschäftsbedingungen gelten für die gesamte Geschäftsverbindung zwischen dem Kunden und den inländischen Geschäftsstellen der Bank (im Folgenden Bank genannt). Daneben gelten für einzelne Geschäftsbeziehungen (zum Beispiel für das Wertpapiergeschäft, den Zahlungsverkehr und für den Sparverkehr) Sonderbedingungen, die Abweichungen oder Ergänzungen zu diesen Allgemeinen Geschäftsbedingungen enthalten; sie werden bei der Kontoeröffnung oder bei Erteilung eines Auftrages mit dem Kunden vereinbart. Unterhält der Kunde auch Geschäftsverbindungen zu ausländischen Geschäftsstellen, sichert das Pfandrecht der Bank (Nr. 14 dieser Geschäftsbedingungen) auch die Ansprüche dieser ausländischen Geschäftsstellen.</p>', '6e7b0fb2-28f5-4f54-8a24-d8116872ea90');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d12e46fb-a476-4599-b365-3bde0a0b2330', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The General Business Conditions govern the entire business relationship between the customer and the bank&#39;s domestic offices (hereinafter referred to as the &quot;Bank&quot;). In addition, particular business relations (securities transactions, payment services and savings accounts, for example) are governed by Special Conditions, which contain deviations from, or complements to, these General Business Conditions; they are agreed with the customer when the account is opened or an order is given. If the customer also maintains business relations with foreign offices, the Bank&#39;s lien (No. 14 of these Business Conditions) also secures the claims of such foreign offices.</p>', '6e7b0fb2-28f5-4f54-8a24-d8116872ea90');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4c9832b8-a4c4-4dbe-9a59-c4883ddbb037', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Las presentes Condiciones Generales de Contratación se aplicarán a todas las relaciones comerciales entre el cliente y las oficinas del banco en Alemania (en adelante &quot;el banco&quot;). Para determinados tipos de operaciones o servicios (por ejemplo, compra y venta de valores mobiliarios, servicios de pagos y cuentas de ahorro), se aplicarán adicionalmente las cláusulas específicas con modificaciones o ampliaciones a las presentes Condiciones Generales de Contratación, acordadas con el cliente en la apertura de una cuenta o al cursarse una orden. Si el cliente efectúa también operaciones con oficinas del banco situadas fuera de Alemania, el derecho de prenda del banco (art. 14 de las presentes Condiciones de Contratación) se extenderá a los derechos de estas oficinas.</p>', '6e7b0fb2-28f5-4f54-8a24-d8116872ea90');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9a25a74f-ce75-4961-ae4b-c13d693ebb47', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>1.2 Änderungen</h2>', 'baa4984e-6ad5-4def-a02d-0ac7fd292cd1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('517282dc-300d-486d-bd2c-cfbab8e3b759', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>1.2 Amendments</h2>', 'baa4984e-6ad5-4def-a02d-0ac7fd292cd1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('40a82bde-9b29-4789-b1e4-73b4af1d8b94', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>1.2 Modificaciones</h2>', 'baa4984e-6ad5-4def-a02d-0ac7fd292cd1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0f412a06-fbf7-4bd7-806a-46e20c2cc29d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>a) Änderungsangebot</h2>', '7366f6f1-2ee2-4f10-a94e-c106732250c9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fcfdbe27-476d-494a-818d-810f4ce8f55c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>a) Offer of amendments</h2>', '7366f6f1-2ee2-4f10-a94e-c106732250c9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('50473272-0a83-4aa0-910c-4e2358412f89', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>a) Oferta de modificaciones</h2>', '7366f6f1-2ee2-4f10-a94e-c106732250c9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('33ad8692-5d40-47a4-b3ff-b5f6ae5fc872', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Änderungen dieser Geschäftsbedingungen und der Sonderbedingungen werden dem Kunden spätestens zwei Monate vor dem vorgeschlagenen Zeitpunkt ihres Wirksamwerdens in Textform angeboten. Hat der Kunde mit der Bank im Rahmen der Geschäftsbeziehung einen elektronischen Kommunikationsweg vereinbart (zum Beispiel das Online-Banking), können die Änderungen auch auf diesem Wege angeboten werden.</p>', '37306544-39ef-4c17-8473-44c14abc7777');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('07fadf01-1ecb-43aa-8891-7f782d911509', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Any amendments to these General Business Conditions and the Special Conditions shall be offered to the customer in text form no later than two months before their proposed date of entry into force. If the customer has agreed an electronic communication channel (e.g. online banking) with the Bank within the framework of the business relationship, the amendments may also be offered through this channel.</p>', '37306544-39ef-4c17-8473-44c14abc7777');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6f14213e-c4ec-44c5-a95d-6d2a5b8f6b0a', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Toda modificación de las presentes Condiciones Generales de Contratación o cláusulas específicas deberá ser comunicada en forma textual al cliente con una antelación mínima de dos meses con respecto a la fecha designada para que tome efecto. Si el cliente y el banco han convenido un sistema electrónico de comunicación en el ámbito de las relaciones contractuales (por ejemplo: banca electrónica), los cambios que se realicen también podrán ser comunicados por esa vía.</p>', '37306544-39ef-4c17-8473-44c14abc7777');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0aa8ab23-9eef-4c38-843c-e04b83c1633a', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>b) Annahme durch den Kunden</h2>', 'e026608b-fa7e-4192-8bb2-1b742cc679d6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('41c686f6-7c6f-4afd-babb-cf95869d625a', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>b) Acceptance by the customer</h2>', 'e026608b-fa7e-4192-8bb2-1b742cc679d6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c452ee13-256c-446a-8eaa-f716f6dde1e5', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>b) Aceptación por parte del cliente</h2>', 'e026608b-fa7e-4192-8bb2-1b742cc679d6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('787b3ebf-f234-436f-81ac-de12993ec8e8', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die von der Bank angebotenen Änderungen werden nur wirksam, wenn der Kunde diese annimmt, gegebenenfalls im Wege der nachfolgend geregelten Zustimmungsfiktion.</p>', 'd1320d5e-bc77-4d74-a0dc-a9aa9d66a57b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2543d45a-cbfa-40f5-bde8-7c2c1539d630', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The amendments offered by the Bank shall only become effective if the customer accepts them, where appropriate by way of the deemed consent set out in the following clause.</p>', 'd1320d5e-bc77-4d74-a0dc-a9aa9d66a57b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f536d19c-06fd-42a5-bc9c-ab262e739f8b', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Los cambios ofrecidos por el banco solo entrarán en vigor si el cliente los acepta, dado el caso, por vía del supuesto de consentimiento definido a continuación.</p>', 'd1320d5e-bc77-4d74-a0dc-a9aa9d66a57b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7f25a27e-c797-422a-a94e-a01867172928', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>c) Annahme durch den Kunden im Wege der Zustimmungsfiktion</h2>', 'b025731c-9e87-4212-821d-6f1a4dfa8472');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f56f0fbf-d8cb-4908-be5d-84a8360bcb64', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>c) Acceptance by the customer by way of deemed consent</h2>', 'b025731c-9e87-4212-821d-6f1a4dfa8472');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9105618a-2547-4800-98fc-9833b8eaf3a3', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>c) Aceptación por parte del cliente por vía del supuesto de consentimiento</h2>', 'b025731c-9e87-4212-821d-6f1a4dfa8472');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2c2ae7d9-d53c-4726-bf67-c09989e91e2e', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Das Schweigen des Kunden gilt nur dann als Annahme des Änderungsangebots (Zustimmungsfiktion), wenn</p>', '0be34d82-1290-4fd0-b0dd-e120c549696a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('28860a3b-6cbb-4ad5-bf17-4f8f039464fc', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Silence on the part of the customer shall only be deemed to constitute acceptance of the offered amendments (deemed consent [Zustimmungsfiktion]) if</p>', '0be34d82-1290-4fd0-b0dd-e120c549696a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8c3fdefd-0ab4-4e83-9645-b905bf4d268f', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El silencio del cliente solo se considerará una aceptación de la oferta de cambio (supuesto de consentimiento), si se cumplen las siguientes condiciones:</p>', '0be34d82-1290-4fd0-b0dd-e120c549696a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('196129d8-f1df-43b4-a75f-fa4e4dd97e5c', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>(i) das Änderungsangebot der Bank erfolgt, um die Übereinstimmung der vertraglichen Bestimmungen mit einer veränderten Rechtslage wiederherzustellen, weil eine Bestimmung dieser Geschäftsbedingungen oder der Sonderbedingungen</p>', '610f6fc3-adf8-4735-a6e1-ec0e86ed6157');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2a9d248b-f8bb-4533-9157-7cb44e2caca0', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>(i) the Bank is offering amendments to restore the conformity of the contractual provisions with a changed legal position because a provision of these General Business Conditions or of the Special Conditions</p>', '610f6fc3-adf8-4735-a6e1-ec0e86ed6157');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f817a790-04a5-456c-8428-331165a73fdd', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>(i) La oferta de cambio del banco tiene lugar con el fin de restablecer la conformidad de las disposiciones contractuales con una situación jurídica actual diferente porque una disposición de dichas condiciones generales de contratación o condiciones especiales ha dejado de cumplir la ley debido a cambios en las leyes, incluyendo los reglamentos jurídicos directamente vigentes de la Unión Europea; o porque, debido a un fallo judicial en vigor, también emitido por un juzgado de primera instancia, ha dejado de ser válida o no se puede aplicar más; o porque, debido a una disposición vinculante de una autoridad nacional o internacional competente para el banco (p. ej. la Autoridad Federal de Supervisión Financiera de Alemania, BaFin, o el Banco Central Europeo), ha dejado de estar conforme con las obligaciones del banco según las disposiciones de la supervisión financiera.</p>', '610f6fc3-adf8-4735-a6e1-ec0e86ed6157');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2d3214cb-1e68-4873-be9a-5c8fb6bf8c89', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<ul><li>aufgrund einer Änderung von Gesetzen, einschließlich unmittelbar geltender Rechtsvorschriften der Europäischen Union, nicht mehr der Rechtslage entspricht oder</li><li>durch eine rechtskräftige gerichtliche Entscheidung, auch durch ein Gericht erster Instanz, unwirksam wird oder nicht mehr verwendet werden darf oder</li><li>aufgrund einer verbindlichen Verfügung einer für die Bank zuständigen nationalen oder internationalen Behörde (z. B. der Bundesanstalt für Finanzdienstleistungsaufsicht oder der Europäischen Zentralbank) nicht mehr mit den aufsichtsrechtlichen Verpflichtungen der Bank in Einklang zu bringen ist, und</li></ul>', 'd5321908-6b54-464f-a442-d6477a733ea2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4eab2992-4dba-43fb-8036-231f8e775eab', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<ul><li>is no longer consistent with the legal position as a result of a change in the law, including directly applicable legal provisions of the European Union, or</li><li>is rendered ineffective or may no longer be used as a result of a final court decision, including by a court of first instance, or</li><li>is no longer in compliance with the Bank’s regulatory obligations as a result of a binding administrative act issued by a national or international competent authority for the Bank (e.g. the German Federal Financial Supervisory Authority [Bundesanstalt für Finanzdienstleistungsaufsicht] or the European Central Bank) and</li></ul>', 'd5321908-6b54-464f-a442-d6477a733ea2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('586ea145-dc23-4784-8cdc-b02b6c78a5fc', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<ul><li>is no longer consistent with the legal position as a result of a change in the law, including directly applicable legal provisions of the European Union, or</li><li>durch eine rechtskräftige gerichtliche Entscheidung, auch durch ein Gericht erster Instanz, unwirksam wird oder nicht mehr verwendet werden darf oder</li><li>aufgrund einer verbindlichen Verfügung einer für die Bank zuständigen nationalen oder internationalen Behörde (z. B. der Bundesanstalt für Finanzdienstleistungsaufsicht oder der Europäischen Zentralbank) nicht mehr mit den aufsichtsrechtlichen Verpflichtungen der Bank in Einklang zu bringen ist, und</li></ul>', 'd5321908-6b54-464f-a442-d6477a733ea2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3e1795d5-ec80-47bb-ae98-a9e3ab024dec', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>(ii) der Kunde das Änderungsangebot der Bank nicht vor dem vorgeschlagenen Zeitpunkt des Wirksamwerdens der Änderungen abgelehnt hat. Die Bank wird den Kunden im Änderungsangebot auf die Folgen seines Schweigens hinweisen.</p>', '8de11a5e-f881-406b-8737-cbcf035740f9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('48db477b-6ac7-4820-a33c-c38db8608348', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>(ii) the customer has not rejected the Bank&#39;s offer of amendments before the proposed date of the entry into force of the changes. In its offer of amendments, the Bank shall specifically draw the customer&#39;s attention to the consequences of remaining silent.</p>', '8de11a5e-f881-406b-8737-cbcf035740f9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('527cc3ff-8333-45c9-8d2b-a71d84f47185', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>(ii) El cliente no ha rechazado la oferta de cambio del banco antes del plazo propuesto de entrada en vigor de los cambios. El banco informará al cliente de las consecuencias de su silencio en la oferta de cambio.</p>', '8de11a5e-f881-406b-8737-cbcf035740f9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f461a2d6-fb19-485c-953e-3f93ea89b822', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>d) Ausschluss der Zustimmungsfiktion</h2>', 'd602d5c6-17ca-460a-8556-cff3ce6d966b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7949cc3f-d926-445e-b825-cb33abbb874f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>d) Exclusion of deemed consent</h2>', 'd602d5c6-17ca-460a-8556-cff3ce6d966b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2742b624-f7df-47ab-8a62-cb9187f9d9dd', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>d) Exclusión del supuesto de consentimiento</h2>', 'd602d5c6-17ca-460a-8556-cff3ce6d966b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('69e555ee-55cb-45eb-9773-da152d04524d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Zustimmungsfiktion findet keine Anwendung</p>', '510804f2-9843-4149-a349-c7849ed33b46');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b66854ba-3298-4648-9600-fb10cd0da7a7', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Deemed consent shall not apply</p>', '510804f2-9843-4149-a349-c7849ed33b46');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5caed370-00f1-445d-84d9-4d63a47e00a4', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El supuesto de consentimiento no es de aplicación en los siguientes casos:</p>', '510804f2-9843-4149-a349-c7849ed33b46');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('70c9047f-e5cb-425c-b850-0b975584c3af', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<ul><li>bei Änderungen der Nummern 1 Absatz 2 und 12 Absatz 5 der Geschäftsbedingungen und der entsprechenden Regelungen in den Sonderbedingungen oder</li><li>bei Änderungen, die die Hauptleistungspflichten des Vertrages und die Entgelte für Hauptleistungen betreffen, oder</li><li>bei Änderungen von Entgelten, die auf eine über das vereinbarte Entgelt für die Hauptleistung hinausgehende Zahlung des Verbrauchers gerichtet sind, oder</li><li>bei Änderungen, die dem Abschluss eines neuen Vertrages gleichkommen, oder</li><li>bei Änderungen, die das bisher vereinbarte Verhältnis von Leistung und Gegenleistung erheblich zugunsten der Bank verschieben würden.</li></ul>', '5c4ffafd-665c-4322-bd0e-08b98f1b33a8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('de9deb5f-a324-406e-a4e9-9e90e3277d62', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<ul><li>to amendments to No. 1, paragraph 2 and No. 12, paragraph 5 of the General Business Conditions and to the corresponding provisions in the Special Conditions, or</li><li>to amendments affecting the obligations under the agreement to perform principal services and the charges for principal services, or</li><li>to amendments to charges which concern a payment by the consumer in excess of the charge agreed for the principal service, or</li><li>to amendments which amount to the conclusion of a new agreement, or</li><li>to amendments which would significantly shift the previously agreed relationship between performance and remuneration in favour of the Bank.</li></ul>', '5c4ffafd-665c-4322-bd0e-08b98f1b33a8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('371a23fb-02e7-4d4b-b079-e1271857859e', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<ul><li>Cambios en los artículos 1, apartado 2, y 12, apartado 5 de las condiciones generales de contratación y de las regulaciones correspondientes de las condiciones especiales.</li><li>Cambios que afecten las obligaciones de pago principales del contrato y las remuneraciones de las obligaciones de pago</li><li>Cambios en las remuneraciones relacionadas con pagos del consumidor que vayan más allá de la remuneración acordada como obligación de pago principal.</li><li>Cambios que sean equivalentes al cierre de un nuevo contrato.</li><li>Cambios que desbalanceen considerablemente la relación de prestaciones y contraprestaciones a favor del banco.</li></ul>', '5c4ffafd-665c-4322-bd0e-08b98f1b33a8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e3c36f49-f5c9-4aa8-a261-61f530e45606', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>In diesen Fällen wird die Bank die Zustimmung des Kunden zu den Änderungen auf andere Weise einholen.</p>', '8e516f2e-7352-4e47-8aa3-57f879eacf46');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4dde1a78-e0f4-4f64-80b2-9fb19444aa5a', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>In these cases, the Bank shall use other means to obtain the customer&#39;s consent to the amendments.</p>', '8e516f2e-7352-4e47-8aa3-57f879eacf46');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a509ef55-96f4-4c09-be3a-77d0ce5d869f', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>En estos casos, el banco solicitará el consentimiento de los cambios por parte del cliente por otra vía.</p>', '8e516f2e-7352-4e47-8aa3-57f879eacf46');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f70c1bc4-427a-4a1f-b07b-51adb4db637f', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>e) Kündigungsrecht des Kunden bei der Zustimmungsfiktion</h2>', '13e1db45-92f1-4438-9dd1-6e68e9220656');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e6f6e867-e1f9-45ce-8133-130829453081', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>e) Customer&#39;s right of termination in cases of deemed consent</h2>', '13e1db45-92f1-4438-9dd1-6e68e9220656');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d52b4f2a-c2a0-460d-9642-69dcfb16ae0a', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>e) Derecho de rescisión en caso de supuesto de consentimiento</h2>', '13e1db45-92f1-4438-9dd1-6e68e9220656');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3f271e37-32fa-433a-a226-4cc510e5c295', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Macht die Bank von der Zustimmungsfiktion Gebrauch, kann der Kunde den von der Änderung betroffenen Vertrag vor dem vorgeschlagenen Zeitpunkt des Wirksamwerdens der Änderungen auch fristlos und kostenfrei kündigen. Auf dieses Kündigungsrecht wird die Bank den Kunden in ihrem Änderungsangebot besonders hinweisen.</p>', '6cc1d412-b076-4667-ae67-2264b04984a7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4aa7671d-d75c-4cf0-9d6b-9a0c6bf0d1e3', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the Bank makes use of deemed consent, the customer may also terminate the agreement affected by the amendment without notice and free of charge prior to the proposed date of entry into force of the amendments. The Bank shall specifically draw the customer&#39;s attention to this right of termination in its offer of amendments.</p>', '6cc1d412-b076-4667-ae67-2264b04984a7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('60a88fcb-dbea-40a6-92a5-b4d927dd6a8a', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si el banco hace uso del supuesto de consentimiento, el cliente puede rescindir, de inmediato y exento de gastos, el contrato afectado por los cambios antes del plazo propuesto de entrada en vigor de los cambios. El banco informará al cliente expresamente de su derecho de rescisión en su oferta de modificaciones.</p>', '6cc1d412-b076-4667-ae67-2264b04984a7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ae555ba4-84a1-4d0e-9ed0-ad4e3753a4a2', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>2. Bankgeheimnis und Bankauskunft</h2>', '2aa51f65-bb14-4950-94cc-d7e66f3c8f05');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4d18dae8-bf16-472d-bdaa-718c3f46f1df', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>2. Banking secrecy and disclosure of banking affairs</h2>', '2aa51f65-bb14-4950-94cc-d7e66f3c8f05');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('de4dc773-d76c-4441-a7c6-c3127e886e37', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>2. Secreto bancario e informes comerciales</h2>', '2aa51f65-bb14-4950-94cc-d7e66f3c8f05');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3164f759-1130-4db8-b930-cb4d7fe7538f', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>2.1 Bankgeheimnis</h2>', '3632c4f9-eeea-4491-85b7-f4681e24d5a3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fa3cb2f8-3b65-4251-ac8e-d138c4bbc579', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>2.1 Banking secrecy</h2>', '3632c4f9-eeea-4491-85b7-f4681e24d5a3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('12596bc5-4021-40bf-bbf8-2fc3b345e968', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>2.1 Secreto bancario</h2>', '3632c4f9-eeea-4491-85b7-f4681e24d5a3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ec182061-e771-46c5-affb-c8c094f23381', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank ist zur Verschwiegenheit über alle kundenbezogenen Tatsachen und Wertungen verpflichtet, von denen sie Kenntnis erlangt (Bankgeheimnis). Informationen über den Kunden darf die Bank nur weitergeben, wenn gesetzliche Bestimmungen dies gebieten oder der Kunde eingewilligt hat oder die Bank zur Erteilung einer Bankauskunft befugt ist.</p>', '69d554c9-ecda-4364-bc3f-4e2779422536');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8e5485d3-ac18-4b4e-8489-ccdbf6f10f5f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank has the duty to maintain secrecy about any customer-related facts and evaluations of which it may have knowledge (banking secrecy). The Bank may only disclose information concerning the customer if it is legally required to do so or if the customer has consented thereto or if the Bank is authorized to disclose banking affairs.</p>', '69d554c9-ecda-4364-bc3f-4e2779422536');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6051bfd0-02bd-4569-a873-6c953de88dc3', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco deberá tratar confidencialmente todos los hechos y valoraciones relacionados con el cliente que puedan llegar a su conocimiento (secreto bancario). El banco solamente podrá facilitar información referente al cliente en los supuestos en los que la ley lo exigiera, a los que el cliente haya dado expresamente su consentimiento o que el banco esté facultado para facilitar.</p>', '69d554c9-ecda-4364-bc3f-4e2779422536');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('60c00168-eeaa-4e77-8038-fa44bf5352ed', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>2.2 Bankauskunft</h2>', '24e67fc3-cb90-4e96-940d-4de78bb87844');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8fe8f9ce-7c11-42a0-83e5-724e661e886f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>2.2 Disclosure of banking affairs</h2>', '24e67fc3-cb90-4e96-940d-4de78bb87844');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f7ce16c7-7092-48a6-93dc-7b3e8f547ce0', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>2.2 Informe comercial</h2>', '24e67fc3-cb90-4e96-940d-4de78bb87844');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6ee781c1-a87a-4c2e-8485-5406057ac4fb', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Eine Bankauskunft enthält allgemein gehaltene Feststellungen und Bemerkungen über die wirtschaftlichen Verhältnisse des Kunden, seine Kreditwürdigkeit und Zahlungsfähigkeit; betragsmäßige Angaben über Kontostände, Sparguthaben, Depot- oder sonstige der Bank anvertraute Vermögenswerte sowie Angaben über die Höhe von Kreditinanspruchnahmen werden nicht gemacht.</p>', 'eb5c53db-be79-49a7-bf5b-aa5fa789f685');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f28e2921-bb0f-4693-9b1e-46be1ff8f1ed', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Any disclosure of details of banking affairs comprises statements and comments of a general nature concerning the economic status, the creditworthiness and solvency of the customer; no information shall be disclosed as to amounts of balances of accounts, of savings deposits, of securities deposits or of other assets entrusted to the Bank or as to amounts drawn under a credit facility.</p>', 'eb5c53db-be79-49a7-bf5b-aa5fa789f685');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a2adda30-9feb-42ab-be43-5d197ef47516', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El informe comercial consiste en información constatada y comentarios de naturaleza general sobre la situación financiera del cliente, su solvencia crediticia y capacidad de pago. El banco no podrá proporcionar cifras sobre saldos acreedores en cuentas corrientes de ahorro o en carteras de valores ni cualquier otra cantidad representativa de los activos que el cliente haya confiado al banco, ni tampoco de los importes retirados por el cliente de su línea de crédito.</p>', 'eb5c53db-be79-49a7-bf5b-aa5fa789f685');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ddab4009-246a-40a8-9d24-f5ac5402f000', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>2.3 Voraussetzungen für die Erteilung einer Bankauskunft</h2>', '55c3778a-6528-4823-8e84-f4b74c6e2b21');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('de410f88-0863-4995-9409-cb504c1a4373', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>2.3 Prerequisites for the disclosure of banking affairs</h2>', '55c3778a-6528-4823-8e84-f4b74c6e2b21');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7e89b058-2f00-4977-ba39-52f2c8fdcb47', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>2.3 Requisitos para la emisión de informes comerciales</h2>', '55c3778a-6528-4823-8e84-f4b74c6e2b21');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('695431b0-9c99-40f6-9657-983273ebbb56', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank ist befugt, über juristische Personen und im Handelsregister eingetragene Kaufleute Bankauskünfte zu erteilen, sofern sich die Anfrage auf ihre geschäftliche Tätigkeit bezieht. Die Bank erteilt jedoch keine Auskünfte, wenn ihr eine anders lautende Weisung des Kunden vorliegt. Bankauskünfte über andere Personen, insbesondere über Privatkunden und Vereinigungen, erteilt die Bank nur dann, wenn diese generell oder im Einzelfall ausdrücklich zugestimmt haben. Eine Bankauskunft wird nur erteilt, wenn der Anfragende ein berechtigtes Interesse an der gewünschten Auskunft glaubhaft dargelegt hat und kein Grund zu der Annahme besteht, dass schutzwürdige Belange des Kunden der Auskunftserteilung entgegenstehen.</p>', '9ac95de4-767d-49aa-8752-015ee33f5421');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c19bd349-541f-4ef6-8c31-14ecbbdcce2c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank shall be entitled to disclose banking affairs concerning legal entities and on businesspersons registered in the Commercial Register, provided that the inquiry relates to their business activities. The Bank shall not, however, disclose any information if it has received instructions to the contrary from the customer. Details of banking affairs concerning other persons, in particular retail customers and associations, shall be disclosed by the Bank only if such persons have expressly agreed thereto, either generally or in an individual case. Details of banking affairs shall be disclosed only if the requesting party has substantiated its justified interest in the information requested and there is no reason to assume that the disclosure of such information would be contrary to the customer&#39;s legitimate concerns.</p>', '9ac95de4-767d-49aa-8752-015ee33f5421');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2210684c-420c-4e74-928c-87798fac4c24', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco está facultado a emitir informes comerciales de personas jurídicas y comerciantes inscritos en el Registro Mercantil, siempre y cuando la consulta se refiera a sus actividades comerciales. Sin embargo, el banco no podrá proveer información si ha recibido instrucciones al contrario del cliente. El banco emitirá informes comerciales sobre otras personas, en particular de clientes particulares y asociaciones, sólo en caso de que dichas personas, sea de forma general o particular, lo hayan autorizado expresamente. El banco sólo podrá emitir un informe comercial si el solicitante del informe acredita un interés legítimo en la información solicitada y si no existen motivos para suponer que la emisión pudiera atentar contra los legítimos intereses del cliente.</p>', '9ac95de4-767d-49aa-8752-015ee33f5421');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8311d153-a2d0-41be-828c-22a313e1abe6', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>2.4 Empfänger von Bankauskünften</h2>', '7dcdbfbb-018a-4452-9e05-4ba02a1433e5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('484fa8e9-da95-410f-9df4-368ea3010ec5', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>2.4 Recipients of disclosed banking affairs</h2>', '7dcdbfbb-018a-4452-9e05-4ba02a1433e5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('942d496d-52c7-46f2-ade9-dad242863175', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>2.4 Destinatarios de informes comerciales</h2>', '7dcdbfbb-018a-4452-9e05-4ba02a1433e5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6519c5c5-dd1c-4301-b2a1-d19a73470cc1', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Bankauskünfte erteilt die Bank nur eigenen Kunden sowie anderen Kreditinstituten für deren Zwecke oder die ihrer Kunden.</p>', '5469931f-91a0-4ed2-ace3-3cb7805a300a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('14a18e27-e963-47cd-9117-17f8473304ca', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank shall disclose details of banking affairs only to its own customers as well as to other credit institutions for their own purposes or those of their customers.</p>', '5469931f-91a0-4ed2-ace3-3cb7805a300a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d7e017eb-c52e-4f79-93b2-66007afaaf01', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco suministrará informes comerciales exclusivamente a clientes de su propia entidad y a otras entidades de crédito, para sus propios fines o para los fines de sus clientes.</p>', '5469931f-91a0-4ed2-ace3-3cb7805a300a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('47f7f4cb-d344-4944-a157-734e2671021c', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>3. Haftung der Bank; Mitverschulden des Kunden</h2>', '9c68fde6-a3d3-4272-bf5e-c64748bf3acf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3fd85f01-398f-4b02-a35d-cc34b35eed0d', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>3. Liability of the Bank; contributory negligence of the customer</h2>', '9c68fde6-a3d3-4272-bf5e-c64748bf3acf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5426c08e-2226-4ada-bd7a-5fe64cb6ef64', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>3. Responsabilidad del banco; concurrencia de culpabilidad del cliente</h2>', '9c68fde6-a3d3-4272-bf5e-c64748bf3acf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0e934e90-060f-44ff-88bd-fc7d7db1fcd0', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>3.1 Haftungsgrundsätze</h2>', 'd8f713a9-0d1e-498e-942d-30ee478f2c47');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0874c39a-6e2c-4076-bb30-e67ad383191d', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>3.1 Principles of liability</h2>', 'd8f713a9-0d1e-498e-942d-30ee478f2c47');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6774b5ce-6bbd-4b8b-8d69-78c67e36a372', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>3.1 Principios de responsabilidad</h2>', 'd8f713a9-0d1e-498e-942d-30ee478f2c47');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('51f25e6e-89a0-4fec-a6f3-83d562f049d5', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank haftet bei der Erfüllung ihrer Verpflichtungen für jedes Verschulden ihrer Mitarbeiter und der Personen, die sie zur Erfüllung ihrer Verpflichtungen hinzuzieht. Soweit die Sonderbedingungen für einzelne Geschäftsbeziehungen oder sonstige Vereinbarungen etwas Abweichendes regeln, gehen diese Regelungen vor. Hat der Kunde durch ein schuldhaftes Verhalten (zum Beispiel durch Verletzung der in Nr.11 dieser Geschäftsbedingungen aufgeführten Mitwirkungspflichten) zu der Entstehung eines Schadens beigetragen, bestimmt sich nach den Grundsätzen des Mitverschuldens, in welchem Umfang Bank und Kunde den Schaden zu tragen haben.</p>', 'dd47b76a-8e8a-41d9-90b7-06a724ccb213');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('39f6d9a2-4389-4f90-84db-f673fd6f5fd7', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>In performing its obligations, the Bank shall be liable for any negligence on the part of its staff and of those persons whom it may call in for the performance of its obligations. If the Special Conditions for particular business relations or other agreements contain provisions inconsistent herewith, such provisions shall prevail. In the event that the customer has contributed to the occurrence of the loss by any own fault (e.g. by violating the duties to cooperate as mentioned in No. 11 of these Business Conditions), the principles of contributory negligence shall determine the extent to which the Bank and the customer shall have to bear the loss.</p>', 'dd47b76a-8e8a-41d9-90b7-06a724ccb213');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ff53aabe-0ad5-4d67-8c58-ff84138f95b8', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco será responsable del incumplimiento de sus obligaciones por parte de sus empleados o terceras personas a las que haya delegado su ejecución. En los casos en que existan cláusulas específicas pactadas individualmente para determinados tipos de operaciones que difieran de las presentes Condiciones Generales de Contratación, prevalecerán las primeras. Si el cliente es también causante de daños y perjuicios acaecidos (por ej. por haber incumplido la obligación de cooperar, dispuesta en la cláusula 11 de las presentes Condiciones Generales de Contratación), se determinará, en proporción a la concurrencia de culpa, las partes que correspondan asumir al banco y al cliente en la indemnización de los daños y perjuicios causados.</p>', 'dd47b76a-8e8a-41d9-90b7-06a724ccb213');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('682a73d2-4164-41db-bc36-2ba717617544', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>3.2 Weitergeleitete Aufträge</h2>', '63d0ed59-155e-42c1-b1e3-503bfb933907');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('19a59bb8-edc6-4b27-bb35-b662dcc94042', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>3.2 Orders passed on to third parties</h2>', '63d0ed59-155e-42c1-b1e3-503bfb933907');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('829b32a1-8ca1-4fbf-adbe-f4c03fe759a1', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>3.2 Ordenes transferidas a terceros</h2>', '63d0ed59-155e-42c1-b1e3-503bfb933907');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('94f56240-9b67-4352-95c2-9ace8939d959', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Wenn ein Auftrag seinem Inhalt nach typischerweise in der Form ausgeführt wird, dass die Bank einen Dritten mit der weiteren Erledigung betraut, erfüllt die Bank den Auftrag dadurch, dass sie ihn im eigenen Namen an den Dritten weiterleitet (weitergeleiteter Auftrag). Dies betrifft zum Beispiel die Einholung von Bankauskünften bei anderen Kreditinstituten oder die Verwahrung und Verwaltung von Wertpapieren im Ausland. In diesen Fällen beschränkt sich die Haftung der Bank auf die sorgfältige Auswahl und Unterweisung des Dritten.</p>', 'fcb05ab9-6b4b-40f8-b6b5-4ff0798da454');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4020f346-23f1-4965-9c06-5d5821db0db4', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the contents of an order are such that the Bank typically entrusts a third party with its further execution, the Bank performs the order by passing it on to the third party in its own name (order passed on to a third party). This applies, for example, to obtaining information on banking affairs from other credit institutions or to the custody and administration of securities in other countries. In such cases, the liability of the Bank shall be limited to the careful selection and instruction of the third party.</p>', 'fcb05ab9-6b4b-40f8-b6b5-4ff0798da454');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('22fcbe5b-d987-415c-964f-47c54ce1f558', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Para la ejecución de una orden que, por su naturaleza, se confía habitualmente a terceros, el banco habrá cumplido su compromiso contractual encargando en nombre propio la ejecución de la orden al tercero (orden transferida a terceros). Son ejemplos de estas órdenes la solicitud de información a otras entidades de crédito o la custodia y administración de valores mobiliarios fuera de Alemania. En estos casos, la responsabilidad del banco se limitará a la escrupulosa selección e instrucción del tercero.</p>', 'fcb05ab9-6b4b-40f8-b6b5-4ff0798da454');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ccf108e0-f3c4-4704-83d1-84d58a4c09e3', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>3.3 Störung des Betriebs</h2>', '1fd88b9a-3817-4a13-8853-9377eb9677bc');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7be34cce-7094-4f16-870c-303e5dca2026', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>3.3 Disturbance of business</h2>', '1fd88b9a-3817-4a13-8853-9377eb9677bc');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('19e3c404-4f4e-454d-8e62-43ded4dfad28', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>3.3 Trastornos en el funcionamiento de los servicios</h2>', '1fd88b9a-3817-4a13-8853-9377eb9677bc');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2917d8df-3d28-4324-b7ef-98d4f3c89010', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank haftet nicht für Schäden, die durch höhere Gewalt, Aufruhr, Kriegs- und Naturereignisse oder durch sonstige von ihr nicht zu vertretende Vorkommnisse (zum Beispiel Streik, Aussperrung, Verkehrsstörung, Verfügungen von hoher Hand im In- oder Ausland) eintreten.</p>', '5b4905b6-1e66-440c-9b03-b2bcc394541b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3106b5c0-fef8-460d-8e1e-dae452acd05e', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank shall not be liable for any losses caused by force majeure, riot, war or natural events or due to other occurrences for which the Bank is not responsible (e.g. strike, lock-out, traffic hold-ups, administrative acts of domestic or foreign high authorities).</p>', '5b4905b6-1e66-440c-9b03-b2bcc394541b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e57ac161-aca0-42a5-b48b-04e2d5a4a999', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco no responderá por daños y perjuicios causados por fuerza mayor, disturbios o tumultos, acontecimientos bélicos, naturales o por otras causas cuya responsabilidad no sea atribuible al banco (por ejemplo: huelgas, cierres patronales, dificultades de transporte, actos administrativos de autoridades públicas de Alemania o de otros países).</p>', '5b4905b6-1e66-440c-9b03-b2bcc394541b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f7517518-c9f3-4b53-a2ce-7165520b504f', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>4. Grenzen der Aufrechnungsbefugnis des Kunden, der kein Verbraucher ist</h2>', '5edfbbaf-7049-4ef5-b674-96eb6a36b143');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5972ac97-d6b6-4cf3-ab94-b7e209cc8d43', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>4. Set-off limitations on the part of the customer who is not a consumer</h2>', '5edfbbaf-7049-4ef5-b674-96eb6a36b143');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('252734ff-2175-44e1-b6ed-4a23fe1f5204', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>4. Limitaciones del cliente no consumidor a posibilidades de compensación recíproca</h2>', '5edfbbaf-7049-4ef5-b674-96eb6a36b143');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0791deb6-896b-49d8-bb72-19fa05d2d774', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Ein Kunde, der kein Verbraucher ist, kann gegen Forderungen der Bank nur aufrechnen, wenn seine Forderungen unbestritten oder rechtskräftig festgestellt sind. Diese Aufrechnungsbeschränkung gilt nicht für eine vom Kunden zur Aufrechnung gestellte Forderung, die ihren Rechtsgrund in einem Darlehen oder einer Finanzierungshilfe gemäß §§ 513, 491 bis 512 BGB hat.</p>', '90b975c3-4e4d-433f-8db9-6cfdcd2e0eb3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('abad9814-43eb-4ef5-8c95-6c4a9dacb354', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>A non-consumer customer may only set off claims against those of the Bank if the customer&#39;s claims are undisputed or have been confirmed by a final court decision. This set-off limitation shall not apply to any claim for which offsetting is invoked by the client that has its legal basis in a loan or financial support pursuant to Sections 513 and 491-512 of the German Civil Code [BGB].</p>', '90b975c3-4e4d-433f-8db9-6cfdcd2e0eb3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0cb523dd-9981-4589-8d17-7e5151a63b2d', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El cliente que no sea un consumidor sólo podrá liquidar deudas frente al banco mediante compensación si las deudas del banco frente al cliente tienen carácter definitivo y firme. Dicha restricción del derecho a liquidar mediante compensación no se aplicará en deudas cuya compensación plantee el cliente y que tengan su fundamento jurídico en un préstamo o asistencia financiera conforme a los arts. 513 y de 491 a 512 del Código Civil Alemán [BGB].</p>', '90b975c3-4e4d-433f-8db9-6cfdcd2e0eb3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('263af393-53bd-4293-92ee-2095d66cf4ca', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>5. Verfügungsberechtigung nach dem Tod des Kunden</h2>', '596619c3-5357-477b-86c5-e863f17dd57f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c2ebe2ef-8199-4299-8265-1352706dc481', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>5. Right of disposal upon the death of the customer</h2>', '596619c3-5357-477b-86c5-e863f17dd57f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d9e5c0f1-5e13-47a1-954c-ecd357eb5856', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>5. Derechos de disposición después del fallecimiento del cliente</h2>', '596619c3-5357-477b-86c5-e863f17dd57f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7d5fae25-8683-4cd3-b7d3-ef4033e6c8e1', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Nach dem Tod des Kunden hat derjenige, der sich gegenüber der Bank auf die Rechtsnachfolge des Kunden beruft, der Bank seine erbrechtliche Berechtigung in geeigneter Weise nachzuweisen. Wird der Bank eine Ausfertigung oder eine beglaubigte Abschrift der letztwilligen Verfügung (Testament, Erbvertrag) nebst zugehöriger Eröffnungsniederschrift vorgelegt, darf die Bank denjenigen, der darin als Erbe oder Testamentsvollstrecker bezeichnet ist, als Berechtigten ansehen, ihn verfügen lassen und insbesondere mit befreiender Wirkung an ihn leisten. Dies gilt nicht, wenn der Bank bekannt ist, dass der dort Genannte (zum Beispiel nach Anfechtung oder wegen Nichtigkeit des Testaments) nicht verfügungsberechtigt ist oder wenn ihr dies infolge Fahrlässigkeit nicht bekannt geworden ist.</p>', '712083ab-30ac-4da2-9c73-7d22817d3ce9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a0b8169a-64a6-4506-8331-8b4055f5db78', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Upon the death of the customer, any person who approaches the Bank claiming to be the customer&#39;s legal successor shall be required to furnish suitable proof to the Bank of their entitlement under inheritance law. If an official or certified copy of the testamentary disposition (last will or contract of inheritance) together with the relevant record of probate proceedings is presented to the Bank, the Bank may consider any person designated therein as heir or executor as the entitled person, allow this person to dispose of any assets and, in particular, make payment or delivery to this person, thereby discharging its obligations. This shall not apply if the Bank is aware that the person designated therein is not entitled to dispose (e.g. following challenge or invalidity of the will) or if this has not come to the knowledge of the Bank due to its own negligence.</p>', '712083ab-30ac-4da2-9c73-7d22817d3ce9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4bbf28dc-cab3-42aa-adf3-9b87444589cc', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>En caso de fallecimiento del cliente, el banco podrá exigir la presentación de los documentos pertinentes para los poderes de disposición. El banco podrá considerar como heredero prescindiendo de la presentación de títulos de heredero o del certificado de ejecución de testamento a cambio de la presentación de un ejemplar original o copia autenticada de la última voluntad del cliente (testamento o contrato sucesorio), acompañada del respectivo documento que acredite la apertura del proceso de declaración sucesoria. El banco está autorizado a considerar que la persona que en dichos documentos sea designada como heredero o albacea de la herencia, detenta el poder de disposición sobre los bienes, permitiéndole disponer sobre éstos y ejecutando.</p>', '712083ab-30ac-4da2-9c73-7d22817d3ce9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a2473c1b-e963-49c7-9ed1-73549f28f4bb', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>6. Maßgebliches Recht und Gerichtsstand bei kaufmännischen und öffentlich-rechtlichen Kunden</h2>', '59029d74-7a8d-4963-b0e1-24c845feb240');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0de22992-849c-4ebd-b778-aa831d622e5a', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>6. Applicable law and place of jurisdiction for customers who are businesspersons or public-law entities</h2>', '59029d74-7a8d-4963-b0e1-24c845feb240');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6efdea3e-0e2e-42a0-8f44-faa19509d3d6', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>6. Legislación aplicable y tribunales competentes en caso de clientes comerciantes y entidades de derecho público</h2>', '59029d74-7a8d-4963-b0e1-24c845feb240');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fc71aa6f-6704-460f-b015-28d7f909054a', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>6.1 Geltung deutschen Rechts</h2>', '1e227b9b-2fed-4069-b336-401e15561868');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7b3613cf-a253-4c09-aaee-a4437739a02e', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>6.1 Applicability of German law</h2>', '1e227b9b-2fed-4069-b336-401e15561868');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('65241d1e-34c5-4360-9615-24db2add3559', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>6.1 Aplicación de la legislación alemana</h2>', '1e227b9b-2fed-4069-b336-401e15561868');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a7a666a5-0781-4434-9c6e-e38241b25292', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Für die Geschäftsverbindung zwischen dem Kunden und der Bank gilt deutsches Recht.</p>', '8ac9d906-9ac9-42f1-8f06-023be944810c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('dd0f12f5-c909-4155-9f68-6436b76f05ae', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>German law shall apply to the business relationship between the customer and the Bank.</p>', '8ac9d906-9ac9-42f1-8f06-023be944810c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('98e2538f-8f07-4bb7-9005-79e9a845d659', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Se aplicará la legislación alemana a todas las relaciones contractuales entre el cliente y el banco.</p>', '8ac9d906-9ac9-42f1-8f06-023be944810c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('74715c33-f6bf-400a-82ef-d3132e3ec458', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>6.2 Gerichtsstand für Inlandskunden</h2>', 'd02ddaf8-f61c-46ef-952b-f36900b2893a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fb562da6-9215-4a01-8a7f-052a4204b29e', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>6.2 Place of jurisdiction for domestic customers</h2>', 'd02ddaf8-f61c-46ef-952b-f36900b2893a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4ec3fbca-4fe7-4f71-b197-5b0bb32d66bc', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>6.2 Tribunales competentes en caso de clientes residentes en Alemania</h2>', 'd02ddaf8-f61c-46ef-952b-f36900b2893a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a2167a4b-10f0-4c8c-ae61-333926976278', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Ist der Kunde ein Kaufmann und ist die streitige Geschäftsbeziehung dem Betriebe seines Handelsgewerbes zuzurechnen, so kann die Bank diesen Kunden an dem für die kontoführende Stelle zuständigen Gericht oder bei einem anderen zuständigen Gericht verklagen; dasselbe gilt für öffentlich-rechtliche juristische Personen und öffentlich-rechtliche Sondervermögen. Die Bank selbst kann von diesen Kunden nur an dem für die kontoführende Stelle zuständigen Gericht verklagt werden.</p>', '707dece4-9a78-4d46-b460-2342ec24b5fb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('503ed8de-6450-47a6-9958-3261ecfaefc2', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the customer is a businessperson and if the business relation in dispute is attributable to the conducting of such businessperson&#39;s trade, the Bank may sue such customer before the court having jurisdiction for the bank office keeping the account or before any other competent court; the same applies to legal entities under public law and separate funds under public law. The Bank itself may be sued by such customers only before the court having jurisdiction for the bank office keeping the account.</p>', '707dece4-9a78-4d46-b460-2342ec24b5fb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c7cc7c0c-f5da-4d9e-aa5a-efa7b36fb3da', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si el cliente es un comerciante inscrito como tal en el Registro Mercantil y la operación objeto del litigio es imputable a su actividad comercial, el banco podrá demandar judicialmente a este cliente ante el tribunal competente para el domicilio del establecimiento bancario que administra y mantiene su cuenta o ante cualquier otro tribunal competente; lo mismo se aplicará a entidades de derecho público o entidades que administren patrimonios especiales del Estado. El cliente sólo podrá demandar judicialmente al banco ante el tribunal competente para el domicilio de la oficina bancaria que administra y mantiene su cuenta.</p>', '707dece4-9a78-4d46-b460-2342ec24b5fb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('cea1b7c9-4cd3-41d2-948c-963a52f12980', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>6.3 Gerichtsstand für Auslandskunden</h2>', '933bebe3-3dcd-4822-8f8c-228363fce4d4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('40756e44-292e-4ffe-b3a0-ee736771868c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>6.3 Place of jurisdiction for foreign customers</h2>', '933bebe3-3dcd-4822-8f8c-228363fce4d4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3b7bf9bd-3a24-407e-b3fc-55f5bf677b6c', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>6.3 Tribunales competentes en caso de clientes no residentes en Alemania</h2>', '933bebe3-3dcd-4822-8f8c-228363fce4d4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9fbc40b8-a69f-4a7e-a833-fc7b2e112f06', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Gerichtsstandsvereinbarung gilt auch für Kunden, die im Ausland eine vergleichbare gewerbliche Tätigkeit ausüben, sowie für ausländische Institutionen, die mit inländischen juristischen Personen des öffentlichen Rechts oder mit einem inländischen öffentlich-rechtlichen Sondervermögen vergleichbar sind.</p>', 'f47adda7-8e7b-4072-98be-5c364b9a60dd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8d699da1-0219-40c1-836f-55f6761626b6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The agreement upon the place of jurisdiction shall also apply to customers who conduct a comparable trade or business abroad and to foreign institutions which are comparable with domestic legal entities under public law or a domestic separate fund under public law.</p>', 'f47adda7-8e7b-4072-98be-5c364b9a60dd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('de7e44cd-a9b3-4d11-b21e-677bd09347d4', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Lo estipulado en el apartado anterior se extenderá a aquellos clientes que ejerzan una actividad comercial equivalente fuera de Alemania, así como a aquellas entidades con domicilio fuera de Alemania que sean equivalentes a entidades de derecho público en Alemania o a entidades con domicilio en Alemania que administren patrimonios especiales del Estado.</p>', 'f47adda7-8e7b-4072-98be-5c364b9a60dd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('33583487-2459-41e7-89b7-f99e0f610ff5', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Kontoführung</h2>', 'fc3afde6-4d07-4ef9-a4e0-56c24b404571');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('01a7288e-4267-4ad1-b18d-583a27159dae', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Keeping of Accounts</h2>', 'fc3afde6-4d07-4ef9-a4e0-56c24b404571');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('657a4e0f-afa0-4087-bbc0-3d967a7be9c0', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Administración de cuentas</h2>', 'fc3afde6-4d07-4ef9-a4e0-56c24b404571');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('813d06c7-206f-4c13-bf5a-fca83da507d6', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Rechnungsabschlüsse bei Kontokorrentkonten (Konten in laufender Rechnung)</h2>', '5773a50f-176f-4a29-afb9-4ab66d7bfb51');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('43ece728-4798-4b79-9a1b-526ec99754a3', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Periodic balance statements for current accounts</h2>', '5773a50f-176f-4a29-afb9-4ab66d7bfb51');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b65a6e56-1b3e-4fce-b37d-e5ff53a0ddca', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Liquidación de cuentas corrientes (cuentas contables corrientes)</h2>', '5773a50f-176f-4a29-afb9-4ab66d7bfb51');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f9edad89-6013-4322-b028-1c6f2f189beb', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>7. Erteilung der Rechnungsabschlüsse</h2>', 'd805a118-46ac-432b-a947-8474ede289fa');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9febfc5e-9988-4fc5-8645-cf5175b765c8', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>7. Issue of periodic balance statements</h2>', 'd805a118-46ac-432b-a947-8474ede289fa');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('91800567-e89a-44c3-a67c-f45082e3bb79', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>7. Concesión de liquidaciones de cuentas</h2>', 'd805a118-46ac-432b-a947-8474ede289fa');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('90d28274-b6b8-4572-9186-73e62ac4d2a9', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>7.1 Die Bank erteilt bei einem Kontokorrentkonto, sofern nicht etwas anderes vereinbart ist, jeweils zum Ende eines Kalenderquartals einen Rechnungsabschluss; dabei werden die in diesem Zeitraum entstandenen beiderseitigen Ansprüche (einschließlich der Zinsen und Entgelte der Bank) verrechnet. Die Bank kann auf den Saldo, der sich aus der Verrechnung ergibt, nach Nr. 12 dieser Geschäftsbedingungen oder nach der mit dem Kunden anderweitig getroffenen Vereinbarung Zinsen berechnen.</p>', '947843e7-58ff-4a1b-b89b-08668ecf0f10');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('58a8fc1c-cf0b-431a-945a-18e3816a69e2', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>7.1 Unless otherwise agreed, the Bank shall issue a periodic balance statement for a current account at the end of each calendar quarter, thereby clearing the claims accrued by both parties during this period (including interest and charges imposed by the Bank). The Bank may charge interest on the balance arising therefrom in accordance with No. 12 of these Business Conditions or any other agreements entered into with the customer.</p>', '947843e7-58ff-4a1b-b89b-08668ecf0f10');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ce471522-b710-4805-b34b-44cfe78c2938', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>7.1 Salvo que las partes hayan pactado algo diferente, al final de cada trimestre, el banco facilitará al cliente una liquidación de cuentas, en la que se liquidarán las deudas contraídas mutuamente originadas durante el respectivo periodo (incluyendo intereses y devengos del banco). El banco podrá facturar intereses sobre el saldo resultante de esta liquidación, de acuerdo con lo establecido en el artículo 12 de las presentes Condiciones Generales de Contratación o según lo pactado con el cliente.</p>', '947843e7-58ff-4a1b-b89b-08668ecf0f10');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7f0fd3cf-d276-4dbf-93ba-136bdfd01631', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>7.2 Frist für Einwendungen; Genehmigung durch Schweigen</h2>', '1b48bd57-affa-4afb-9d21-4ce0364e705c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('325a148e-484b-4f04-bbc3-5593433e8d78', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>7.2 Time allowed for objections; approval by silence</h2>', '1b48bd57-affa-4afb-9d21-4ce0364e705c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('82c87f1d-6793-4a18-ab3a-39b9381f79b8', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>7.2 Plazo para remitir objeciones, consentimiento tácito</h2>', '1b48bd57-affa-4afb-9d21-4ce0364e705c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('85010017-ff88-498e-90cf-38f17781993b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Einwendungen wegen Unrichtigkeit oder Unvollständigkeit eines Rechnungsabschlusses hat der Kunde spätestens vor Ablauf von sechs Wochen nach dessen Zugang zu erheben; macht er seine Einwendungen in Textform geltend, genügt die Absendung innerhalb der Sechs-Wochen-Frist. Das Unterlassen rechtzeitiger Einwendungen gilt als Genehmigung. Auf diese Folge wird die Bank bei Erteilung des Rechnungsabschlusses besonders hinweisen. Der Kunde kann auch nach Fristablauf eine Berichtigung des Rechnungsabschlusses verlangen, muss dann aber beweisen, dass zu Unrecht sein Konto belastet oder eine ihm zustehende Gutschrift nicht erteilt wurde.</p>', '9b23955c-370c-4a5a-bb73-3a4e520c810c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3bf8475a-9e00-4858-8921-2bce284ab794', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Any objections a customer may have concerning the incorrectness or incompleteness of a periodic balance statement must be raised not later than six weeks after its receipt; if the objections are made in text form, it is sufficient to dispatch these within the period of six weeks. Failure to make objections in due time shall be considered as approval. When issuing the periodic balance statement, the Bank shall expressly draw the customer&#39;s attention to this consequence. The customer may demand a correction of the periodic balance statement even after expiry of this period, but must then prove that the account was either wrongly debited or mistakenly not credited.</p>', '9b23955c-370c-4a5a-bb73-3a4e520c810c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a914e884-d28b-484c-b17c-45e5f30c8064', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Cualquier objeción que tenga el cliente por liquidación indebida o incompleta, deberá ser remitida en un plazo de seis semanas a contar desde la fecha del acuse de recibo de la liquidación. Si el cliente remite su objeción en forma textual, basta que se haya enviado dentro del plazo de seis semanas. Si el cliente no remite su objeción en el plazo previsto, se considerará que ha otorgado tácitamente su consentimiento a la liquidación. Al conceder la liquidación de cuentas, el banco advertirá expresamente al cliente de tal consecuencia. El cliente podrá exigir que se corrija la liquidación de la cuenta, incluso después de haber expirado este plazo, si comprueba la existencia de un error en recargos en cuenta o en abonos no concedidos.</p>', '9b23955c-370c-4a5a-bb73-3a4e520c810c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('df819d14-5917-4edc-98dc-34658656228b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p id="footnote-1"><sup>1</sup> Bankarbeitstage sind alle Werktage außer Sonnabende, 24. und 31. Dezember</p>', '2e7e89f0-3c63-4799-be73-e6c6c54cb4bd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('99ef9132-46d1-48fc-9a79-3a3607484f9d', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p id="footnote-1"><sup>1</sup> Bank Working Days are all working days except for Saturdays, December 24 and 31</p>', '2e7e89f0-3c63-4799-be73-e6c6c54cb4bd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1ff92e05-d5e9-4c34-af76-f47c4a76f6ae', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p id="footnote-1"><sup>1</sup> Los días hábiles bancarios son todos los días laborables, excepto sábados y los días 24 y 31 de diciembre</p>', '2e7e89f0-3c63-4799-be73-e6c6c54cb4bd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('023fc340-5a4c-40c8-8f2a-0833d247e6e5', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p id="footnote-2"><sup>2</sup> International Bank Account Number (Internationale Bankkontonummer)</p>', '23a7599c-5ade-48d4-99e5-4e081bc7dbdd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5ae47bbf-8ba1-4c04-bc87-0cd46724456c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p id="footnote-2"><sup>2</sup> International Bank Account Number</p>', '23a7599c-5ade-48d4-99e5-4e081bc7dbdd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b0fa8b78-d690-4fb2-bdfb-ab1c409e50d3', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p id="footnote-2"><sup>2</sup> International Bank Account Number (Número internacional de cuenta bancaria)</p>', '23a7599c-5ade-48d4-99e5-4e081bc7dbdd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('07b35bb4-28f6-4e0c-afb7-9fd7b2c7a399', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p id="footnote-3"><sup>3</sup> Bank Identifier Code (Bank-Identifizierungs-Code)</p>', '7f39a461-d7db-4c65-ba95-60b2e0a8ca26');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('12a10bae-d118-4d1d-8124-b1765fc0f0f6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p id="footnote-3"><sup>3</sup> Bank Identifier Code</p>', '7f39a461-d7db-4c65-ba95-60b2e0a8ca26');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('49db2659-93b3-469f-a378-ec7764651ac0', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p id="footnote-3"><sup>3</sup> Bank Identifier Code (Código bancario de identificación)</p>', '7f39a461-d7db-4c65-ba95-60b2e0a8ca26');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6fe91ed5-caab-4a3f-980a-c7490cc78a28', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>8. Storno- und Berichtigungsbuchungen der Bank</h2>', '71179695-03cd-4886-9400-52dd0ffbdb1e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6d784dee-15c5-4c0b-857a-52775de11924', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>8. Reverse entries and correction entries made by the Bank</h2>', '71179695-03cd-4886-9400-52dd0ffbdb1e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3f56ee81-088f-40a4-940e-c56f6ec2e2a3', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>8. Asientos de revocación y asientos de rectificación del banco</h2>', '71179695-03cd-4886-9400-52dd0ffbdb1e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4c35c319-0c2e-4e94-9858-22367ea50b5b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>8.1 Vor Rechnungsabschluss</h2>', 'bc922c9c-1a8f-462f-a781-7a382597f033');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1ece0cc2-165a-43cf-9a79-94f926f13be0', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>8.1 Prior to issuing a periodic balance statement</h2>', 'bc922c9c-1a8f-462f-a781-7a382597f033');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0c7e3519-1035-414b-8cad-909b3863ad76', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>8.1 Antes de la liquidación del saldo en cuenta</h2>', 'bc922c9c-1a8f-462f-a781-7a382597f033');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6a1290f5-b829-4673-896b-4c49d1d985d6', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Fehlerhafte Gutschriften auf Kontokorrentkonten (zum Beispiel wegen einer falschen Kontonummer) darf die Bank bis zum nächsten Rechnungsabschluss durch eine Belastungsbuchung rückgängig machen, soweit ihr ein Rückzahlungsanspruch gegen den Kunden zusteht (Stornobuchung); der Kunde kann in diesem Fall gegen die Belastungsbuchung nicht einwenden, dass er in Höhe der Gutschrift bereits verfügt hat.</p>', '7b9a7799-a993-4fcf-96d0-4ff5913fb947');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e633b192-a28b-4d30-adcd-27c0fa8ddddf', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Incorrect credit entries on current accounts (e.g. due to a wrong account number) may be reversed by the Bank through a debit entry prior to the issue of the next periodic balance statement to the extent that the Bank has a repayment claim against the customer (reverse entry); in this case, the customer may not object to the debit entry on the grounds that a disposal of an amount equivalent to the credit entry has already been made.</p>', '7b9a7799-a993-4fcf-96d0-4ff5913fb947');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('22d27591-c275-43ce-aa5d-6e476937a227', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Hasta la siguiente liquidación del saldo en cuenta, el banco podrá revocar mediante asientos de débito los importes abonados indebidamente (por ejemplo porque el número de cuenta era incorrecto), hasta el valor por el que el banco pueda exigir la devolución al cliente (asiento de revocación); en este caso, el cliente no podrá pronunciarse en contra del cargo en cuenta aduciendo que ya había dispuesto del importe indebidamente acreditado.</p>', '7b9a7799-a993-4fcf-96d0-4ff5913fb947');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('51dc5c1b-ffb5-456a-b25a-804841c5d1f8', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>8.2 Nach Rechnungsabschluss</h2>', 'f394cac6-75d4-4438-9c16-254d5f34d4d7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d9de6d43-edca-4919-828f-2a22aabdb19f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>8.2 After issuing a periodic balance statement</h2>', 'f394cac6-75d4-4438-9c16-254d5f34d4d7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e5fb64d6-e672-437a-855c-f8a65e7dcfb1', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>8.2 Después de la liquidación del saldo en cuenta</h2>', 'f394cac6-75d4-4438-9c16-254d5f34d4d7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bdfcfa02-9169-4e21-acc8-cba1a8109574', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Stellt die Bank eine fehlerhafte Gutschrift erst nach einem Rechnungsabschluss fest und steht ihr ein Rückzahlungsanspruch gegen den Kunden zu, so wird sie in Höhe ihres Anspruchs sein Konto belasten (Berichtigungsbuchung). Erhebt der Kunde gegen die Berichtigungsbuchung Einwendungen, so wird die Bank den Betrag dem Konto wieder gutschreiben und ihren Rückzahlungsanspruch gesondert geltend machen.</p>', '16c037a7-9a95-4b3b-8348-96b82fe2eb5f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ab756f34-76a2-4878-9de5-413b75873c6a', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the Bank ascertains an incorrect credit entry after a periodic balance statement has been issued and if the Bank has a repayment claim against the customer, it shall debit the account of the customer with the amount of its claim (correction entry). If the customer objects to the correction entry, the Bank shall re-credit the account with the amount in dispute and assert its repayment claim separately.</p>', '16c037a7-9a95-4b3b-8348-96b82fe2eb5f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c89f1940-5cf8-4ec1-9517-2b7431d1c3a0', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si el banco constata que se ha acreditado indebidamente un importe después de la liquidación del saldo en cuenta y puede exigir la devolución al cliente, podrá cargar la cuenta por el importe correspondiente (asiento de rectificación). Si el cliente se pronuncia en contra del asiento de rectificación, el banco volverá a abonar el importe en la cuenta y reclamará por separado su derecho a la devolución.</p>', '16c037a7-9a95-4b3b-8348-96b82fe2eb5f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8d0b125a-397d-4bfe-be67-404d60a93e3f', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>8.3 Information des Kunden; Zinsberechnung</h2>', 'bd41def1-c335-4db4-8995-9c1b447e66a6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9c205bc8-04cc-4a17-9cde-295fc4db1373', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>8.3 Notification to the customer; calculation of interest</h2>', 'bd41def1-c335-4db4-8995-9c1b447e66a6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7ac047b1-c9bd-43f0-9d2e-dc0c2bd2fed5', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>8.3 Información al cliente; devengo de intereses</h2>', 'bd41def1-c335-4db4-8995-9c1b447e66a6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('76af4e0c-577a-4f72-896d-14022134d9e9', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Über Storno- und Berichtigungsbuchungen wird die Bank den Kunden unverzüglich unterrichten. Die Buchungen nimmt die Bank hinsichtlich der Zinsberechnung rückwirkend zu dem Tag vor, an dem die fehlerhafte Buchung durchgeführt wurde.</p>', 'd6c86c99-1d27-4406-beb8-adf80606722d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e59653ae-7df0-482f-8562-69648c653463', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank shall immediately notify the customer of any reverse entries and correction entries made. With respect to the calculation of interest, the Bank shall effect the entries retroactively as of the day on which the incorrect entry was made.</p>', 'd6c86c99-1d27-4406-beb8-adf80606722d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('25128063-3bf6-48d3-b6c2-b06581824744', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco notificará al cliente sin demora cualquier asiento de revocación y/o rectificación que haya realizado. El banco calculará los intereses devengados con efecto retroactivo a la fecha en que se cargó el importe en la cuenta.</p>', 'd6c86c99-1d27-4406-beb8-adf80606722d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('aa273e86-3548-42c0-97ff-10b628c57a97', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>9. Einzugsaufträge</h2>', '87bfa760-b410-4beb-a596-17ac6606b55a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ff863872-3665-48db-81a8-8eb056fdb261', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>9. Collection orders</h2>', '87bfa760-b410-4beb-a596-17ac6606b55a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('873670b8-ea82-471a-beea-4ab026fb1800', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>9. Ordenes de adeudo</h2>', '87bfa760-b410-4beb-a596-17ac6606b55a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bbfd6587-e1ff-42f3-bf13-2683d77a7741', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>9.1 Erteilung von Vorbehaltsgutschriften bei der Einreichung</h2>', '20aa917d-7fdc-438d-886d-17fd7e9041e9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b72a7d46-d496-48d1-8bc7-66e57d110344', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>9.1 Conditional credit entries effected upon presentation of documents</h2>', '20aa917d-7fdc-438d-886d-17fd7e9041e9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d1fb9b83-de52-4f73-8f73-62f4cbaccb06', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>9.1 Concesión de abonos bajo reserva durante la presentación</h2>', '20aa917d-7fdc-438d-886d-17fd7e9041e9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3f64847e-4db5-4273-82c3-a8e0443156fe', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Schreibt die Bank den Gegenwert von Schecks und Lastschriften schon vor ihrer Einlösung gut, geschieht dies unter dem Vorbehalt ihrer Einlösung, und zwar auch dann, wenn diese bei der Bank selbst zahlbar sind. Reicht der Kunde andere Papiere mit dem Auftrag ein, von einem Zahlungspflichtigen einen Forderungsbetrag zu beschaffen (zum Beispiel Zinsscheine), und erteilt die Bank über den Betrag eine Gutschrift, so steht diese unter dem Vorbehalt, dass die Bank den Betrag erhält. Der Vorbehalt gilt auch dann, wenn die Schecks, Lastschriften und anderen Papiere bei der Bank selbst zahlbar sind.</p>', '9dee4458-6fae-4430-ba29-4eaaf7d56f18');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5ccae78c-7176-48df-bf51-ec783c362ba6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the Bank credits the countervalue of cheques and direct debits prior to their payment, this is done on condition of payment, even if these items are payable at the Bank itself. If the customer surrenders other items, instructing the Bank to collect an amount due from a debtor (e.g. interest coupons), and if the Bank effects a credit entry for such amount, this is done under the reserve that the Bank shall obtain the amount. This reserve shall also apply if the cheques, direct debits and other items are payable at the Bank itself. If cheques or direct debits are not paid or if the Bank does not obtain the amount under the collection order, the Bank shall cancel the conditional credit entry regardless of whether or not a periodic balance statement has been issued in the meantime.</p>', '9dee4458-6fae-4430-ba29-4eaaf7d56f18');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1e976c8b-d243-49b0-ab1c-e6c1614ab5b3', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si el banco abona al cliente el contravalor de cheques o adeudos antes de hacerlos efectivos, ello se realizará bajo reserva de su pago, incluso cuando sean pagaderos en el mismo banco. Si el cliente presenta otros documentos con la orden de cobrar un importe de un deudor (por ejemplo cupones de intereses), y si el banco concede un abono por ese importe, éste estará también sometido a la salvedad, de que el banco reciba el importe. La salvedad también es aplicable, cuando los cheques, adeudos y otros documentos son pagaderos en el mismo banco. Si quedaran cheques o adeudos impagados o si el banco no recibe el importe de la orden de adeudo, el banco anulará el abono bajo salvedad, aunque entretanto ya se haya concedido la liquidación el cierre de la cuenta.</p>', '9dee4458-6fae-4430-ba29-4eaaf7d56f18');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('51ae106e-0146-4fe6-b8d0-bb9937e20850', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>9.2 Einlösung von Lastschriften und vom Kunden ausgestellter Schecks</h2>', '7ab2b823-8551-4f4d-9ea4-e85dead4a0b1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('57e7a5de-9030-4758-86cf-99ef8a0f37ec', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>9.2 Payment of direct debits and of cheques made out by the customer</h2>', '7ab2b823-8551-4f4d-9ea4-e85dead4a0b1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('aafbb694-d1ad-4d5b-8252-6b38c496ac1f', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>9.2 Pago de adeudos y de cheques expedidos por el cliente</h2>', '7ab2b823-8551-4f4d-9ea4-e85dead4a0b1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3104b7b1-ad85-4a9a-bd01-06921d205a41', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Lastschriften sowie Schecks sind eingelöst, wenn die Belastungsbuchung nicht spätestens am zweiten Bankarbeitstag<sup><a href="#footnote-1">1</a></sup> – bei SEPA-Firmenlastschriften nicht spätestens am dritten Bankarbeitstag – nach ihrer Vornahme rückgängig gemacht wird. Barschecks sind bereits mit Zahlung an den Scheckvorleger eingelöst. Schecks sind auch schon dann eingelöst, wenn die Bank im Einzelfall eine Bezahltmeldung absendet. Schecks, die über die Abrechnungsstelle der Bundesbank vorgelegt werden, sind eingelöst, wenn sie nicht bis zu dem von der Bundesbank festgesetzten Zeitpunkt zurückgegeben werden.</p>', '9039dd8c-b46c-49b8-9b87-3db4586fbf20');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6f852b37-ed91-4b18-946c-93bf27d7f45d', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Direct debits and cheques shall be deemed to have been paid, unless the debit entry is cancelled prior to the end of the second bank working day<sup><a href="#footnote-1">1</a></sup> – in the case of SEPA business-to-business (B2B) direct debits, prior to the end of the third bank working day – after it was made. Cash cheques shall already be deemed to have been paid once the amount has been paid to the presenting party. Cheques shall also be deemed to have been paid as soon as the Bank dispatches a paid-message in an individual case. Cheques presented through the Bundesbank clearing office shall be deemed to have been paid unless they are returned by the time set by the Bundesbank.</p>', '9039dd8c-b46c-49b8-9b87-3db4586fbf20');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b8a95deb-1656-42c9-b036-6fc7104c4d84', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Los recibos de adeudo así como los cheques se consideraran pagados si el adeudo a cuenta no es anulado a mas tardar el segundo día hábil bancario<sup><a href="#footnote-1">1</a></sup> – o el tercer día en caso de recibos de adeudo SEPA – posterior a su asiento. Los cheques pagaderos en efectivo quedaran pagados ya al abonarlos al portador. Los cheques también se consideraran pagados, cuando el banco en cada caso particular envíe un aviso de pagado. Los cheques que se presenten a través de la Oficina de compensaciones del Bundesbank, se consideraran pagados si no son devueltos hasta el momento fijado por el Bundesbank.</p>', '9039dd8c-b46c-49b8-9b87-3db4586fbf20');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('cc33edad-fdc9-4e74-b66f-1d449c84f209', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Fremdwährungsgeschäfte und Risiken bei Fremdwährungskonten</h2>', '296437b8-e056-40e8-b13b-accc12597431');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('507d81a5-c1fa-4049-8f66-d1a2c30f3eae', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Foreign currency transactions and risks inherent in foreign currency accounts</h2>', '296437b8-e056-40e8-b13b-accc12597431');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('42078d4d-96e8-443f-a94e-5299dcbdc39b', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Operaciones en moneda extranjera y riesgos relacionados con las cuentas en moneda extranjera</h2>', '296437b8-e056-40e8-b13b-accc12597431');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c4a672c0-8a46-4d4b-8be6-6ff81614e13d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>10. Auftragsausführung bei Fremdwährungskonten</h2>', '0f454dce-faa6-49bf-97cc-229b5635f875');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6e5af03d-7c55-4bfe-90c8-ef9fc85d4cea', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>10. Execution of orders relating to foreign currency accounts</h2>', '0f454dce-faa6-49bf-97cc-229b5635f875');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2ef7e06e-f20e-4dfa-a29b-5a3dffb5f2e4', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>10. Ejecución de órdenes en cuentas en moneda extranjera</h2>', '0f454dce-faa6-49bf-97cc-229b5635f875');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6e30dd3f-2246-40ea-95b1-af4d2dbd8c00', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>10.1 Fremdwährungskonten des Kunden dienen dazu, Zahlungen an den Kunden und Verfügungen des Kunden in fremder Währung bargeldlos abzuwickeln. Verfügungen über Guthaben auf Fremdwährungskonten (zum Beispiel durch Überweisungen zu Lasten des Fremdwährungsguthabens) werden unter Einschaltung von Banken im Heimatland der Währung abgewickelt, wenn sie die Bank nicht vollständig innerhalb des eigenen Hauses ausführt.</p>', 'fc295b4f-53e9-4d76-9ff5-c150d712df4c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('72155aa1-ba7b-41e4-812b-316fe767ed54', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Foreign currency accounts of the customer serve to effect the cashless settlement of payments to and disposals by the customer in foreign currency. Disposals of credit balances on foreign currency accounts (e.g. by means of credit transfers to the debit of the foreign currency credit balance) are settled through or by banks in the home country of the currency unless the Bank executes them entirely within its own organisation.</p>', 'fc295b4f-53e9-4d76-9ff5-c150d712df4c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('af701d28-a629-4150-ad3d-bfe5af4ac811', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Las cuentas en moneda extranjera del cliente permiten efectuar pagos al cliente y aplicar disposiciones del cliente en moneda extranjera sin dinero en efectivo. Las disposiciones sobre el saldo en cuentas en moneda extranjera (por ejemplo, por transferencias a cargo del saldo en moneda extranjera) se llevarán a cabo con la intervención de bancos en el país de origen de la respectiva moneda, si es que el banco no las ejecuta por completo por sí mismo.</p>', 'fc295b4f-53e9-4d76-9ff5-c150d712df4c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6f9bb8bc-4064-447b-bdfc-69d90617dbbb', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>10.2 Gutschriften bei Fremdwährungsgeschäften mit dem Kunden</h2>', '89cb2930-6be3-4817-ac14-49c4fc3f15ea');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8cf574a4-600d-43af-b438-a90e62a66391', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Credit entries for foreign currency transactions with the Customer</h2>', '89cb2930-6be3-4817-ac14-49c4fc3f15ea');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3e43d2f0-c75b-4924-8abe-dac0b9d377ad', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>10.2 Abonos a cuenta en operaciones con el cliente en moneda extranjera</h2>', '89cb2930-6be3-4817-ac14-49c4fc3f15ea');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0be37386-cdef-4fdf-bc47-b23c6151de4b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Schließt die Bank mit dem Kunden ein Geschäft (zum Beispiel ein Devisentermingeschäft) ab, aus dem sie die Verschaffung eines Betrages in fremder Währung schuldet, wird sie ihre Fremdwährungsverbindlichkeit durch Gutschrift auf dem Konto des Kunden in dieser Währung erfüllen, sofern nicht etwas anderes vereinbart ist.</p>', '971efbde-0043-4888-8944-ecf1741a6daf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9a993c1e-5b0b-49db-b8d0-28f62378c7d3', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the Bank concludes a transaction with the customer (e.g. a forward exchange transaction) under which it owes the provision of an amount in a foreign currency, it shall discharge its foreign currency obligation by crediting the account of the customer in the respective currency, unless otherwise agreed.</p>', '971efbde-0043-4888-8944-ecf1741a6daf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1e3cb873-4558-42db-821b-d96fa7d464af', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si el banco acuerda una operación con el cliente (por ejemplo, de compra o de venta de divisas a plazo), de la cual deba poner a disposición cierto importe en moneda extranjera, cumplirá su compromiso, abonando ese importe en la moneda correspondiente a la cuenta del cliente, a no ser que se haya pactado otra cosa.</p>', '971efbde-0043-4888-8944-ecf1741a6daf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('83c38df7-43c7-47cc-ac08-04d820b9b40e', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>10.3 Vorübergehende Beschränkung der Leistung durch die Bank</h2>', '5de2c04e-3cea-41e9-9521-cab02a30059f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2fec3724-27b1-4849-adca-8a792d605f0f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>10.3 Temporary limitation of performance by the Bank</h2>', '5de2c04e-3cea-41e9-9521-cab02a30059f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5311524d-ebf5-436e-8af3-fd9feab485d7', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>10.3 Limitación transitoria de las prestaciones del banco</h2>', '5de2c04e-3cea-41e9-9521-cab02a30059f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3184e1df-5cf9-47fd-a395-d8f42f8c23e6', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Verpflichtung der Bank zur Ausführung einer Verfügung zu Lasten eines Fremdwährungsguthabens (Absatz 1) oder zur Erfüllung einer Fremdwährungsverbindlichkeit (Absatz 2) ist in dem Umfang und so lange ausgesetzt, wie die Bank in der Währung, auf die das Fremdwährungsguthaben oder die Verbindlichkeit lautet, wegen politisch bedingter Maßnahmen oder Ereignisse im Lande dieser Währung nicht oder nur eingeschränkt verfügen kann. In dem Umfang und solange diese Maßnahmen oder Ereignisse andauern, ist die Bank auch nicht zu einer Erfüllung an einem anderen Ort außerhalb des Landes der Währung, in einer anderen Währung (auch nicht in Euro) oder durch Anschaffung von Bargeld verpflichtet. Die Verpflichtung der Bank zur Ausführung einer Verfügung zu Lasten eines Fremdwährungsguthabens ist dagegen nicht ausgesetzt, wenn sie die Bank vollständig im eigenen Haus ausführen kann. Das Recht des Kunden und der Bank, fällige gegenseitige Forderungen in derselben Währung miteinander zu verrechnen, bleibt von den vorstehenden Regelungen unberührt.</p>', 'e24963a7-f76b-4f6b-bc9d-de8928bef2ff');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1c05cd37-646d-4a1a-a65c-f1f4d2f27246', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank&#39;s duty to execute a disposal order to the debit of a foreign currency credit balance (paragraph 1) or to discharge a foreign currency obligation (paragraph 2) shall be suspended to the extent that and for as long as the Bank cannot or can only restrictedly dispose of the currency in which the foreign currency credit balance or the obligation is denominated, due to political measures or events in the country of the respective currency. To the extent that and for as long as such measures or events persist, the Bank is not obligated either to perform at some other place outside the country of the respective currency, in some other currency (including euros) or by providing cash. However, the Bank&#39;s duty to execute a disposal order to the debit of a foreign currency credit balance shall not be suspended if the Bank can execute it entirely within its own organisation. The right of the customer and of the Bank to set off mutual claims due in the same currency against each other shall not be affected by the above provisions.</p>', 'e24963a7-f76b-4f6b-bc9d-de8928bef2ff');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c578a1af-d154-4b5f-9450-347a59923ad3', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>La obligación del banco de ejecutar una disposición con recargo a un saldo en moneda extranjera (apartado 1) o de cumplir un pago en moneda extranjera (apartado 2) quedará interrumpida en la medida y durante el tiempo en que el banco no pueda disponer, de forma total o parcial, de los fondos requeridos en la moneda extranjera en la que está expedida el saldo o la obligación de pago, como consecuencia de medidas políticas adoptadas o acontecimientos ocurridos en el país de dicha moneda. Durante el tiempo y en la medida en que dichas medidas o dichos acontecimientos subsistan, el banco tampoco estará obligado a cumplir sus obligaciones en otro lugar diferente al país de esa moneda, ni en una moneda diferente (tampoco en euros), ni mediante la aportación de dinero en efectivo. Sin embargo, la obligación del banco de ejecutar una orden a cargo de un saldo en moneda extranjera no quedará suspendida, si el banco puede efectuar la operación por completo de forma interna. Ello no afectará al derecho del cliente y del banco a compensar mutuamente deudas pagaderas en la misma moneda.</p>', 'e24963a7-f76b-4f6b-bc9d-de8928bef2ff');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d9253c17-0c8e-40b3-ad46-2a178d1a221c', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>10.4 Wechselkurs</h2>', '231d08c6-33dd-4bf8-b047-22009e5e2f42');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ded67757-dd9b-4251-8dd6-651b1eb146ca', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>10.4 Exchange rate</h2>', '231d08c6-33dd-4bf8-b047-22009e5e2f42');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('46cccd3a-46e3-48ad-8cdf-83b5779b1a8e', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>10.4 Tipo de cambio</h2>', '231d08c6-33dd-4bf8-b047-22009e5e2f42');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9d6bac80-6cc5-447c-a210-535f7c3b2b38', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bestimmung des Wechselkurses bei Fremdwährungsgeschäften ergibt sich aus dem &quot;Preis- und Leistungsverzeichnis&quot;. Bei Zahlungsdiensten gilt ergänzend der Zahlungsdiensterahmenvertrag.</p>', 'afbb1c16-1f54-4571-9c4b-bd7466b62953');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7cc15fdb-fe41-4334-bcc4-2ef1287205b2', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The exchange rate for foreign currency transactions shall be determined on the basis of the &quot;List of Prices and Services&quot; (Preisund Leistungsverzeichnis). Payment services shall be governed in addition by the payment services framework contract.</p>', 'afbb1c16-1f54-4571-9c4b-bd7466b62953');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('dea6fc4c-5cce-4629-9bec-ea06d0852b22', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>La determinación del tipo de cambio para las operaciones en moneda extranjera resulta de lo establecido en la &quot;Relación de precios y prestaciones&quot;. En el caso de los servicios de pago, se aplicará adicionalmente el contrato marco de servicios de pago.</p>', 'afbb1c16-1f54-4571-9c4b-bd7466b62953');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5f8a11d2-134d-4f07-b53f-953dffabb3a5', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Mitwirkungspflichten des Kunden</h2>', 'dbb75c77-9b64-42fc-97d1-68beae7465d5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d8cfd5ad-fe33-4755-be48-9cb4808fc96f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Duties of the customer to cooperate</h2>', 'dbb75c77-9b64-42fc-97d1-68beae7465d5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('53222545-ab9d-4544-a900-716656b4b3b3', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Obligaciones de cooperación del cliente</h2>', 'dbb75c77-9b64-42fc-97d1-68beae7465d5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b42b0fb3-e38e-43ba-8c73-a08045021ad7', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>11. Mitwirkungspflichten des Kunden</h2>', '153f6150-d2c6-4834-be8a-3530eedcbf6b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0b53d2fa-9a2d-4495-b4de-16dbd9f74862', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>11. Duties of the Customer to Cooperate</h2>', '153f6150-d2c6-4834-be8a-3530eedcbf6b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('35e23c73-2bd2-44e0-8df2-ed09b6e16b14', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>11. Obligaciones de cooperación del cliente</h2>', '153f6150-d2c6-4834-be8a-3530eedcbf6b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('43174cee-3620-4b63-9c6d-c5a91a5ffc7f', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>11.1 Mitteilung von Änderungen</h2>', 'bd434a28-0723-493d-b9b2-6eec6e0c44d0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fde8c222-29b7-4b24-aeb4-08432976d7f4', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>11.1 Notification of changes</h2>', 'bd434a28-0723-493d-b9b2-6eec6e0c44d0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bfaf06f8-7f52-4caf-ac49-680a1acd6092', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>11.1 Comunicación de los cambios</h2>', 'bd434a28-0723-493d-b9b2-6eec6e0c44d0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ad776b1d-bbde-4c77-84e5-9fa03568d250', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Zur ordnungsgemäßen Abwicklung des Geschäftsverkehrs ist es erforderlich, dass der Kunde der Bank Änderungen seines Namens und seiner Anschrift sowie das Erlöschen oder die Änderung einer gegenüber der Bank erteilten Vertretungsmacht (insbesondere einer Vollmacht) unverzüglich mitteilt. Diese Mitteilungspflicht besteht auch dann, wenn die Vertretungsmacht in ein öffentliches Register (zum Beispiel in das Handelsregister) eingetragen ist und ihr Erlöschen oder ihre Änderung in dieses Register eingetragen wird. Darüber hinaus können sich weitergehende gesetzliche Mitteilungspflichten, insbesondere aus dem Geldwäschegesetz, ergeben.</p>', '11519ca5-ba06-4a6f-a2b4-b15487faaa50');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('cdbc0a6d-9be4-4726-b214-8213aa2d1d0c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>A proper settlement of business requires that the customer notify the Bank without delay of any changes in the customer&#39;s name and address, as well as the termination of, or amendment to, any powers of representation towards the Bank conferred to any person (in particular, a power of attorney). This notification duty also exists where the powers of representation are recorded in a public register (e.g. the Commercial Register) and any termination thereof or any amendments thereto are entered in that register. Additional statutory notification requirements, resulting from the German Money Laundering Act (Geldwäschegesetz), in particular may apply.</p>', '11519ca5-ba06-4a6f-a2b4-b15487faaa50');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('499e5ae5-2c65-4ce7-9892-d070ce0f0d5f', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Para la adecuada gestión de las transacciones, es necesario que el cliente informe inmediatamente al banco de cualquier cambio de su nombre o de su domicilio, así como de la extinción o modificación de un poder de representación otorgado frente al banco a favor de una persona (en particular, un poder). Esta obligación de informar es también aplicable al caso de que el poder de representación esté inscrito en un registro público (por ej. en el Registro Mercantil) y su extinción o modificación se haya inscrito en dicho registro. También pueden existir otras obligaciones legales de comunicación, especialmente derivadas de la Ley alemana contra el blanqueo de dinero.</p>', '11519ca5-ba06-4a6f-a2b4-b15487faaa50');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2e556b58-13a2-4ec7-adad-7a71ea38396b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>11.2 Klarheit von Aufträgen</h2>', '142cb909-eff5-4332-81b2-d6d123b8861b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fe048968-b519-4e00-b90e-9de50591a13c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>11.2 Clarity of orders</h2>', '142cb909-eff5-4332-81b2-d6d123b8861b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('69e8b46a-bc91-46d5-a466-ee676d085932', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>11.2 Claridad de las órdenes</h2>', '142cb909-eff5-4332-81b2-d6d123b8861b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f4492c3c-3747-43e1-a6e7-34c576019126', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Aufträge müssen ihren Inhalt zweifelsfrei erkennen lassen. Nicht eindeutig formulierte Aufträge können Rückfragen zur Folge haben, die zu Verzögerungen führen können. Vor allem hat der Kunde bei Aufträgen auf die Richtigkeit und Vollständigkeit seiner Angaben, insbesondere der Kontonummer und Bankleitzahl oder IBAN<sup><a href="#footnote-2">2</a></sup> und BIC<sup><a href="#footnote-3">3</a></sup> sowie der Währung zu achten. Änderungen, Bestätigungen oder Wiederholungen von Aufträgen müssen als solche gekennzeichnet sein.</p>', '98cc691c-8a01-4e27-8d25-412b1ed37309');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c44f52eb-61cd-4c1c-8b0a-7b24aa549075', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Orders must unequivocally show their contents. Orders that are not worded clearly may lead to queries, which may result in delays. In particular, when giving orders, the customer must ensure that the information the customer provides, particulary the domestic account number bank and code number (&quot;Bankleitzahl&quot;) or IBAN<sup><a href="#footnote-2">2</a></sup> and BIC<sup><a href="#footnote-3">3</a></sup> and the currency, are complete and correct. Amendments, confirmations or repetitions of orders must be designated as such.</p>', '98cc691c-8a01-4e27-8d25-412b1ed37309');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('766d8ea3-27d7-4e2d-aa6a-aece88911344', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El contenido de las órdenes deberá ser inequívoco. Si una orden no está formulada de forma clara, puede haber consultas que pueden originar demoras. En las órdenes, el cliente deberá cerciorarse especialmente de que los datos son exactos y completos, en especial el número de cuenta y el código bancario o el IBAN<sup><a href="#footnote-2">2</a></sup> y el BIC<sup><a href="#footnote-3">3</a></sup>, asi como la moneda dada. Toda modificación, confirmación o repetición de órdenes deberá estar definida como tal.</p>', '98cc691c-8a01-4e27-8d25-412b1ed37309');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5d3d33cc-f09b-4015-8020-f3c3b0a103e7', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>11.3 Besonderer Hinweis bei Eilbedürftigkeit der Ausführung eines Auftrags</h2>', 'd068c12b-f022-478d-ae10-956c4f14cdb2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('190cd1cc-9d3b-42bc-94ab-a8de25410031', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>11.3 Special reference to urgency in connection with the execution of an order or a credit transfer</h2>', 'd068c12b-f022-478d-ae10-956c4f14cdb2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c7f8ea13-2308-494d-97f7-64f7c06b9b96', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>11.3 Indicación especial en caso de urgencia en la ejecución de órdenes</h2>', 'd068c12b-f022-478d-ae10-956c4f14cdb2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6683623c-bb8c-4cec-b60b-96f42af64c68', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Hält der Kunde bei der Ausführung eines Auftrags besondere Eile für nötig, hat er dies der Bank gesondert mitzuteilen. Bei formularmäßig erteilten Aufträgen muss dies außerhalb des Formulars erfolgen.</p>', 'f086f772-ef38-40c2-9115-d5e29b1e8b53');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4227a64b-466d-4fee-89aa-de18a2778424', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the customer feels that an order requires particularly prompt execution, the customer shall notify the Bank of this fact separately. For orders issued on a printed form, this must be done separately from the form.</p>', 'f086f772-ef38-40c2-9115-d5e29b1e8b53');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('eac8a4db-f35f-4feb-b3e0-305ed6a9c103', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si el cliente considera necesario que una orden se efectúe de forma urgente, deberá indicarlo al banco por separado. En las órdenes concedidas mediante formulario, ello deberá indicarse de forma ajena al formulario.</p>', 'f086f772-ef38-40c2-9115-d5e29b1e8b53');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5d2231f1-ffb0-4da7-b3e7-078d1adbb245', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>11.4 Prüfung und Einwendungen bei Mitteilungen der Bank</h2>', 'b71037d5-5b9d-4ea1-9cf6-99581de26b40');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('364d740e-8a54-4a8e-8a3e-f37d2aa768a9', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>11.4 Examination of, and objections to, notification received from the Bank</h2>', 'b71037d5-5b9d-4ea1-9cf6-99581de26b40');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('185116af-d8b3-4000-b1b5-4498c0111992', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>11.4 Revisión y objeciones de comunicados del banco</h2>', 'b71037d5-5b9d-4ea1-9cf6-99581de26b40');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('346cadad-b489-4b9b-8f23-ea2a56d4602c', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Der Kunde hat Kontoauszüge, Wertpapierabrechnungen, Depot- und Erträgnisaufstellungen, sonstige Abrechnungen, Anzeigen über die Ausführung von Aufträgen sowie Informationen über erwartete Zahlungen und Sendungen (Avise) auf ihre Richtigkeit und Vollständigkeit unverzüglich zu überprüfen und etwaige Einwendungen unverzüglich zu erheben.</p>', '69c2b205-5915-4b5b-b8f3-a7f886136ae8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7d425c85-16f3-473c-816b-76f9a0da4a6f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The customer must immediately examine account statements, securities contract notes, statements of securities holdings and earnings, other statements, advices of execution of orders, as well as information on expected payments and consignments (advices), as to their correctness and completeness and immediately raise any objections relating thereto.</p>', '69c2b205-5915-4b5b-b8f3-a7f886136ae8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('350f47d8-fa2f-4a87-a8a3-8272524d4d25', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El cliente deberá verificar sin demora que los extractos de la cuenta, las liquidaciones de valores, las presentaciones de depósitos y de réditos, demás liquidaciones, avisos de ejecución de órdenes, así como la información sobre pagos y remesas esperadas (avisos) son correctos y completos, y comunicar sin demora eventuales quejas.</p>', '69c2b205-5915-4b5b-b8f3-a7f886136ae8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('717aec5c-abe0-48c5-9ffd-cd9da19115e5', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>11.5 Benachrichtigung der Bank bei Ausbleiben von Mitteilungen</h2>', 'a976e41e-ac03-43ab-89f5-c63c6a5f785b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9203a037-8160-483d-ae59-a67ee64512ae', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>11.5 Notice to the Bank in case of non-receipt of statements</h2>', 'a976e41e-ac03-43ab-89f5-c63c6a5f785b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ff1cda48-571e-4ded-b361-99bf1edbddb5', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>11.5 Aviso al banco por falta de comunicados</h2>', 'a976e41e-ac03-43ab-89f5-c63c6a5f785b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bed92d6a-caf7-4870-9020-d30ea1f4b281', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Falls Rechnungsabschlüsse und Depotaufstellungen dem Kunden nicht zugehen, muss er die Bank unverzüglich benachrichtigen. Die Benachrichtigungspflicht besteht auch beim Ausbleiben anderer Mitteilungen, deren Eingang der Kunde erwartet (Wertpapierabrechnungen, Kontoauszüge nach der Ausführung von Aufträgen des Kunden oder über Zahlungen, die der Kunde erwartet).</p>', '68335400-66d6-4bc4-ae6d-a05dd18dec10');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ebf05216-054c-4c3d-8521-1e174a59a0f4', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The customer must notify the Bank immediately if periodic balance statements and statements of securities holdings are not received. The duty to notify the Bank also exists if other advices expected by the customer are not received (e.g. securities contract notes, account statements after execution of customer orders or regarding payments expected by the customer).</p>', '68335400-66d6-4bc4-ae6d-a05dd18dec10');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e8bd81a3-1613-4fbb-9e91-9e6ba2da5836', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El cliente deberá notificar inmediatamente al banco si no recibe liquidaciones contables o relaciones de depósitos La obligación de notificar también existe al no recibir otros comunicados que el cliente espera (liquidaciones de valores, extractos de cuenta tras la ejecución de órdenes del cliente o de pagos que el cliente espera).</p>', '68335400-66d6-4bc4-ae6d-a05dd18dec10');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('be8d1236-f3e1-4a62-a932-e9bdacab373b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Kosten der Bankdienstleistungen</h2>', '39c9780c-b608-4230-8ffd-6ce1c9809083');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ae16049c-6a59-444c-804f-4e30c46c443e', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Cost of Bank Services</h2>', '39c9780c-b608-4230-8ffd-6ce1c9809083');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0520f4fc-f3b3-4f3a-8819-2ceb05193f11', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Comisiones y gastos de los servicios del banco</h2>', '39c9780c-b608-4230-8ffd-6ce1c9809083');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ead82f3a-cf57-44fb-83b2-2bea27095d39', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Zinsen, Entgelte und Aufwendungen</h2>', 'a863b260-d64f-4d61-9163-8d5be05c87d4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('63da2162-43d9-4893-9785-213b50385a66', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>12. Interest, charges and expenses</h2>', 'a863b260-d64f-4d61-9163-8d5be05c87d4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5cc2a29b-34c2-40e1-b0fc-bbc265b98f4d', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>12. Intereses, retribuciones y gastos</h2>', 'a863b260-d64f-4d61-9163-8d5be05c87d4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('25447b66-02a5-4f4d-8a6a-7540513eb82c', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>12.1 Zinsen und Entgelte im Geschäft mit Verbrauchern</h2>', '4526fd79-d7aa-4f99-8a29-e3016388c720');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fb0eee07-f708-45c1-8f8d-3d2419168df4', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>12.1 Interest and charges in business with consumers</h2>', '4526fd79-d7aa-4f99-8a29-e3016388c720');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('56e230dd-8bcf-4c39-8b6b-2e75edeac233', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>12.1 Intereses y devengos en operaciones con clientes particulares</h2>', '4526fd79-d7aa-4f99-8a29-e3016388c720');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c071bbae-2433-43f1-a826-6b4f07755249', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Höhe der Zinsen und Entgelte für die üblichen Bankleistungen, die die Bank gegenüber Verbrauchern erbringt, einschließlich der Höhe von Zahlungen, die über die für die Hauptleistung vereinbarten Entgelte hinausgehen, ergeben sich aus dem &quot;Preisaushang – Regelsätze im standardisierten Privatkundengeschäft&quot; und aus dem &quot;Preis- und Leistungsverzeichnis&quot;. Wenn ein Verbraucher eine dort aufgeführte Hauptleistung in Anspruch nimmt und dabei keine abweichende Vereinbarung getroffen wurde, gelten die zu diesem Zeitpunkt im Preisaushang oder Preis- und Leistungsverzeichnis angegebenen Zinsen und Entgelte. Eine Vereinbarung, die auf eine über das vereinbarte Entgelt für die Hauptleistung hinausgehende Zahlung des Verbrauchers gerichtet ist, kann die Bank mit dem Verbraucher nur ausdrücklich treffen, auch wenn sie im &quot;Preisaushang&quot; oder im &quot;Preis- und Leistungsverzeichnis&quot; ausgewiesen ist. Für die Vergütung der nicht im &quot;Preisaushang&quot; oder im &quot;Preisund Leistungsverzeichnis&quot; aufgeführten Leistungen, die im Auftrag des Verbrauchers erbracht werden und die, nach den Umständen zu urteilen, nur gegen eine Vergütung zu erwarten sind, gelten, soweit keine andere Vereinbarung getroffen wurde, die gesetzlichen Vorschriften.</p>', '778d3c1a-44a0-4d71-b05a-1184668b1de0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c5b4d2c9-4c37-4364-ac9c-e889438bfc05', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The amount of interest and charges for the customary services which the Bank provides to consumers, including the amount of any payments in addition to the remuneration agreed for the principal service, is set out in the &quot;Price Display – Standard rates for retail banking&quot; (Preisaushang – Regelsätze im standardisierten Privatkundengeschäft) and the &quot;List of Prices and Services&quot; (Preis- und Leistungsverzeichnis). If a customer makes use of a service included therein, and unless otherwise agreed between the Bank and the customer, the interest and charges stated in the then valid Price Display or &quot;List of Prices and Services&quot; are applicable. Any agreement that concerns a payment made by the consumer in addition to the remuneration agreed for the principal service must be expressly concluded by the Bank with the consumer, even if such payment is stated in the Price Display or the &quot;List of Prices and Services&quot;. Unless otherwise agreed, the charges for any services not included in the Price Display or the &quot;List of Prices and Services&quot; which are provided following the instructions of the customer and which can, in the given circumstances, only be expected to be provided against remuneration, shall be governed by the relevant statutory provisions.</p>', '778d3c1a-44a0-4d71-b05a-1184668b1de0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('396467bc-10bb-4db8-9bb1-c81c47b2fdd4', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El importe de los intereses y los devengos usuales para servicios bancarios a clientes particulares incluyendo los pagos de las retribuciones acordadas más allá del servicio principal resultan del &quot;Folleto de Comisiones y Gastos – Tarifas aplicables a las operaciones usuales con clientes particulares&quot; y de la &quot;Relación de precios y prestaciones&quot;. Si un cliente retira el importe de un crédito y no se hubiera acordado nada divergente, se aplicarán los intereses y comisiones indicados en el folleto de comisiones y la relación de precios y prestaciones en la actualidad. Un acuerdo destinado a un pago superior del cliente más allá de la retribución acordada respecto del crédito pueden tomarlo el banco y el cliente expresamente sólo cuando esto se indique en el Folleto de Comisiones y la Relación de precios y prestaciones. Salvo que las partes hayan pactado algo diferente, la retribución de cualquier otro servicio que no figure en dichas listas, pero cuya prestación se haya realizado por solicitud del cliente, o presumiendo de que se realiza en interés de éste, y que, a juzgar por las circunstancias, se espere que solo podrán ser prestados a cambio de una retribución, se regirá por la normativa legal.</p>', '778d3c1a-44a0-4d71-b05a-1184668b1de0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c3344076-ede7-4857-a4a4-afeede43433e', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>12.2 Zinsen und Entgelte im Geschäft mit Kunden, die keine Verbraucher sind</h2>', '8c62ac57-eab9-4d40-b347-3e7a1796a518');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a7877c43-c744-4a19-9375-b4319c77cc8f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>12.2 Interest and charges in business with customers who are not consumers</h2>', '8c62ac57-eab9-4d40-b347-3e7a1796a518');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('337f95c2-50c4-4f48-94ba-74e169da1482', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>12.2 Tipos de intereses y comisiones en operaciones con clientes diferentes a los particulares</h2>', '8c62ac57-eab9-4d40-b347-3e7a1796a518');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f4b6f476-de8b-4d20-b451-38be806d0bac', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Höhe der Zinsen und Entgelte für die üblichen Bankleistungen, die die Bank gegenüber Kunden, die keine Verbraucher sind, erbringt, ergeben sich aus dem &quot;Preisaushang – Regelsätze im standardisierten Privatkundengeschäft&quot; und aus dem &quot;Preis- und Leistungsverzeichnis&quot;, soweit der &quot;Preisaushang&quot; und das &quot;Preis- und Leistungsverzeichnis&quot; übliche Bankleistungen gegenüber Kunden, die keine Verbraucher sind (z.B. Geschäftskunden), ausweisen. Wenn ein Kunde, der kein Verbraucher ist, eine dort aufgeführte Bankleistung in Anspruch nimmt und dabei keine abweichende Vereinbarung getroffen wurde, gelten die zu diesem Zeitpunkt im &quot;Preisaushang&quot; oder &quot;Preis- und Leistungsverzeichnis&quot; angegebenen Zinsen und Entgelte. Im Übrigen bestimmt die Bank, sofern keine andere Vereinbarung getroffen wurde und gesetzliche Bestimmungen dem nicht entgegenstehen, die Höhe von Zinsen und Entgelten nach billigem Ermessen (§ 315 des Bürgerlichen Gesetzbuchs).</p>', '96582821-e66a-4b6e-ae5a-50f432f11eb6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6ad8d39b-a9ab-44e9-829b-97c3c81b3a3f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The amount of interest and charges for the customary banking services which the Bank provides to customers who are not consumers is set out in the &quot;Price Display – Standard rates for retail banking&quot; (Preisaushang – Regelsätze im standardisierten Privatkundengeschäft) and the &quot;List of Prices and Services&quot; (Preis- und Leistungsverzeichnis), provided that the Price Display and the &quot;List of Prices and Services&quot; include customary banking services to customers who are not consumers (e.g. business customers). If a customer who is not a consumer makes use of a service included therein, and unless otherwise agreed between the Bank and the customer, the interest and charges stated in the then valid Price Display or &quot;List of Prices and Services&quot; are applicable. Otherwise, in the absence of any other agreement or conflict with statutory provisions, the Bank shall determine the amount of interest and charges at its reasonable discretion (Section 315 of the German Civil Code [Bürgerliches Gesetzbuch – BGB]).</p>', '96582821-e66a-4b6e-ae5a-50f432f11eb6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('eefd92bf-cd46-4446-b69d-9e291bc0834b', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Los intereses y retribuciones relativos a las operaciones con clientes diferentes a los particulares, el resultan del &quot;Folleto de Comisiones y Gastos – Tarifas aplicables a las operaciones usuales con clientes particulares&quot; y de la &quot;Relación de precios y prestaciones&quot;, siempre que el folleto y la relación contengan servicios bancarios usuales para clientes diferentes a los particulares (por ej. clientes comerciales). Por lo demás, siempre que no se hayan tomado acuerdos divergentes y nada lo contradiga legalmente, el banco determinará los intereses y retribuciones o devengos de forma razonable (art. 315 del Código Civil alemán).</p>', '96582821-e66a-4b6e-ae5a-50f432f11eb6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8226f481-c73c-40b9-afc5-ac4592b1c043', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>12.3 Nicht entgeltfähige Leistungen</h2>', 'f71e3908-a200-419f-98bf-9b9eebc53858');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1f3c14dc-0cf1-4559-8d25-9004c7ab4d38', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>12.3 Non-chargeable service</h2>', 'f71e3908-a200-419f-98bf-9b9eebc53858');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('124632fa-478e-4570-b4a5-0b1165b52eeb', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>12.3 Servicios no remunerables</h2>', 'f71e3908-a200-419f-98bf-9b9eebc53858');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0d32acef-9cb2-4be9-9485-d2ebd926c94d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Für eine Leistung, zu deren Erbringung die Bank kraft Gesetzes oder aufgrund einer vertraglichen Nebenpflicht verpflichtet ist oder die sie im eigenen Interesse wahrnimmt, wird die Bank kein Entgelt berechnen, es sei denn, es ist gesetzlich zulässig und wird nach Maßgabe der gesetzlichen Regelung erhoben.</p>', '04e7fc81-f0b2-4dfd-a9fa-c5c1c8209d19');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('10d814d3-0dd6-408d-b1b9-da7c4d9c3290', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank shall not charge for any service which it is required to provide by law or pursuant to a contractual accessory obligation or which it performs in its own interest, unless such charge is legally permissible and levied in accordance with the relevant statutory provisions.</p>', '04e7fc81-f0b2-4dfd-a9fa-c5c1c8209d19');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0654a450-0b9f-4eea-9135-a07d08594a47', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco no percibirá ninguna comisión por los servicios que en virtud de ley o por una obligación contractual, adicional esté obligado a prestar o que considere de su interés, salvo que esté legalmente permitido y dicha comisión se establezca con arreglo a las normas legales.</p>', '04e7fc81-f0b2-4dfd-a9fa-c5c1c8209d19');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('36037edf-a2cd-49af-8b27-4b5f615f20a9', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>12.4 Änderung von Zinsen; Kündigungsrecht des Kunden bei Erhöhung</h2>', '629dee1a-09d3-4d9f-8d28-6fcbb5327c2e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8f2528ad-a59d-4970-bbb0-7a47c855c2d9', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>12.4 Changes in interest rates; right of termination by the customer in the event of an increase</h2>', '629dee1a-09d3-4d9f-8d28-6fcbb5327c2e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('19239e11-1f43-4190-9aca-6f5e7b2e32db', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>12.4 Cambios en intereses y derecho del cliente de resolución del contrato ante su aumento</h2>', '629dee1a-09d3-4d9f-8d28-6fcbb5327c2e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('672c9300-2644-4a56-897a-b46586f6ee02', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Änderung der Zinsen bei Krediten mit einem veränderlichen Zinssatz erfolgt aufgrund der jeweiligen Kreditvereinbarung mit dem Kunden. Die Bank wird dem Kunden Änderungen von Zinsen mitteilen. Bei einer Erhöhung kann der Kunde, sofern nichts anderes vereinbart ist, die davon betroffene Kreditvereinbarung innerhalb von sechs Wochen nach der Bekanntgabe der Änderung mit sofortiger Wirkung kündigen. Kündigt der Kunde, so werden die erhöhten Zinsen für die gekündigte Kreditvereinbarung nicht zugrunde gelegt. Die Bank wird zur Abwicklung eine angemessene Frist einräumen.</p>', 'e5153651-8629-4d74-a9df-c4e025fe98c0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b8eafecb-eaa2-4180-9aac-d1a0137808f7', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>In the case of variable interest rate loans, the interest rate shall be adjusted in accordance with the terms of the respective loan agreement. The Bank shall notify the customer of any interest rate adjustments. If the interest rate is increased, the customer may, unless otherwise agreed, terminate the loan agreement affected thereby with immediate effect within six weeks from notification of the change. If the customer terminates the loan agreement, any such increased interest rate shall not be applied to the terminated loan agreement. The Bank shall allow a reasonable period of time for settlement.</p>', 'e5153651-8629-4d74-a9df-c4e025fe98c0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('be5bba7c-c284-4ee8-95ea-43ae925eb58c', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si las partes han acordado un crédito con tipo de interés variable, éste se modificará de acuerdo con los acuerdos de crédito con el cliente. El banco informará al cliente sobre cualquier modificación en los tipos de interés. Si el banco aumenta los intereses, el cliente dispone de seis semanas, a contar desde la fecha de notificación de la modificación, para rescindir, con efecto inmediato, el contrato de crédito afectado por el aumento de precio, salvo que las partes hayan acordado algo diferente. Si el cliente rescinde la relación contractual, los tipos de interés elevados no se aplicarán al contrato de crédito rescindido. El banco concederá un plazo razonable para la liquidación del contrato afectado.</p>', 'e5153651-8629-4d74-a9df-c4e025fe98c0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2c4d6ced-8193-4110-9702-f7bb34e7706a', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>12.5 Änderungen von Entgelten bei typischerweise dauerhaft in Anspruch genommenen Leistungen</h2>', 'f497b5b0-4cdd-47b8-99c9-40eeef0ced75');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('587ad5f5-43dd-482f-a89e-3498faf1f11c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>12.5 Changes in charges for services typically used on a permanent basis</h2>', 'f497b5b0-4cdd-47b8-99c9-40eeef0ced75');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fff78bf6-9ea7-493f-8889-c2adb6c2f88d', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>12.5 Cambios en los devengos por servicios típicamente utilizados de forma permanente</h2>', 'f497b5b0-4cdd-47b8-99c9-40eeef0ced75');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6c2ce955-1a25-434b-951c-5bae7b8291b1', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Änderungen von Entgelten für Bankleistungen, die von Kunden im Rahmen der Geschäftsverbindung typischerweise dauerhaft in Anspruch genommen werden (z.B. Konto- und Depotführung), werden dem Kunden spätestens zwei Monate vor dem vorgeschlagenen Zeitpunkt ihres Wirksamwerdens in Textform angeboten. Hat der Kunde mit der Bank im Rahmen der Geschäftsbeziehung einen elektronischen Kommunikationsweg vereinbart (z. B. das Online-Banking), können die Änderungen auch auf diesem Wege angeboten werden. Die von der Bank angebotenen Änderungen werden nur wirksam, wenn der Kunde diese annimmt. Eine Vereinbarung über die Änderung eines Entgelts, das auf eine über die Hauptleistung hinausgehende Zahlung eines Verbrauchers gerichtet ist, kann die Bank mit dem Verbraucher nur ausdrücklich treffen.</p>', 'ffc86447-f552-4aba-8120-eff08dae29c3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6eea2531-4796-4669-aee1-230c647802e3', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Changes in charges for banking services which are typically used by customers within the framework of the business relationship on a permanent basis (e.g. account/securities account management) shall be offered to the customer in text form no later than two months before their proposed date of entry into force. If the customer has agreed an electronic communication channel (e.g. online banking) with the Bank within the framework of the business relationship, the changes may also be offered through this channel. The changes offered by the Bank shall only become effective if the customer accepts them. Any agreement on amending a charge that concerns a payment by the consumer in excess of the charge for the principal service can only be expressly concluded with the consumer by the Bank.</p>', 'ffc86447-f552-4aba-8120-eff08dae29c3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('11e0aebb-351b-48c7-a72b-26eb732d07d6', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Los cambios en los devengos por aquellos servicios que, por su naturaleza, sean utilizados de forma permanente por el cliente en el ámbito de sus operaciones bancarias (p. ej. cuentas corrientes y custodia de valores), serán comunicados al cliente en forma textual con una antelación mínima de dos meses con respecto a la fecha designada para que tomen efecto. Si el cliente y el banco han convenido un sistema electrónico de comunicación en el ámbito de las relaciones comerciales (por ejemplo: banca electrónica), los cambios que se realicen también podrán ser comunicados por este sistema. Los cambios ofrecidos por el banco solo entrarán en vigor si el cliente los acepta. El banco puede hacer un cambio en una remuneración que vaya más allá del pago del consumidor acordado como servicio principal, solo con el acuerdo expreso del cliente.</p>', 'ffc86447-f552-4aba-8120-eff08dae29c3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('23b17f22-1d51-4fa0-849c-1a216c66023c', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>12.6 Ersatz von Aufwendungen</h2>', '55a5eca7-c711-4804-acfd-da8ace54cd0b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c7636716-7d49-4be6-9bad-e339be82bd41', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>12.6 Reimbursement of expenses</h2>', '55a5eca7-c711-4804-acfd-da8ace54cd0b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('dc0e0c22-2399-4354-8e92-e10e6f8f2953', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>12.6 Reposición de gastos</h2>', '55a5eca7-c711-4804-acfd-da8ace54cd0b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('12947761-3808-4bd2-81ea-0b66858e51bc', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Ein möglicher Anspruch der Bank auf Ersatz von Aufwendungen richtet sich nach den gesetzlichen Vorschriften.</p>', '3d335e42-385d-4bc5-9023-46fc1e8d97de');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('198ef693-5e8c-4278-9964-ac9a9412c887', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Any entitlement by the Bank to reimbursement of expenses shall be governed by the applicable statutory provisions.</p>', '3d335e42-385d-4bc5-9023-46fc1e8d97de');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('36b4c150-bc4e-4e63-94ec-12e67abff648', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco podrá tener derecho a una reposición de gastos conforme a las disposiciones legales.</p>', '3d335e42-385d-4bc5-9023-46fc1e8d97de');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('38f9a568-4207-4f19-8c75-148781d12e72', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>12.7 Besonderheiten bei Verbraucherdarlehensverträgen und Zahlungsdiensteverträgen mit Verbrauchern für Zahlungen innerhalb des Europäischen Wirtschaftsraums (EWR) in einer EWR-Währung</h2>', '031434f0-abcc-4220-a53f-c337c9106817');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('68494cc7-2fbb-4a6d-89f4-48d30cbec98f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>12.7 Special arrangements for consumer loan agreements and payment services contracts with consumers for payments</h2>', '031434f0-abcc-4220-a53f-c337c9106817');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b994e73a-1c45-4229-82af-284865f85c8c', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>12.7 Casos especiales para contratos de préstamo al consumidor y para contratos de servicios de pago con los consumidores por pagos</h2>', '031434f0-abcc-4220-a53f-c337c9106817');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0b9c56c7-dddf-4592-93a3-394bec039270', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Bei Verbraucherdarlehensverträgen und Zahlungsdiensteverträgen mit Verbrauchern für Zahlungen innerhalb des Europäischen Wirtschaftsraums (EWR) in einer EWR-Währung richten sich die Zinsen und die Kosten (Entgelte, Auslagen) nach den jeweiligen vertraglichen Vereinbarungen und Sonderbedingungen sowie ergänzend nach den gesetzlichen Vorschriften. Die Änderung von Entgelten von Zahlungsdiensterahmenverträgen (zum Beispiel Girovertrag) richtet sich nach Absatz 5.</p>', '9f0b1b26-ce78-4842-8f59-47d886b7e15c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5ca78700-5331-4c31-b640-2524330af5a6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The interest and costs (charges, out-of-pocket expenses) for consumer loan agreements and payment services contracts with consumers for payments shall be determined by the relevant contractual arrangements and Special Conditions as well as the additional statutory provisions. Changes in charges for payment services framework contracts (e.g. current account agreements) shall be governed by paragraph 5.</p>', '9f0b1b26-ce78-4842-8f59-47d886b7e15c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5ba5bd6d-e4a4-48af-bf74-36701e25c7f7', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>De servicios de pago con consumidores para pagos, el devengo de intereses y costes correspondientes (comisiones y gastos) se regirá por los correspondientes acuerdos contractuales y las cláusulas específicas, así como complementariamente por la normativa legal. El cambio en los devengos de contratos marco de servicios de pago (p. ej. contrato de cuenta corriente) se rige por el apartado 5.</p>', '9f0b1b26-ce78-4842-8f59-47d886b7e15c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1a166818-f680-43da-b751-a416966298fc', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Sicherheiten für die Ansprüche der Bank gegen den Kunden</h2>', 'afac25ee-520a-4369-8a9a-302b8a264c72');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3876dfcd-b4c5-41c0-b74b-a4c9b7eff621', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Security for the Bank&#39;s Claims against the Customer</h2>', 'afac25ee-520a-4369-8a9a-302b8a264c72');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('03ee9308-92d4-4ff4-b5c5-0905db496a1a', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Garantías de los derechos del banco frente al cliente</h2>', 'afac25ee-520a-4369-8a9a-302b8a264c72');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('01ec72a6-9090-429e-84e3-f10acdb7d3ac', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Bestellung oder Verstärkung von Sicherheiten</h2>', 'b351b3b1-cfe2-429f-8223-74d49e61499b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('809ebcde-d889-48f4-9992-153f11f29884', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Providing or increasing security</h2>', 'b351b3b1-cfe2-429f-8223-74d49e61499b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('edb2918b-cb4b-4cac-a072-a9e630b80309', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Constitución o refuerzo de garantías</h2>', 'b351b3b1-cfe2-429f-8223-74d49e61499b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('aaae817c-bb35-4f0b-aa83-1f2a48aaceba', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>13. Bestellung oder Verstärkung von Sicherheiten</h2>', 'dfb91bf8-35f8-447d-a6d5-7744d238b883');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ba3c0daf-701c-4b8b-80ab-34e581a70e74', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>13. Right of the Bank to request security</h2>', 'dfb91bf8-35f8-447d-a6d5-7744d238b883');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f5d5990a-7446-4efe-bad2-b7aafad7a9f0', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>13. Constitución o refuerzo de garantías</h2>', 'dfb91bf8-35f8-447d-a6d5-7744d238b883');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5edb5d22-5f3d-4b6d-9b32-783474025aee', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>13.1 Anspruch der Bank auf Bestellung von Sicherheiten</h2>', 'f8e4237a-888f-4871-b32a-13e1c75bd587');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('18f720ee-f6b7-47f9-ac4d-ceed01382c0e', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>13.1 Right of the Bank to request security</h2>', 'f8e4237a-888f-4871-b32a-13e1c75bd587');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1ceb1557-442a-4027-be0a-2062f04d1e76', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>13.1 Derecho del banco a exigir la constitución de garantías</h2>', 'f8e4237a-888f-4871-b32a-13e1c75bd587');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8f6c644c-f004-452a-938f-3539778ebee4', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank kann für alle Ansprüche aus der bankmäßigen Geschäftsverbindung die Bestellung bankmäßiger Sicherheiten verlangen, und zwar auch dann, wenn die Ansprüche bedingt sind (zum Beispiel Aufwendungsersatzanspruch wegen der Inanspruchnahme aus einer für den Kunden übernommenen Bürgschaft). Hat der Kunde gegenüber der Bank eine Haftung für Verbindlichkeiten eines anderen Kunden der Bank übernommen (zum Beispiel als Bürge), so besteht für die Bank ein Anspruch auf Bestellung oder Verstärkung von Sicherheiten im Hinblick auf die aus der Haftungsübernahme folgende Schuld jedoch erst ab ihrer Fälligkeit.</p>', 'b8caf533-84be-42c4-b4d5-f31fb56bff2b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0a296091-9319-43a0-b2b0-ab32c19f1a9f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank may demand that the customer provide the usual forms of security for any claims that may arise from the banking relationship, even if such claims are conditional (e.g. indemnity for amounts paid under a guarantee issued on behalf of the customer). If the customer has assumed a liability for another customer&#39;s obligations towards the Bank (e.g. as a surety), the Bank is, however, not entitled to demand that security be provided or increased for the debt resulting from such liability incurred before the maturity of the debt.</p>', 'b8caf533-84be-42c4-b4d5-f31fb56bff2b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bd100c45-135d-4a2d-b21e-0075d01265fe', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco podrá exigir la constitución de las garantías habitualmente exigidas por los bancos para el amparo de todos los derechos que se deriven de las relaciones contractuales bancarias, incluso cuando dichos derechos estén condicionados (por ej. el derecho a la reposición de gastos por el pago de una fianza asumida a favor del cliente). Si el cliente responde frente al banco por deudas de otro cliente del banco (por ej. en calidad de fiador), el banco sólo podrá exigir la constitución o el refuerzo de garantías sobre la deuda resultante de esta responsabilidad, una vez que el pago de esta deuda haya vencido.</p>', 'b8caf533-84be-42c4-b4d5-f31fb56bff2b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8dfdcf04-e0fd-469a-9061-a9d4beddbb93', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>13.2 Veränderung des Risikos</h2>', '59f4e786-ae08-4831-a212-c9ef984f7a99');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d2784c93-2cac-41b8-82bd-da92bba2dd10', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>13.2 Changes in the risk</h2>', '59f4e786-ae08-4831-a212-c9ef984f7a99');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('daca3d3a-12a2-4761-8eec-1a3849a0f502', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>13.2 Cambio del riesgo</h2>', '59f4e786-ae08-4831-a212-c9ef984f7a99');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c6d322eb-ff2d-46fd-a00f-920f1565c7af', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Hat die Bank bei der Entstehung von Ansprüchen gegen den Kunden zunächst ganz oder teilweise davon abgesehen, die Bestellung oder Verstärkung von Sicherheiten zu verlangen, kann sie auch später noch eine Besicherung fordern. Voraussetzung ist jedoch, dass Umstände eintreten oder bekannt werden, die eine erhöhte Risikobewertung der Ansprüche gegen den Kunden rechtfertigen. Dies kann insbesondere der Fall sein, wenn</p>', '90b68bf1-d6b0-42f7-af5d-2efb93f5b317');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('92668f63-9fd7-43d8-b45c-ded52613b71d', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the Bank, upon the creation of claims against the customer, has initially dispensed wholly or partly with demanding that security be provided or increased, it may nonetheless make such a demand at a later time, provided, however, that circumstances occur or become known which justify a higher risk assessment of the claims against the customer. This may, in particular, be the case if</p>', '90b68bf1-d6b0-42f7-af5d-2efb93f5b317');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('55af815a-0156-487b-b92b-da83239b4b45', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si al crearse un derecho frente al cliente, el banco prescinde inicialmente, de forma total o parcial, a la constitución o al refuerzo de garantías, podrá exigirlo posteriormente. Sin embargo, al efecto es necesario que se produzcan hechos o que trascienda información sobre hechos que justifiquen una mayor calificación de los riesgos a los que están expuestos sus derechos frente al cliente. Éste es el caso cuando:</p>', '90b68bf1-d6b0-42f7-af5d-2efb93f5b317');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b5ad87a4-f0ae-46a4-8d86-3bfccf416837', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<ul><li>sich die wirtschaftlichen Verhältnisse des Kunden nachteilig verändert haben oder sich zu verändern drohen oder</li><li>sich die vorhandenen Sicherheiten wertmäßig verschlechtert haben oder zu verschlechtern drohen.</li></ul>', '71fed046-26f4-4602-a458-6a62c928f162');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8b526f51-7f3a-40e2-97ba-9896bd9b9f3b', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<ul><li>the economic status of the customer has changed or threatens to change in a negative manner or</li><li>the value of the existing security has deteriorated or threatens to deteriorate.</li></ul>', '71fed046-26f4-4602-a458-6a62c928f162');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('99989563-ec19-4ff8-b2ff-8cb26cd77dff', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<ul><li>la situación financiera del cliente haya sufrido un deterioro sustancial o tienda a deteriorarse sustancialmente, o</li><li>las garantías constituidas hayan perdido valor o el deterioro de su valor sea previsible.</li></ul>', '71fed046-26f4-4602-a458-6a62c928f162');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f6cbde49-a4fd-44a3-a807-5948b8bbdb70', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Der Besicherungsanspruch der Bank besteht nicht, wenn ausdrücklich vereinbart ist, dass der Kunde keine oder ausschließlich im Einzelnen benannte Sicherheiten zu bestellen hat. Bei Verbraucherdarlehensverträgen besteht der Anspruch auf die Bestellung oder Verstärkung von Sicherheiten nur, soweit die Sicherheiten im Kreditvertrag angegeben sind. Übersteigt der Nettodarlehensbetrag 75.000 Euro, besteht der Anspruch auf Bestellung oder Verstärkung auch dann, wenn in einem vor dem 21. März 2016 abgeschlossenen Verbraucherdarlehensvertrag oder in einem ab dem 21. März 2016 abgeschlossenen Allgemein-Verbraucherdarlehensvertrag im Sinne von § 491 Abs. 2 BGB keine oder keine abschließenden Angaben über Sicherheiten enthalten sind.</p>', '4f4f8662-3a01-428d-a101-b34e053db067');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('561adeba-def7-4311-9a58-be57353281d0', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank has no right to demand security if it has been expressly agreed that the customer either does not have to provide any security or must only provide that security which has been specified. When, however, the net loan amount exceeds EUR 75,000, the Bank may demand that security be provided or increased even if a consumer loan agreement or a general consumer loan agreement within the meaning of Section 491 (2) of the German Civil Code which is concluded, in the former case, before 21 March 2016 and, in the latter case, from 21 March 2016 does not contain any or any exhaustive indications as to security.</p>', '4f4f8662-3a01-428d-a101-b34e053db067');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('79d75d0f-3965-4db3-b632-3dc5b871c3bb', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El derecho a constitución de garantías del banco no existe si se acuerda explícitamente que el cliente no debe constituir ninguna garantía o exclusivamente garantías que se identifican individualmente. En el caso de contratos de créditos a consumidores existe el derecho a la constitución o el refuerzo de garantías solo en la medida en la cual se establecen garantías en el contrato del crédito. Si el monto neto del crédito supera los 75.000,­ euros, el derecho a la constitución o refuerzo de garantías también existe, si un contrato de un crédito de consumo celebrado antes del 21 de marzo de 2016 o un contrato general de un crédito de consumo celebrado a partir del 21 de marzo de 2016 en el sentido del Artículo 491, Párrafo 2 del Código Civil, no contiene – o no contiene suficientes indicaciones – sobre garantías.</p>', '4f4f8662-3a01-428d-a101-b34e053db067');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('431a8ae8-9193-4716-baf1-2dd154df42a3', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>13.3 Fristsetzung für die Bestellung oder Verstärkung von Sicherheiten</h2>', '68021758-a7d7-42ae-8d4b-c381dad63cfa');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a47d31c1-496f-45c4-8ac5-2f7a7867b884', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>13.3 Setting a period of time for providing or increasing security</h2>', '68021758-a7d7-42ae-8d4b-c381dad63cfa');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b5e63040-5141-4884-a9e7-6db4421311bf', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>13.3 Plazos para la constitución o el refuerzo de garantías</h2>', '68021758-a7d7-42ae-8d4b-c381dad63cfa');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d6122f36-ea73-4c41-91ce-5572df4bd752', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Für die Bestellung oder Verstärkung von Sicherheiten wird die Bank eine angemessene Frist einräumen. Beabsichtigt die Bank, von ihrem Recht zur fristlosen Kündigung nach Nr. 19 Absatz 3 dieser Geschäftsbedingungen Gebrauch zu machen, falls der Kunde seiner Verpflichtung zur Bestellung oder Verstärkung von Sicherheiten nicht fristgerecht nachkommt, wird sie ihn zuvor hierauf hinweisen.</p>', '751bd891-8699-4c4f-aefb-77ef0ffeb3a0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2b399505-6b42-4f29-91ea-0e182b272fcb', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank shall allow a reasonable period of time for providing or increasing security. If the Bank intends to make use of its right of termination without notice according to No.19 (3) of these Business Conditions should the customer fail to comply with the obligation to provide or increase security within such period, it shall draw the customer&#39;s attention to this consequence before doing so.</p>', '751bd891-8699-4c4f-aefb-77ef0ffeb3a0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1a2afbce-acf3-4d3e-a0a0-74f64017bdda', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco concederá al cliente un plazo razonable para la constitución o el refuerzo de garantías. Si el cliente no cumple en el plazo previsto su obligación de constituir o reforzar garantías, el banco advertirá antes al cliente de su intención de hacer uso de su derecho de rescisión inmediata del contrato de acuerdo con el artículo 19, apartado 3 de las presentes Condiciones Generales de Contratación.</p>', '751bd891-8699-4c4f-aefb-77ef0ffeb3a0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('73d58c90-de3f-422b-83e6-0d1fd630820f', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Vereinbarung eines Pfandrechts zugunsten der Bank</h2>', '8410c1eb-ee77-4784-9481-b7f0c97bb635');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('80e8b10e-0c48-43b0-997b-8218be719058', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Lien in favour of the Bank</h2>', '8410c1eb-ee77-4784-9481-b7f0c97bb635');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9d45e4e2-cb77-46d8-87ec-ddba6c89e17a', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Acuerdo sobre el derecho de prenda a favor del banco</h2>', '8410c1eb-ee77-4784-9481-b7f0c97bb635');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3b924c61-ce6d-4757-95ce-18c592d3ffb6', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>14. Vereinbarung eines Pfandrechts zugunsten der Bank</h2>', '07000ce0-073d-4ba3-b0b1-fcd728c677fe');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d7628d95-96b6-48b6-afaf-9947401fe515', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>14. Agreement on the lien</h2>', '07000ce0-073d-4ba3-b0b1-fcd728c677fe');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fe1d4898-a6d2-4b6b-896b-0486bcc63451', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>14. Acuerdo sobre el derecho de prenda</h2>', '07000ce0-073d-4ba3-b0b1-fcd728c677fe');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ba66e3f5-020d-44b7-8214-541bd4e98dc3', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>14.1 Der Kunde und die Bank sind sich darüber einig, dass die Bank ein Pfandrecht an den Wertpapieren und Sachen erwirbt, an denen eine inländische Geschäftsstelle im bankmäßigen Geschäftsverkehr Besitz erlangt hat oder noch erlangen wird. Die Bank erwirbt ein Pfandrecht auch an den Ansprüchen, die dem Kunden gegen die Bank aus der bankmäßigen Geschäftsverbindung zustehen oder künftig zustehen werden (zum Beispiel Kontoguthaben).</p>', '67a61920-3f32-4620-bc6e-54f7effff115');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f6b8a782-bad2-4c99-acec-44d70edfdf2a', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>14.1 The customer and the Bank agree that the Bank acquires a lien on the securities and chattels which, within the scope of banking business, have come or may come into the possession of a domestic office of the Bank. The Bank also acquires a lien on any claims which the customer has or may in future have against the Bank arising from the banking relationship (e.g. credit balances).</p>', '67a61920-3f32-4620-bc6e-54f7effff115');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('43b6d451-4e64-451b-8446-192bc263a038', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>14.1 El cliente y el banco acuerdan que el banco adquiere un derecho de prenda sobre aquellos títulos o bienes que estén en poder o lleguen a poder de alguna oficina del banco en Alemania que opere en el marco del negocio bancario. El banco también adquirirá el derecho de prenda sobre cualquier deuda del banco frente al cliente resultante del negocio bancario (por ej. sobre saldos acreedores en cuenta).</p>', '67a61920-3f32-4620-bc6e-54f7effff115');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b4924627-7093-4db1-b57b-42d8c9ff9161', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>14.2 Gesicherte Ansprüche</h2>', 'cb49e7ac-2434-4b8a-a8fa-0df3cc481a07');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('10b0bbda-f8c3-443f-ad42-b6dd70171d8a', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>14.2 Secured claims</h2>', 'cb49e7ac-2434-4b8a-a8fa-0df3cc481a07');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8624704d-e583-4852-8d61-e8d51fae6e3b', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>14.2 Derechos garantizados</h2>', 'cb49e7ac-2434-4b8a-a8fa-0df3cc481a07');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('17a9a70f-2dbb-4056-9675-50bf55bbc44e', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Das Pfandrecht dient der Sicherung aller bestehenden, künftigen und bedingten Ansprüche, die der Bank mit ihren sämtlichen in- und ausländischen Geschäftsstellen aus der bankmäßigen Geschäftsverbindung gegen den Kunden zustehen. Hat der Kunde gegenüber der Bank eine Haftung für Verbindlichkeiten eines anderen Kunden der Bank übernommen (zum Beispiel als Bürge), so sichert das Pfandrecht die aus der Haftungsübernahme folgende Schuld jedoch erst ab ihrer Fälligkeit.</p>', '81fa1725-f287-4e31-aa9b-bb7f7cd29799');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6e9e0b30-3ce8-4153-82f9-ccc83cee7f62', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The lien serves to secure all existing, future and contingent claims arising from the banking relationship which the Bank with all its domestic and foreign offices is entitled to against the customer. If the customer has assumed liability for another customer&#39;s obligations towards the Bank (e.g. as a surety), the lien shall not secure the debt resulting from the liability incurred before the maturity of the debt.</p>', '81fa1725-f287-4e31-aa9b-bb7f7cd29799');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('259c5734-8c5a-4edc-a1c6-cec6300d0924', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El derecho de prenda facultará al banco a asegurar todos los derechos existentes, futuros y condicionados del banco resultantes de la relación bancaria con el cliente, incluyendo todos sus establecimientos bancarios dentro y fuera de Alemania. Si el cliente responde frente al banco por deudas de otro cliente del banco (por ej. en calidad de fiador), el banco sólo podrá exigir, sin embargo, la constitución o el refuerzo de garantías sobre la deuda resultante de esta responsabilidad, una vez que el pago de esta deuda haya vencido.</p>', '81fa1725-f287-4e31-aa9b-bb7f7cd29799');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9693c1af-4259-4bdb-841c-fe70af8d7e44', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>14.3 Ausnahmen vom Pfandrecht</h2>', '2999346c-9387-4d9b-8e62-64c7526739bd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('71641929-3e96-4261-9b78-09c9c03fc85a', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>14.3 Exemptions from the lien</h2>', '2999346c-9387-4d9b-8e62-64c7526739bd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ab377024-e8e8-4bc9-8e86-b33587147fd2', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>14.3 Excepciones al derecho de prenda</h2>', '2999346c-9387-4d9b-8e62-64c7526739bd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ea3aa278-d2be-42a4-9787-88a9f378a9c8', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Gelangen Gelder oder andere Werte mit der Maßgabe in die Verfügungsgewalt der Bank, dass sie nur für einen bestimmten Zweck verwendet werden dürfen (zum Beispiel Bareinzahlung zur Einlösung eines Wechsels), erstreckt sich das Pfandrecht der Bank nicht auf diese Werte. Dasselbe gilt für die von der Bank selbst ausgegebenen Aktien (eigene Aktien) und für die Wertpapiere, die die Bank im Ausland für den Kunden verwahrt. Außerdem erstreckt sich das Pfandrecht nicht auf die von der Bank selbst ausgegebenen eigenen Genussrechte/Genussscheine und nicht auf die verbrieften und nicht verbrieften nachrangigen Verbindlichkeiten der Bank.</p>', '27ca8726-ade4-4c85-ac79-6653136ca0b0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f98d00ec-7b79-4a64-ae13-ecf8d57d06fc', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If funds or other assets come into the power of disposal of the Bank under the reserve that they may only be used for a specified purpose (e.g. deposit of cash for payment of a bill of exchange),the Bank&#39;s lien does not extend to these assets. The same applies to shares issued by the Bank itself (own shares) and to securities which the Bank keeps in custody abroad for the customer&#39;s account. Moreover, the lien extends neither to the profit-participation rights/profit-participation certificates(Genussrechte/Genussscheine) issued by the Bank itself nor to the Bank&#39;s securitised and non-securitised subordinated liabilities.</p>', '27ca8726-ade4-4c85-ac79-6653136ca0b0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b5ad6d1d-6311-4bef-82f4-92e68e769301', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El derecho de prenda del banco no se extiende a fondos u otros valores que lleguen a su poder de disposición con la finalidad de emplearlos con fines específicos (por ej. depósito de dinero en efectivo para el pago de una letra de cambio). Quedan también excluidas del derecho de prenda las acciones del banco emitidas por el propio banco (acciones propias) y aquellos títulos que el banco conserve en custodia para el cliente en el extranjero. El derecho de prenda tampoco se aplicará a los derechos o certificados de participación en el beneficio emitidos por el propio banco, ni tampoco las deudas subordinadas del banco, estén representadas por valores negociables o no.</p>', '27ca8726-ade4-4c85-ac79-6653136ca0b0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a38bac9c-007b-4dfc-9642-787bbc32ec03', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>14.4 Zins- und Gewinnanteilscheine</h2>', '17bed4e9-323d-4998-9a67-fd122ad9f0b4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('27559136-ccf6-40c2-a694-2b65d83a4649', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>14.4 Interest and dividend coupons</h2>', '17bed4e9-323d-4998-9a67-fd122ad9f0b4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4e7c0a25-91a1-4dd5-8bc7-93cc7fa11ec5', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>14.4 Cupones de intereses y de dividendos</h2>', '17bed4e9-323d-4998-9a67-fd122ad9f0b4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0df9fab6-890c-439a-9a70-a625a3794aa7', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Unterliegen dem Pfandrecht der Bank Wertpapiere, ist der Kunde nicht berechtigt, die Herausgabe der zu diesen Papieren gehörenden Zins- und Gewinnanteilscheine zu verlangen.</p>', '944455f2-6385-4f75-9bbc-e23b3fd6d091');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('03ceea5c-61f8-47fe-800f-25bcefbb32dc', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If securities are subject to the Bank&#39;s lien, the customer is not entitled to demand the delivery of the interest and dividend coupons pertaining to such securities.</p>', '944455f2-6385-4f75-9bbc-e23b3fd6d091');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c502020f-6c51-48bd-a982-cb410ea7e95a', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si el derecho de prenda es aplicable a valores mobiliarios, el cliente no podrá exigir la entrega de los cupones de intereses y dividendos correspondientes.</p>', '944455f2-6385-4f75-9bbc-e23b3fd6d091');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d0f56561-4d9b-4acf-8dbc-c5d2fcdc943d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>15. Sicherungsrechte bei Einzugspapieren und diskontierten Wechseln</h2>', 'daccec53-c77b-413e-a682-766156be3883');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('410dfe47-0130-482d-ace6-00e3f085d63c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>15. Security interests in the case of items for collection and discounted bills of exchange</h2>', 'daccec53-c77b-413e-a682-766156be3883');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a49f55cf-d462-4ee5-afa1-dbb39431188c', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>15. Derechos sobre garantías consistentes en documentos presentados al cobro y efectos descontados</h2>', 'daccec53-c77b-413e-a682-766156be3883');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0a17e3cf-f6e5-4f40-b580-e4abe7b1d7e7', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>15.1 Sicherungsübereignung</h2>', '391093db-7278-4c38-bb32-ab16411b7172');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('35143413-47c5-466a-bf2a-3be5c3adc8a7', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>15.1 Transfer of ownership by way of security</h2>', '391093db-7278-4c38-bb32-ab16411b7172');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('39e024b7-eb6d-47a3-a07b-3e4ecb5de767', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>15.1 Transmisión de la propiedad en garantía</h2>', '391093db-7278-4c38-bb32-ab16411b7172');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1e8618e3-b0b0-4909-917c-2acf508a2de6', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank erwirbt an den ihr zum Einzug eingereichten Schecks und Wechseln im Zeitpunkt der Einreichung Sicherungseigentum. An diskontierten Wechseln erwirbt die Bank im Zeitpunkt des Wechselankaufs uneingeschränktes Eigentum; belastet sie diskontierte Wechsel dem Konto zurück, so verbleibt ihr das Sicherungseigentum an diesen Wechseln.</p>', '4983ccdf-32c9-4118-bbc1-53fa333fa3cf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0001cffd-6f60-4adf-84ca-8bb812109cf6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank acquires ownership by way of security of any cheques and bills of exchange deposited for collection at the time such items are deposited. The Bank acquires absolute ownership of discounted bills of exchange at the time of the purchase of such items; if it re-debits discounted bills of exchange to the account, it retains the ownership by way of security in such bills of exchange.</p>', '4983ccdf-32c9-4118-bbc1-53fa333fa3cf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c0c93ba0-0e88-4e71-9760-a72b65d57b50', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco adquirirá la propiedad en garantía sobre cheques y efectos presentados al cobro en el momento de su presentación. El banco adquirirá la plena propiedad de efectos descontados en el momento de la compra del efecto; si el banco recarga en cuenta el importe de los efectos descontados, conservará la propiedad sobre dichas letras de cambio tomadas en garantía.</p>', '4983ccdf-32c9-4118-bbc1-53fa333fa3cf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('25af3330-4671-454f-bd6a-2b7fefb07dd5', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>15.2 Sicherungsabtretung</h2>', '6fc1b623-dd82-4bc2-9dc5-354af6548dd9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('984ed25f-69b1-46ad-861a-71ef348edd4e', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>15.2 Assignment by way of security</h2>', '6fc1b623-dd82-4bc2-9dc5-354af6548dd9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('73313e9f-55a6-4cc4-aaff-9418e9c3d8be', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>15.2 Cesión de derechos en garantía</h2>', '6fc1b623-dd82-4bc2-9dc5-354af6548dd9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8f398155-ab12-4100-ad7e-2ab8cd34aaa4', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Mit dem Erwerb des Eigentums an Schecks und Wechseln gehen auch die zugrunde liegenden Forderungen auf die Bank über; ein Forderungsübergang findet ferner statt, wenn andere Papiere zum Einzug eingereicht werden (zum Beispiel Lastschriften, kaufmännische Handelspapiere).</p>', '59df4713-bf8b-4154-a4b8-51f1a629229c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2c5d395b-ebc1-4048-9a1c-b8bea5c31af6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The claims underlying the cheques and bills of exchange shall pass to the Bank simultaneously with the acquisition of ownership in the cheques and bills of exchange; the claims also pass to the Bank if other items are deposited for collection (e.g. direct debits, documents of commercial trading).</p>', '59df4713-bf8b-4154-a4b8-51f1a629229c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d0207d8a-7013-4fb2-a521-f2303af9eef6', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Al adquirir la propiedad de cheques y letras de cambio, el banco adquiere a la vez los derechos subyacentes; esto es aplicable a cualquier otro documento presentado al cobro (por ej. recibos o efectos comerciales).</p>', '59df4713-bf8b-4154-a4b8-51f1a629229c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('292d7620-c67e-429a-84f8-4d726422fc9a', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>15.3 Zweckgebundene Einzugspapiere</h2>', '3e6c5746-cb7f-4b1b-a788-ff860613b16f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0ea57561-5c97-4eab-a4e1-e41270915711', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>15.3 Special-purpose items for collection</h2>', '3e6c5746-cb7f-4b1b-a788-ff860613b16f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('74d64b26-433c-4fc6-b36a-8c7db121125f', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>15.3 Documentos al cobro presentados con fines específicos</h2>', '3e6c5746-cb7f-4b1b-a788-ff860613b16f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b6d7028d-435a-4d56-8856-2a36f272aa2d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Werden der Bank Einzugspapiere mit der Maßgabe eingereicht, dass ihr Gegenwert nur für einen bestimmten Zweck verwendet werden darf, erstrecken sich die Sicherungsübereignung und die Sicherungsabtretung nicht auf diese Papiere.</p>', '3a989a69-5753-4f48-8310-c6db9ac7d294');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('209585c0-b835-41b4-aafb-ec3b929159d6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If items for collection are deposited with the Bank under the reserve that their countervalue may only be used for a specified purpose, the transfer or assignment of ownership by way of security does not extend to these items.</p>', '3a989a69-5753-4f48-8310-c6db9ac7d294');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('81b2601d-b4ce-4bb1-9b6c-ba07ff2928a7', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>La transmisión de propiedad en garantía y la cesión de derechos en garantía no se aplicará a documentos que el cliente haya presentado con la expresa instrucción de que el banco emplee su contravalor con fines específicos.</p>', '3a989a69-5753-4f48-8310-c6db9ac7d294');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ddcc1fe1-b882-44c8-bdbd-a9564f07df09', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>15.4 Gesicherte Ansprüche der Bank</h2>', '67d86f1c-ec09-4ba6-88fb-c79a37a8062a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9fe30a35-dd7c-4314-a9a0-a48193474eca', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>15.4 Secured claims of the Bank</h2>', '67d86f1c-ec09-4ba6-88fb-c79a37a8062a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f1293043-fd84-4d07-9b3c-7be89e2db017', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>15.4 Derechos garantizados del banco</h2>', '67d86f1c-ec09-4ba6-88fb-c79a37a8062a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('537b1a3b-06f0-4d4f-a759-638ec491791b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Das Sicherungseigentum und die Sicherungsabtretung dienen der Sicherung aller Ansprüche, die der Bank gegen den Kunden bei Einreichung von Einzugspapieren aus seinen Kontokorrentkonten zustehen oder die infolge der Rückbelastung nicht eingelöster Einzugspapiere oder diskontierter Wechsel entstehen. Auf Anforderung des Kunden nimmt die Bank eine Rückübertragung des Sicherungseigentums an den Papieren und der auf sie übergegangenen Forderungen an den Kunden vor, wenn ihr im Zeitpunkt der Anforderung kein zu sichernder Anspruch gegen den Kunden zusteht oder wenn sie den Kunden über den Gegenwert der Papiere vor deren endgültiger Bezahlung nicht verfügen lässt.</p>', 'ee0a30da-d5aa-4774-8eae-d136cd0d72e7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a262a0f3-f279-4909-80f0-53aeb7bf7812', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The ownership transferred or assigned by way of security serves to secure any claims which the Bank may be entitled to against the customer arising from the customer&#39;s current account when items are deposited for collection or arising as a consequence of the re-debiting of unpaid items for collection or discounted bills of exchange. Upon request of the customer, the Bank retransfers to the customer the ownership by way of security of such items and of the claims that have passed to it if it does not, at the time of such request, have any claims against the customer that need to be secured or if it does not permit the customer to dispose of the countervalue of such items prior to their final payment.</p>', 'ee0a30da-d5aa-4774-8eae-d136cd0d72e7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4d26b3dc-28b9-4c6b-929d-7bfeafd6ee40', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>La transmisión de propiedad o la cesión de derechos en garantía servirán para cubrir deudas del cliente frente al banco en el momento de la presentación al cobro en cuenta corriente de documentos presentados al cobro o para cancelar deudas derivadas de importes que se han vuelto a cargar en cuenta en virtud del impago de efectos o documentos descontados. A solicitud del cliente, el banco devolverá al cliente la propiedad cedida en garantía de títulos y los derechos frente al cliente que hayan pasado a este, si en el momento de la solicitud el banco no dispone de derecho frente al cliente que deba ser asegurado mediante garantías o si el banco impide al cliente disponer sobre el contravalor de los títulos antes de su pago definitivo.</p>', 'ee0a30da-d5aa-4774-8eae-d136cd0d72e7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0c39a66d-1e4f-4839-8e8e-8adb4ef3e276', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>16. Begrenzung des Besicherungsanspruchs und Freigabeverpflichtung</h2>', 'e1c64895-ce65-4f2f-bfe7-032a1b34e216');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a7c165fe-6076-4612-bf76-bf161347fa72', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>16. Limitation of the claim to security and obligation to release</h2>', 'e1c64895-ce65-4f2f-bfe7-032a1b34e216');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('37498673-414d-40bd-9f94-1404ffb15a87', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>16. Limitación del derecho de exigir garantías y obligación de liberar garantías</h2>', 'e1c64895-ce65-4f2f-bfe7-032a1b34e216');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0cc3ed30-e37e-48ca-b6db-54778e9814cb', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>16.1 Deckungsgrenze</h2>', '7ace2c80-a40a-4b51-91b0-14955f19a6af');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('81d2e915-c70b-41a8-8532-bb4364a022d4', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>16.1 Cover limit</h2>', '7ace2c80-a40a-4b51-91b0-14955f19a6af');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f23e4191-7b26-42d0-80c0-11ee407b63e7', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>16.1 Límite de cobertura</h2>', '7ace2c80-a40a-4b51-91b0-14955f19a6af');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('29959d24-a3e1-4070-8483-489064fd134c', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank kann ihren Anspruch auf Bestellung oder Verstärkung von Sicherheiten so lange geltend machen, bis der realisierbare Wert aller Sicherheiten dem Gesamtbetrag aller Ansprüche aus der bankmäßigen Geschäftsverbindung (Deckungsgrenze) entspricht.</p>', 'f82dd877-120f-4411-9090-860d5787b901');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9e5cbc4f-30b3-47ef-8d6d-347906ed7a38', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank may demand that security be provided or increased until the realisable value of all security corresponds to the total amount of all claims arising from the banking business relationship (cover limit).</p>', 'f82dd877-120f-4411-9090-860d5787b901');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('45eb5370-d5ec-4b19-ad4f-36b4af090a4b', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco podrá exigir la constitución o el refuerzo de garantías hasta el valor de venta o ejecución de garantías que cubra el importe total de todos los derechos resultantes de las relaciones contractuales con el cliente (límite de cobertura).</p>', 'f82dd877-120f-4411-9090-860d5787b901');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('559a9812-6295-4d93-8a1c-7f8a594c05b6', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>16.2 Freigabe</h2>', 'd3b42f4b-c81c-4fb7-a4ce-fd98575e8cf3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b8ca8472-4692-4bb9-b260-09c986ecd569', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>16.2 Release</h2>', 'd3b42f4b-c81c-4fb7-a4ce-fd98575e8cf3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f1634f49-7aa3-4713-8935-989372d52e1e', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>16.2 Liberación de garantías</h2>', 'd3b42f4b-c81c-4fb7-a4ce-fd98575e8cf3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4a57947b-5b41-47cb-afa1-d99233e871ac', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Falls der realisierbare Wert aller Sicherheiten die Deckungsgrenze nicht nur vorübergehend übersteigt, hat die Bank auf Verlangen des Kunden Sicherheiten nach ihrer Wahl freizugeben, und zwar in Höhe des die Deckungsgrenze übersteigenden Betrages; sie wird bei der Auswahl der freizugebenden Sicherheiten auf die berechtigten Belange des Kunden und eines dritten Sicherungsgebers, der für die Verbindlichkeiten des Kunden Sicherheiten bestellt hat, Rücksicht nehmen. In diesem Rahmen ist die Bank auch verpflichtet, Aufträge des Kunden über die dem Pfandrecht unterliegenden Werte auszuführen (zum Beispiel Verkauf von Wertpapieren, Auszahlung von Sparguthaben).</p>', '6831c7c7-1df1-4fc1-8191-7d4ec670372b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5832fd1c-0a1e-4ff3-9302-4af21f574ee1', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the realisable value of all security exceeds the cover limit on a more than temporary basis, the Bank shall, at the customer&#39;s request, release security items as it may choose in the amount exceeding the cover limit; when selecting the security items to be released, the Bank shall take into account the legitimate concerns of the customer or of any third party having provided security for the customer&#39;s obligations. To this extent, the Bank is also obliged to execute orders of the customer relating to the items subject to the lien (e.g. sale of securities, repayment of savings deposits).</p>', '6831c7c7-1df1-4fc1-8191-7d4ec670372b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d5960299-64c6-4190-aa1c-e809f172b096', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si el valor de venta o de ejecución de garantías excede, no sólo de forma transitoria, el límite de cobertura, el banco deberá, a solicitud del cliente, liberar las garantías por el importe que exceda el límite de cobertura, quedando a su discreción la selección de las garantías; al elegir las garantías que ha de liberar, el banco tendrá en cuenta los intereses legítimos del cliente y de posibles terceros que hayan constituido garantías a favor del cliente para la cobertura de sus deudas frente al banco. En este ámbito, el banco también debe ejecutar órdenes del cliente relacionadas con títulos gravados por el derecho de prenda (por ej., venta de valores, desembolso de depósitos de ahorro).</p>', '6831c7c7-1df1-4fc1-8191-7d4ec670372b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5fe0e2a6-902f-4e95-ae63-74e384a64150', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>16.3 Sondervereinbarungen</h2>', '841d6b26-e6c9-4732-8ba7-1a0cedb530a5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8185d0e5-fd83-4a22-b784-3271b3c0a333', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>16.3 Special agreements</h2>', '841d6b26-e6c9-4732-8ba7-1a0cedb530a5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('467a6616-0c7b-425b-9861-c8ea6ee021de', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>16.3 Acuerdos particulares</h2>', '841d6b26-e6c9-4732-8ba7-1a0cedb530a5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('cbc7bc79-edad-4a84-afd7-0434f179e937', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Ist für eine bestimmte Sicherheit ein anderer Bewertungsmaßstab als der realisierbare Wert oder ist eine andere Deckungsgrenze oder ist eine andere Grenze für die Freigabe von Sicherheiten vereinbart, so sind diese maßgeblich.</p>', '08b39fa9-0e0c-49c2-8f82-ccb81433bfee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1343e8b2-3927-4608-b17c-ed9235eea43f', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If assessment criteria for a specific security item other than the realisable value or another cover limit or another limit for the release of security have been agreed, these other criteria or limits shall apply.</p>', '08b39fa9-0e0c-49c2-8f82-ccb81433bfee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('94e98792-3576-404b-a1af-6d842f7d5ccc', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si para una determinada garantía se han pactado criterios distintos de valoración al valor de venta o ejecución, límites diferentes de cobertura o de liberación de garantías, éstos prevalecerán.</p>', '08b39fa9-0e0c-49c2-8f82-ccb81433bfee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5923a956-7cd6-4924-8443-78bd0de997de', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>17. Verwertung von Sicherheiten</h2>', 'b6f354f8-b6e7-44a0-87d6-8447917eaae3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6f50353d-7ce1-4f78-81ed-d1279e2ed66c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>17. Realisation of security</h2>', 'b6f354f8-b6e7-44a0-87d6-8447917eaae3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('61cfbf5a-6169-4711-b129-ee03e21a1fe8', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>17. Ejecución de garantías</h2>', 'b6f354f8-b6e7-44a0-87d6-8447917eaae3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a20dd1bf-7f34-4b85-998a-96c25610eea3', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>17.1 Wahlrecht der Bank</h2>', '60115be8-a6d1-4e1c-8f54-e3199b8c2ea5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a06a2bd8-b99a-4cd6-b375-7f287479e91b', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>17.1 Option of the Bank</h2>', '60115be8-a6d1-4e1c-8f54-e3199b8c2ea5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1277cf45-75f3-4928-8436-7ed426c1ca78', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>17.1 Derecho de opción del banco</h2>', '60115be8-a6d1-4e1c-8f54-e3199b8c2ea5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d40b74de-1078-4926-bca6-960dc580009a', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Wenn die Bank verwertet, hat die Bank unter mehreren Sicherheiten die Wahl. Sie wird bei der Verwertung und bei der Auswahl der zu verwertenden Sicherheiten auf die berechtigten Belange des Kunden und eines dritten Sicherungsgebers, der für die Verbindlichkeiten des Kunden Sicherheiten bestellt hat, Rücksicht nehmen.</p>', 'e46a1f8f-3f73-47e1-967c-ea7ae9dd5ad7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b98861ec-01cf-42fe-bd41-963d63171639', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the Bank realises security, it may choose between several security items. When realising security and selecting the items to be realised, the Bank shall take into account the legitimate concerns of the customer and any third party who may have provided security for the obligations of the customer.</p>', 'e46a1f8f-3f73-47e1-967c-ea7ae9dd5ad7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8896e6b2-f528-41b7-b912-9bb26cd9d6eb', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si el banco vende o ejecuta garantías, podrá elegir las garantías que ha de vender o ejecutar. Al seleccionar las garantías, el banco tendrá en cuenta los legítimos intereses del cliente y de posibles terceros que hayan constituido garantías a favor del cliente para la cobertura de sus deudas frente al banco.</p>', 'e46a1f8f-3f73-47e1-967c-ea7ae9dd5ad7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3fd64798-376b-4022-949c-5162276249cd', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>17.2 Erlösgutschrift nach dem Umsatzsteuerrecht</h2>', '9c8221dc-4d00-4e9c-a0d6-38e6373f3d0d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a2eac072-8117-47e9-9310-69e5c98aeee2', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>17.2 Credit entry for proceeds under turnover tax law</h2>', '9c8221dc-4d00-4e9c-a0d6-38e6373f3d0d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8d3052e8-fd8c-478c-ab4e-4f5aeed24db7', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>17.2 Abono del producto de la venta e impuesto sobre las ventas</h2>', '9c8221dc-4d00-4e9c-a0d6-38e6373f3d0d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c3d8766f-9e45-424c-8102-1e113a5f004d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Wenn der Verwertungsvorgang der Umsatzsteuer unterliegt, wird die Bank dem Kunden über den Erlös eine Gutschrift erteilen, die als Rechnung für die Lieferung der als Sicherheit dienenden Sache gilt und den Voraussetzungen des Umsatzsteuerrechts entspricht.</p>', 'aa3d475e-5123-4c67-b78d-0e5f83af5824');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3b5df301-b36f-4a92-98f5-e6ce44180dd6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the transaction of realisation is subject to turnover tax, the Bank shall provide the customer with a credit entry for the proceeds, such entry being deemed to serve as invoice for the supply of the item given as security and meeting the requirements of turnover tax law (Umsatzsteuerrecht).</p>', 'aa3d475e-5123-4c67-b78d-0e5f83af5824');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7eb305ea-99b0-41d5-be1f-d7fa1981a129', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si la ejecución de garantías está sujeta al impuesto sobre las ventas, el banco extenderá al cliente una nota de abono por el valor del producto de la venta. La nota de abono es válida como factura de la entrega del objeto que sirve de garantía y se corresponde con los requisitos para el régimen del impuesto sobre las ventas.</p>', 'aa3d475e-5123-4c67-b78d-0e5f83af5824');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('82233e42-6773-442d-a684-ebaf8ec41fcc', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Kündigung</h2>', '242f9f74-e77b-4d0d-a1f7-b6bd3c44eb29');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f7f9c1dd-a0e1-4727-bb32-498476009ba6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Termination</h2>', '242f9f74-e77b-4d0d-a1f7-b6bd3c44eb29');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('13ab7100-0eb3-4cde-bc8e-619af1509228', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Resolución del contrato</h2>', '242f9f74-e77b-4d0d-a1f7-b6bd3c44eb29');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e159f94c-00ca-4147-b224-e1e1e36f4453', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>18. Kündigungsrechte des Kunden</h2>', '5a38d0bf-54b2-484e-af5c-12d9fc4d8cb9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('455a2510-b3a3-45f9-9bd2-a7e058de3d55', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>18. Termination rights of the customer</h2>', '5a38d0bf-54b2-484e-af5c-12d9fc4d8cb9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c35c7733-7647-4814-92e5-ac602676ae3d', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>18. Derechos de rescisión del cliente</h2>', '5a38d0bf-54b2-484e-af5c-12d9fc4d8cb9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('be478442-4a0f-43c0-83b7-c1da30b7e910', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>18.1 Jederzeitiges Kündigungsrecht</h2>', 'ca38a1d5-90a9-48f3-a0fa-4499b4eb216f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('86733681-7e4a-4430-bd44-cef80673eabd', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>18.1 Right of termination at any time</h2>', 'ca38a1d5-90a9-48f3-a0fa-4499b4eb216f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1b94fe81-7b40-4570-bcdc-cd196caf3ac4', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>18.1 Posibilidad de rescisión del contrato en cualquier momento</h2>', 'ca38a1d5-90a9-48f3-a0fa-4499b4eb216f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9dc0a27f-04d4-432f-b015-e79f4719c521', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Der Kunde kann die gesamte Geschäftsverbindung oder einzelne Geschäftsbeziehungen (zum Beispiel den Scheckvertrag), für die weder eine Laufzeit noch eine abweichende Kündigungsregelung vereinbart ist, jederzeit ohne Einhaltung einer Kündigungsfrist kündigen.</p>', 'c1497824-d938-4bf6-9013-fd8c5079bf36');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5625fe2a-174a-4e3c-b8ca-52babddd981c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Unless the Bank and the customer have agreed a term or a diverging termination provision, the customer may at any time, without notice, terminate the business relationship as a whole or particular business relations (e.g. a chequing agreement).</p>', 'c1497824-d938-4bf6-9013-fd8c5079bf36');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('403d0400-eaa0-4879-aa31-13e1756f6a66', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Salvo que se haya pactado un determinado plazo de vigencia del contrato o una cláusula distinta de rescisión, el cliente puede rescindir en cualquier momento y sin aviso previo toda la relación contractual o parte de ella (por ej. las operaciones con cheques).</p>', 'c1497824-d938-4bf6-9013-fd8c5079bf36');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('95eb929e-0a9f-4d2d-adc2-a684274188fb', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>18.2 Kündigung aus wichtigem Grund</h2>', '83c74a75-8026-460b-b07d-7d4a98f39aeb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('28e41b06-6036-4690-bee4-e9e3d4c86ace', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>18.2 Termination for reasonable cause</h2>', '83c74a75-8026-460b-b07d-7d4a98f39aeb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('78706025-c9e3-444c-aac4-6e57a1c7c929', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>18.2 Rescisión del contrato por causa justa</h2>', '83c74a75-8026-460b-b07d-7d4a98f39aeb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1744f520-a972-44b3-b50d-e64e35598464', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Ist für eine Geschäftsbeziehung eine Laufzeit oder eine abweichende Kündigungsregelung vereinbart, kann eine fristlose Kündigung nur dann ausgesprochen werden, wenn hierfür ein wichtiger Grund vorliegt, der es dem Kunden, auch unter Berücksichtigung der berechtigten Belange der Bank, unzumutbar werden lässt, die Geschäftsbeziehung fortzusetzen.</p>', '94389748-2a25-40b8-925b-67283780dd52');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('61008497-8464-4bc1-b98d-2a7a817ba426', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If the Bank and the customer have agreed a term or a diverging termination provision for a particular business relation, such relation may only be terminated without notice if there is reasonable cause therefor which makes it unacceptable to the customer to continue it, also after giving consideration to the legitimate concerns of the Bank.</p>', '94389748-2a25-40b8-925b-67283780dd52');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('77927e76-93d3-40c6-a23a-5ef3224a1ebd', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si para un determinado tipo de operación se ha pactado un cierto plazo de vigencia del contrato o una cláusula distinta de rescisión, el contrato sólo podrá rescindirse sin aviso previo si existe una causa justa que, incluso considerando los legítimos intereses del banco, haga inaceptable para el cliente su continuación.</p>', '94389748-2a25-40b8-925b-67283780dd52');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('67184015-4ae4-4219-8842-4abe8ace890e', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>18.3 Gesetzliche Kündigungsrechte</h2>', '75357d84-1de5-472f-9d61-dba566f84f76');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d86de08d-e4a1-4796-86f0-ffcc0c7dc454', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>18.3 Statutory termination rights</h2>', '75357d84-1de5-472f-9d61-dba566f84f76');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b0bbe85b-7c22-4379-bd79-f081483048d6', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>18.3 Derechos legales de rescisión</h2>', '75357d84-1de5-472f-9d61-dba566f84f76');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9fce95fd-a514-49ee-9d98-d39ab927c83b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Gesetzliche Kündigungsrechte bleiben unberührt.</p>', '3412345f-2db6-4588-9b4c-07eb29542f15');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e64bb7fb-d055-4a2a-a16f-8d57e48fc9d0', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Statutory termination rights shall not be affected.</p>', '3412345f-2db6-4588-9b4c-07eb29542f15');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b956a7d6-530a-4621-ad4b-266d5baa5e0b', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Quedan intactos los derechos de rescisión legales.</p>', '3412345f-2db6-4588-9b4c-07eb29542f15');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bb109ebe-9285-4b7b-b3ff-5f4665469f34', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>19. Kündigungsrechte der Bank</h2>', 'f22dac25-a39c-4308-89f6-49cefa19d5e5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a1b6dcdc-4cd3-4c62-8f17-4e59c684b642', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>19. Termination rights of the Bank</h2>', 'f22dac25-a39c-4308-89f6-49cefa19d5e5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6f4f2501-d725-40b0-804d-848e7e5fce6d', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>19. Derechos de rescisión del banco</h2>', 'f22dac25-a39c-4308-89f6-49cefa19d5e5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('94744eaa-2959-4e0b-b2d2-4239fdd76908', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>19.1 Kündigung unter Einhaltung einer Kündigungsfrist</h2>', '42ba0a97-300f-4c5c-aee6-4c3e47f839f9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0ca7f532-8c77-4552-bcc0-bc636cf8a4c6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>19.1 Termination upon notice</h2>', '42ba0a97-300f-4c5c-aee6-4c3e47f839f9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a54fbe36-7705-45b0-a51c-714ec0bfa3cb', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>19.1 Rescisión bajo cumplimiento del plazo</h2>', '42ba0a97-300f-4c5c-aee6-4c3e47f839f9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fe78aa1b-f8ad-4a52-b980-a3680083cf95', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank kann die gesamte Geschäftsverbindung oder einzelne Geschäftsbeziehungen, für die weder eine Laufzeit noch eine abweichende Kündigungsregelung vereinbart ist, jederzeit unter Einhaltung einer angemessenen Kündigungsfrist kündigen (zum Beispiel den Scheckvertrag, der zur Nutzung von Scheckvordrucken berechtigt). Bei der Bemessung der Kündigungsfrist wird die Bank auf die berechtigten Belange des Kunden Rücksicht nehmen. Für die Kündigung eines Zahlungsdiensterahmenvertrages (z.B. laufendes Konto oder Kartenvertrag) und eines Depots beträgt die Kündigungsfrist mindestens zwei Monate.</p>', 'b9391893-e559-4739-b929-8770fb0e1ddc');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9ba1425a-62b2-403d-a472-7f7f8644cd40', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Upon observing a reasonable period of notice, the Bank may at any time terminate the business relationship as a whole or particular business relations for which neither a term nor a diverging termination provision has been agreed (e.g. the chequing agreement authorising the use of cheque forms). In establishing the notice period, the Bank shall take into account the legitimate concerns of the customer. The minimum termination notice for a payment services framework contract (e.g. current account or card contract) and a securities account shall be two months.</p>', 'b9391893-e559-4739-b929-8770fb0e1ddc');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4c775de4-af8c-4071-b001-2d2e8779cc66', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco podrá rescindir en cualquier momento la relación contractual o parte de ella (por ej. el derecho de utilización de formularios de cheques contractual) en los casos en que no se haya pactado ningún plazo de vigencia determinado o condiciones diferentes de rescisión, concediendo al efecto un plazo razonable de preaviso. Al fijar este plazo, el banco tendrá en cuenta los legítimos intereses del cliente. Para la rescisión de contratos marco de servicios de pagos (por ej. cuentas corrientes o tarjetas) y carteras de valores, el plazo mínimo de preaviso será de dos meses.</p>', 'b9391893-e559-4739-b929-8770fb0e1ddc');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3aebce49-f3d3-4279-acab-acb9bb27099a', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>19.2 Kündigung unbefristeter Kredite</h2>', '6a00ecbd-8d76-4c38-aca8-dc964aa5e955');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('459b14d1-91c6-46de-9b9f-84ebd7e5a562', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>19.2 Termination of loans with no fixed term</h2>', '6a00ecbd-8d76-4c38-aca8-dc964aa5e955');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('055f8b39-5272-496e-8d5a-0953d4642090', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>19.2 Rescisión de créditos sin vencimiento</h2>', '6a00ecbd-8d76-4c38-aca8-dc964aa5e955');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('081c566c-a95c-424c-b65a-3c1dc7e9c1f0', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Kredite und Kreditzusagen, für die weder eine Laufzeit noch eine abweichende Kündigungsregelung vereinbart ist, kann die Bank jederzeit ohne Einhaltung einer Kündigungsfrist kündigen. Die Bank wird bei der Ausübung dieses Kündigungsrechts auf die berechtigten Belange des Kunden Rücksicht nehmen. Soweit das Bürgerliche Gesetzbuch Sonderregelungen für die Kündigung eines Verbraucherdarlehensvertrages vorsieht, kann die Bank nur nach Maßgabe dieser Regelungen kündigen.</p>', '4ce47b29-d9f6-49e6-abe8-e015ddd32623');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d55987c0-55f6-4828-b0a5-d836dec45cde', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Loans and loan commitments for which neither a fixed term nor a diverging termination provision has been agreed may be terminated at any time by the Bank without notice. When exercising this right of termination, the Bank shall give due consideration to the legitimate concerns of the customer. Where the German Civil Code contains specific provisions for the termination of a consumer loan agreement, the Bank may only terminate the agreement as provided therein.</p>', '4ce47b29-d9f6-49e6-abe8-e015ddd32623');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8d8584f0-626b-4e1e-9fae-20831e7a7fe1', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco podrá rescindir en cualquier momento y sin observar plazo alguno de preaviso aquellos créditos o compromisos de préstamo para los que no se haya pactado ningún plazo de vigencia determinado o condiciones diferentes de rescisión. Al ejercer este derecho de rescisión, el banco tendrá en cuenta los legítimos intereses del cliente. En los casos en que el Código Civil alemán establezca disposiciones especiales para la rescisión de contratos de préstamo al consumidor, el banco podrá rescindir solamente con arreglo a dichas condiciones.</p>', '4ce47b29-d9f6-49e6-abe8-e015ddd32623');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('79eab016-22f7-4012-80e1-a4715fa4803d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>19.3 Kündigung aus wichtigem Grund ohne Einhaltung einer Kündigungsfrist</h2>', '7f7c1560-9e07-4f93-b2b8-438b3a13c816');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f673e1f5-36ab-4e65-baca-08e5b47a8f99', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>19.3 Termination for reasonable cause without notice</h2>', '7f7c1560-9e07-4f93-b2b8-438b3a13c816');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e4b46b97-9d5d-47f8-b6eb-1469627ee56c', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>19.3 Rescisión por causa importante sin cumplir el plazo</h2>', '7f7c1560-9e07-4f93-b2b8-438b3a13c816');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3008d7fd-e36a-413b-bd8f-61d742cf2877', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Eine fristlose Kündigung der gesamten Geschäftsverbindung oder einzelner Geschäftsbeziehungen ist zulässig, wenn ein wichtiger Grund vorliegt, der der Bank deren Fortsetzung auch unter Berücksichtigung der berechtigten Belange des Kunden unzumutbar werden lässt. Ein wichtiger Grund liegt insbesondere vor,</p>', '7cacc375-2bb4-4904-b2e4-8a5faa85ad76');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2e2582fa-7e1c-4a21-bc67-47cd0f241cb9', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Termination of the business relationship as a whole or of particular business relations without notice is permitted if there is reasonable cause which makes it unacceptable to the Bank to continue the business relations, also after having given consideration to the legitimate concerns of the customer. Reasonable cause is given in particular</p>', '7cacc375-2bb4-4904-b2e4-8a5faa85ad76');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0163d2bd-beaa-48e5-8532-d24db15ac2d1', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco podrá rescindir inmediatamente la relación contractual o determinados tipos de operaciones si existe una causa importante que, incluso considerando los legítimos intereses del cliente, haga inaceptable para el banco la continuación de dicha relación. Se entenderán expresamente como causa importante los siguientes casos, entre otros:</p>', '7cacc375-2bb4-4904-b2e4-8a5faa85ad76');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bb5b7677-1f5d-4028-922b-3343066cf17b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<ul><li>wenn der Kunde unrichtige Angaben über seine Vermögensverhältnisse gemacht hat, die für die Entscheidung der Bank über eine Kreditgewährung oder über andere mit Risiken für die Bank verbundene Geschäfte (z. B. Aushändigung einer Zahlungskarte) von erheblicher Bedeutung waren; bei Verbraucherdarlehen gilt dies nur, wenn der Kunde für die Kreditwürdigkeitsprüfung relevante Informationen wissentlich vorenthalten oder diese gefälscht hat und dies zu einem Mangel der Kreditwürdigkeitsprüfung geführt hat oder</li><li>wenn eine wesentliche Verschlechterung der Vermögensverhältnisse des Kunden oder der Werthaltigkeit einer Sicherheit eintritt oder einzutreten droht und dadurch die Rückzahlung des Darlehens oder die Erfüllung einer sonstigen Verbindlichkeit gegenüber der Bank – auch unter Verwertung einer hierfür bestehenden Sicherheit – gefährdet ist oder</li><li>wenn der Kunde seiner Verpflichtung zur Bestellung oder Verstärkung von Sicherheiten nach Nr. 13 Absatz 2 dieser Geschäftsbedingungen oder aufgrund einer sonstigen Vereinbarung nicht innerhalb der von der Bank gesetzten angemessenen Frist nachkommt.</li></ul>', '4905633c-f1d5-413a-85c7-e9354ce052cc');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7cb71132-20cd-4b24-bbde-ae82b18c6c5a', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<ul><li>if the customer has made incorrect statements as to the customer&#39;s financial status, provided such statements were of significant importance for the Bank&#39;s decision concerning the granting of credit or other operations involving risks for the Bank (e.g. the delivery of a payment card); for consumer loans, this shall only apply if the customer has knowingly withheld or falsified information of relevance for assessing creditworthiness and this has led to a faulty assessment of creditworthiness, or</li><li>if a substantial deterioration in the customer&#39;s financial status or in the value of security occurs or threatens to occur, jeopardizing the repayment of a loan or the discharge of any other obligation towards the Bank even if security provided therefor is realised, or</li><li>if the customer fails to comply, within the required period of time allowed by the Bank, with the obligation to provide or increase security according to No. 13 (2) of these Business Conditions or to the provisions of some other agreement.</li></ul>', '4905633c-f1d5-413a-85c7-e9354ce052cc');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7e1f063d-d8c9-47fb-9f8e-b6dff88aa549', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<ul><li>si el cliente ha dado informaciones incorrectas sobre su situación patrimonial, las cuales tuvieron gran relevancia para la toma de decisión del banco sobre la constitución de un crédito u otros negocios asociados a riesgos para el banco (por ejemplo, la entrega de una tarjeta de pago) en el caso de los créditos de consumo esto solo es válido si el cliente a conciencia ha retenido o falsificado informaciones relevantes para al análisis de crédito, lo cual causa deficiencias en el análisis de crédito o</li><li>si existe un empeoramiento significativo de la situación patrimonial o de los títulos dados en garantía, o si este deterioro es previsible, poniendo en peligro el reembolso de un préstamo o el cumplimiento de cualquier otro compromiso financiero contraído por el cliente frente al banco, aun después de haberse ejecutado las garantías existentes, o</li><li>si el cliente no cumple dentro de un plazo razonable, fijado por el banco, su obligación de constituir o reforzar garantías, en aplicación del artículo 13 apartado 2 de las presentes Condiciones Generales de Contratación o de cualquier otro acuerdo.</li></ul>', '4905633c-f1d5-413a-85c7-e9354ce052cc');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d5eeeb7a-1873-4cbd-b1cc-8a91c3569711', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Besteht der wichtige Grund in der Verletzung einer vertraglichen Pflicht, ist die Kündigung erst nach erfolglosem Ablauf einer zur Abhilfe bestimmten angemessenen Frist oder nach erfolgloser Abmahnung zulässig, es sei denn, dies ist wegen der Besonderheiten des Einzelfalles (§ 323 Absätze 2 und 3 des Bürgerlichen Gesetzbuches) entbehrlich.</p>', 'b07e024f-7f39-4609-a857-dff285c821c2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2f49f17e-e9c0-401c-8989-51a042a941bb', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>If reasonable cause is given due to the breach of a contractual obligation, termination shall only be permitted after expiry, without result, of a reasonable period of time fixed for corrective action by the customer or after a warning to the customer has proved unsuccessful, unless this proviso can be dispensed with owing to the special features of a particular case (Section 323 (2) and(3) of the German Civil Code).</p>', 'b07e024f-7f39-4609-a857-dff285c821c2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('528b1b65-57f9-4080-87dd-f7a69d343661', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Si la causa justa consistiese en el incumplimiento de una obligación contractual, la resolución de la relación contractual no será efectiva hasta transcurrido sin éxito un plazo razonable destinado a remediar la situación o hasta que el respectivo apercibimiento no haya dado resultado satisfactorio para el banco, salvo que esto no sea necesario dadas las circunstancias del caso concreto (art. 323, párrafos 2 y 3 del Código Civil alemán).</p>', 'b07e024f-7f39-4609-a857-dff285c821c2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('23332cea-9721-4d61-876f-6b544dec69b7', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>19.4 Kündigung von Verbraucherdarlehensverträgen bei Verzug</h2>', '0c15fff3-8bf4-44c1-a7fe-565b24411417');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9e4ec7fc-93b3-4e90-8244-d99afcde8535', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>19.4 Termination of consumer loan agreements in the event of default</h2>', '0c15fff3-8bf4-44c1-a7fe-565b24411417');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f875ba88-82f0-4308-bb42-2b141d7f46c7', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>19.4 Rescisión de contratos de préstamo al consumidor en caso de demora</h2>', '0c15fff3-8bf4-44c1-a7fe-565b24411417');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e00479f2-4f54-4c4f-8df5-925885e6d23d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Soweit das Bürgerliche Gesetzbuch Sonderregelungen für die Kündigung wegen Verzuges mit der Rückzahlung eines Verbraucherdarlehensvertrages vorsieht, kann die Bank nur nach Maßgabe dieser Regelungen kündigen.</p>', 'cf426d69-9634-4d55-9d4a-177333122329');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('925af305-3302-4e61-a748-d0951fce6a7e', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Where the German Civil Code contains specific provisions for the termination of a consumer loan agreement subsequent to repayment default, the Bank may only terminate the agreement as provided therein.</p>', 'cf426d69-9634-4d55-9d4a-177333122329');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b84e9753-9ca2-4cb5-9140-e8895cc50375', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>En los casos en que el Código Civil alemán establezca disposiciones especiales para la rescisión de contratos de préstamo al consumidor por demora en el reembolso, el banco podrá rescindir solamente con arreglo a dichas disposiciones.</p>', 'cf426d69-9634-4d55-9d4a-177333122329');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b555882b-a7e5-469e-9796-09af44f7170f', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>19.5 Abwicklung nach einer Kündigung</h2>', 'ea612065-0c9f-433c-90f5-072ed0839caf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('340d4bc4-18d9-458e-b512-ed0eee8ca10c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>19.5 Settlement following termination</h2>', 'ea612065-0c9f-433c-90f5-072ed0839caf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2c510f5d-5a85-43c1-993c-a38da379849b', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>19.5 Liquidación después de la rescisión</h2>', 'ea612065-0c9f-433c-90f5-072ed0839caf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d95f5c72-e5a9-445a-acff-e5535cbc76da', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Im Falle einer Kündigung ohne Kündigungsfrist wird die Bank dem Kunden für die Abwicklung (insbesondere für die Rückzahlung eines Kredits) eine angemessene Frist einräumen, soweit nicht eine sofortige Erledigung erforderlich ist (zum Beispiel bei der Kündigung des Scheckvertrages die Rückgabe der Scheckvordrucke).</p>', '798c80f4-98f4-46ef-b75f-f04c82245e94');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5f0afad1-9b38-465d-9580-73729eb635d3', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>In the event of termination without notice, the Bank shall allow the customer a reasonable period of time for settlement (in particular for the repayment of a loan), unless it is necessary to attend immediately thereto (e.g. the return of cheque forms following termination of a chequing agreement).</p>', '798c80f4-98f4-46ef-b75f-f04c82245e94');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c3cd4e63-ab7f-4a78-bd94-61113726ff78', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco concederá al cliente un plazo razonable en caso de rescisión sin plazo dado (en especial si se trata de la devolución de un crédito), salvo en los casos en que sea necesario su ejecución inmediata (por ej. devolución inmediata del talonario de cheques en caso de la rescisión contractual respectiva).</p>', '798c80f4-98f4-46ef-b75f-f04c82245e94');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7bb1a45a-7cab-4783-9217-7e58c01a116c', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Schutz der Einlagen</h2>', 'f7209a3e-0824-4cad-bf44-363fafae1cbd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('95cd9093-ef57-462a-b3a6-4e9b06f77ac4', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Protection of Deposits</h2>', 'f7209a3e-0824-4cad-bf44-363fafae1cbd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('da06a8de-3ef0-4d5e-a609-1fffdde38584', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Protección de depósitos</h2>', 'f7209a3e-0824-4cad-bf44-363fafae1cbd');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('cb6c6629-9e30-4f64-af45-63432ca4b0f9', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>20. Information über die Einlagensicherung</h2>', 'a4aed91e-ffb8-41ab-a3c9-1ac2536ef262');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e272fe41-2d6a-4bed-af1a-ee8a233cc120', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>20. Information on deposit protection</h2>', 'a4aed91e-ffb8-41ab-a3c9-1ac2536ef262');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('064ac293-9612-41e8-b68b-d12d98ef9384', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>20. Información sobre garantía de depósitos</h2>', 'a4aed91e-ffb8-41ab-a3c9-1ac2536ef262');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2568961d-87ef-4ee2-b59a-51d1f026e42b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>20.1 Einlagen</h2>', '94b0eed1-bcb9-4860-809e-71e8d58fed5e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c32a4140-e229-406f-ad8c-e38595841ada', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>20.1 Deposits</h2>', '94b0eed1-bcb9-4860-809e-71e8d58fed5e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('aea1b4a8-c376-472c-8f53-df33fc70503c', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>20.1 Depósitos</h2>', '94b0eed1-bcb9-4860-809e-71e8d58fed5e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f523456a-800a-4926-a09b-4f0f64d69c47', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Einlagen sind Guthaben, die sich im Rahmen von Bankgeschäften aus Beträgen, die auf einem Konto verblieben sind, oder aus Zwischenpositionen ergeben und die nach den geltenden gesetzlichen und vertraglichen Bedingungen von der Bank zurückzuzahlen sind, wie zum Beispiel Guthaben auf Girokonten, Festgelder, Spareinlagen, Sparbriefe und Namensschuldverschreibungen. Maßgeblich sind die Definitionen in § 2 Absatz 3 des Einlagensicherungsgesetzes (EinSiG) bzw. § 6 Absatz 1 des Statuts des innerhalb des Bundesverbandes deutscher Banken e.V. bestehenden Einlagensicherungsfonds deutscher Banken (Einlagensicherungsfonds).</p>', 'ba241250-e218-4449-af5c-c0c55c446caf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('eb7ecbc0-3319-41bf-995d-c082473ac501', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Deposits are credit balances resulting from funds left in an account or from temporary situations deriving from banking transactions and which the Bank is required to repay under the legal and contractual conditions applicable, such as credit balances on current accounts, time deposits, savings deposits, savings bonds and registered bonds. The applicable definitions shall be those set out in Section 2 (3) of the German Deposit Guarantee Act (Einlagensicherungsgesetz [EinSiG]) and Section 6 (1) of the By-laws of the Deposit Protection Fund of German Banks (Einlagensicherungsfonds deutscher Banken – Einlagensicher-ungsfonds), which forms part of the Association of German Banks (Bundesverband deutscher Banken e.V.)</p>', 'ba241250-e218-4449-af5c-c0c55c446caf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e539b939-fc4a-49d3-9a32-cbcd6fe6080a', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Los depósitos son saldos que surgen en el curso de la actividad bancaria a partir de los montos que permanecen en una cuenta o de posiciones intermedias y que son reembolsables por el Banco de acuerdo a las condiciones legales y contractuales aplicables, como por ejemplo, los saldos acreedores de las cuentas corrientes, los depósitos a plazo, los depósitos de ahorro, los bonos de ahorro y los bonos nominativos. Son válidas las definiciones del artículo 2, párrafo 3, de la Ley de Protección de Depósitos (EinSiG) y del artículo 6, párrafo 1, del Estatuto del Fondo de garantía de depósitos de los Bancos Alemanes (Fondo de garantía de depósitos) existente dentro de la Asociación de Bancos Alemanes.</p>', 'ba241250-e218-4449-af5c-c0c55c446caf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('412ad6b0-a21f-406f-947c-403ea45889d0', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>20.2 Gesetzliche Einlagensicherung</h2>', '86e94534-b43c-4b8a-9cd5-75169cb8415e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6faa1c4b-5ca6-4777-9394-0297e448d67a', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>20.2 Statutory deposit protection</h2>', '86e94534-b43c-4b8a-9cd5-75169cb8415e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('51f52505-f21d-4e85-b7c4-4d87c7ca165f', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>20.2 Garantía de depósitos legal</h2>', '86e94534-b43c-4b8a-9cd5-75169cb8415e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e03dc1da-7026-459d-9482-71d63df8533b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank ist der Entschädigungseinrichtung deutscher Banken GmbH als Träger der gesetzliche Einlagensicherung der privaten Banken zugeordnet. Die gesetzliche Einlagensicherung schützt nach Maßgabe des EinSiG und vorbehaltlich der darin vorgesehenen Ausnahmen Einlagen bis zu einem Gegenwert von 100 000 Euro pro Einleger. In den in § 8 Absatz 2 EinSiG genannten Fällen erhöht sich dieser Betrag auf 500 000 Euro. Dazu gehören insbesondere Beträge, die aus Immobilientransaktionen im Zusammenhang mit privat genutzten Wohnimmobilien resultieren. Nicht geschützt werden insbesondere Einlagen von finanziellen Unternehmen, staatlichen Stellen einschließlich kommunaler Gebietskörperschaften, Einlagen, die im Zusammenhang mit Geldwäsche oder Terrorismusfinanzierung entstanden sind, und Inhaberschuldverschreibungen. Einzelheiten sind im EinSiG, insbesondere dessen § 8 geregelt.</p>', '2c85ca21-8cf5-4a7d-b517-da7e367cbbba');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6190c444-4d45-4863-adde-2bf8450b77b7', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank is assigned to the Entschädigungseinrichtung deutscher Banken GmbH (Compensation Scheme of German Banks) as the institution responsible for the statutory deposit protection of private banks. In accordance with EinSiG and subject to the exemptions provided for therein, the statutory deposit protection scheme protects deposits up to an equivalent of 100,000 euros per depositor. In the cases specified in Section 8 (2) of EinSiG, this amount is increased to 500,000 euros. These cases cover, in particular, amounts resulting from real estate transactions in connection with privately used residential property. Not protected are, in particular, deposits of financial firms, public authorities including regional and local authorities, deposits that have arisen in connection with money laundering or terrorist financing, and bearer bonds. Details are set out in EinSiG, in particular Section 8 thereof.</p>', '2c85ca21-8cf5-4a7d-b517-da7e367cbbba');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3995cba0-1cc9-44cb-aab2-367b2637a507', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El Banco está adscrito al sistema de compensación de bancos alemanes (Entschädigungseinrichtung deutscher Banken GmbH) como institución responsable legalmente de la garantía de depósitos de los bancos privados. De acuerdo con la EinSiG y con las excepciones previstas en ella, la garantía de depósitos legal, protege los depósitos hasta un valor equivalente de 100.000 euros por depositante. En los casos mencionados en el artículo 8, párrafo 2 de la EinSiG, esta cantidad aumenta a 500.000 euros. En particular, esto incluye los importes resultantes de transacciones inmobiliarias en relación con bienes inmuebles residenciales de uso privado. No están protegidos, en particular, los depósitos de empresas financieras, organismos gubernamentales, incluidas las autoridades locales, los depósitos que se hayan originado en relación con el lavado de activos o la financiación del terrorismo y los bonos al portador. Los detalles están regulados por la EinSiG, particularmente en su artículo 8.</p>', '2c85ca21-8cf5-4a7d-b517-da7e367cbbba');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('58e843c6-f161-4673-a7c9-b4598b14eb8c', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>20.3 Einlagensicherungsfonds</h2>', '28448077-5341-4ef9-a91d-e881a7af1e3b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('df301244-118d-486f-85b8-6be9470b2f52', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>20.3 Deposit Protection Fund</h2>', '28448077-5341-4ef9-a91d-e881a7af1e3b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c5900aaa-3656-494d-8dc1-5f0816af0117', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>20.3 Fondo de garantía de depósitos</h2>', '28448077-5341-4ef9-a91d-e881a7af1e3b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7501d832-981b-44f4-a202-c2ae0ebc5318', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank wirkt außerdem am Einlagensicherungsfonds mit. Dieser sichert nach Maßgabe seines Statuts und vorbehaltlich der darin vorgesehenen Ausnahmen Einlagen bei einer inländischen Haupt- oder Zweigniederlassung bzw. Zweigstelle je Gläubiger maximal bis zur folgenden Höhe (Sicherungsgrenze):</p>', 'b33e3d08-a9b0-4010-9cab-1d13b95df9eb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1badd9e7-6705-44e9-a256-df935b6a3bd6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank also participates in the Deposit Protection Fund. In accordance with its By-laws and subject to the exemptions provided for therein, the Fund shall protect deposits at a domestic head office or branch office up to the following amount per creditor (protection ceiling):</p>', 'b33e3d08-a9b0-4010-9cab-1d13b95df9eb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('293c4440-af96-452e-bbff-8eede236e9e1', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El banco participa igualmente en el Fondo de garantía de depósitos. Este último, de acuerdo con sus estatutos y sin perjuicio de las excepciones previstas en los mismos, garantizará los depósitos en una sede principal o, sucursal nacional o, filial hasta un máximo de la siguiente cantidad (límite de garantía), por cada acreedor:</p>', 'b33e3d08-a9b0-4010-9cab-1d13b95df9eb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d1d2fd9c-ceaa-4386-ba34-4df8240e2c0b', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<ol><li>(i) 5 Millionen Euro für natürliche Personen und rechtsfähige Stiftungen unabhängig von ihrer Laufzeit und (ii) 50 Millionen Euro für nichtfinanzielle Unternehmen, gemeinnützige Organisationen, Verbände und Berufsorganisationen ohne Erwerbszweck und andere in § 6 Absatz 3 des Statuts des Einlagensicherungsfonds genannte Gläubiger. In jedem Fall werden Einlagen bis maximal 15% der Eigenmittel der Bank im Sinne von Artikel 72 CRR geschützt, wobei Ergänzungskapital nur bis zur Höhe von 25% des Kernkapitals im Sinne von Artikel 25 CRR Berücksichtigung findet. Weitere Einzelheiten zur Berechnung der relevanten Eigenmittel regelt § 6 Absatz 8 (a) des Statuts des Einlagensicherungsfonds.</li><li>Ab dem 1. Januar 2025: (i) 3 Millionen Euro für natürliche Personen und rechtsfähige Stiftungen unabhängig von ihrer Laufzeit und (ii) 30 Millionen Euro für nichtfinanzielle Unternehmen, gemeinnützige Organisationen, Verbände und Berufsorganisationen ohne Erwerbszweck und andere in § 6 Absatz 3 des Statuts des Einlagensicherungsfonds genannte Gläubiger. In jedem Fall werden Einlagen bis maximal 8,75% der Eigenmittel im Sinne von Absatz (a) Sätzen 2 und 3 geschützt.</li><li>Ab dem 1. Januar 2030: (i) 1 Million Euro für natürliche Personen und rechtsfähige Stiftungen unabhängig von ihrer Laufzeit und (ii) 10 Millionen Euro für nichtfinanzielle Unternehmen, gemeinnützige Organisationen, Verbände und Berufsorganisationen ohne Erwerbszweck und andere in § 6 Absatz 3 des Statuts des Einlagensicherungsfonds genannte Gläubiger. In jedem Fall werden Einlagen bis maximal 8,75% der Eigenmittel im Sinne von Absatz (a) Sätzen 2 und 3 geschützt.</li><li>Für Einlagen, die bis zum Ablauf des 31. Dezember 2022 gesichert wurden, finden die zu diesem Zeitpunkt geltenden Sicherungsgrenzen weiterhin Anwendung bis die Einlage fällig ist, prolongiert wird oder vom Kunden erstmals gekündigt werden kann oder auf eine ausländische Zweigniederlassung oder Zweigstellen übertragen wird. Für Einlagen, die nach dem 31. Dezember 2022 begründet oder prolongiert werden, gelten die jeweils neuen Sicherungsgrenzen ab den oben genannten Stichtagen.</li></ol>', 'a4ed58ec-7bb4-4273-a622-40fee3f55c34');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e22e22cf-bd7f-455b-93d0-0a465e9d75fb', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<ol><li>(i) 5 million euros for natural persons and foundations with legal capacity irrespective of the term of the deposit; and (ii) 50 million euros for nonfinancial companies, non-profit organisations, associations and non-profit professional organisations, and other creditors referred to in Section 6(3) of the By-laws of the Deposit Protection Fund. In any event, deposits shall be protected up to a maximum of 15% of the bank’s own funds within the meaning of Article 72 of the CRR, with Tier 2 capital only being taken into account up to an amount of 25% of Tier 1 capital within the meaning of Article 25 of the CRR. Further details on calculating the relevant own funds are set out in Section 6 (8) (a) of the By-laws of the Deposit Protection Fund.</li><li>From 1 January 2025: (i) 3 million euros for natural persons and foundations with legal capacity irrespective of the term of the deposit and (ii) 30 million euros for non-financial companies, non-profit organisations, associations and non-profit professional organisations, and other creditors referred to in Section 6(3) of the By-laws of the Deposit Protection Fund. In any event, deposits shall be protected up to a maximum of 8.75% of own funds within the meaning of paragraph (a), sentences 2 and 3.</li><li>From 1 January 2030: (i) 1 million euros for natural persons and foundations with legal capacity irrespective of the term of the deposit and (ii) 10 million euros for non-financial companies, non-profit organisations, associations and non-profit professional organisations, and other creditors referred to in Section 6(3) of the By-laws of the Deposit Protection Fund. In any event, deposits shall be protected up to a maximum of 8.75% of own funds within the meaning of paragraph (a), sentences 2 and 3.</li><li>For deposits protected until the end of 31 December 2022, the protection ceilings applicable at that time shall continue to apply until the deposit matures, is rolled over or can be cancelled by the customer for the first time or is transferred to one or more foreign branches. For deposits established or rolled over after 31 December 2022, the relevant new protection ceilings shall apply as of the above cut-off dates.</li></ol>', 'a4ed58ec-7bb4-4273-a622-40fee3f55c34');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d2f23717-c001-45e1-a3ea-9ca30ea554a0', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<ol><li>(i) 5 millones de euros para personas físicas y fundaciones con personalidad jurídica, independientemente de su duración, y (ii) 50 millones de euros para sociedades no financieras, organizaciones sin ánimo de lucro, asociaciones y organizaciones profesionales sin ánimo de lucro y otros acreedores mencionados en el artículo 6.3 del Estatuto del Fondo de garantía de depósitos. En cualquier caso, los depósitos están protegidos hasta un máximo del 15% de los fondos propios del banco, según lo dispuesto en el artículo 72 de la RRC, y el capital complementario sólo se tiene en cuenta hasta el importe del 25% del capital básico, según lo dispuesto en el artículo 25 de la RRC. Más detalles sobre el cálculo de los fondos propios correspondientes figuran en el artículo 6.8(a) del Estatuto del Fondo de garantía de depósitos.</li><li>A partir del 1 de enero de 2025: (i) 3 millones de euros para personas físicas y fundaciones con personalidad jurídica, independientemente de su duración, y (ii) 30 millones de euros para sociedades no financieras, organizaciones sin ánimo de lucro, asociaciones y organizaciones profesionales sin ánimo de lucro y otros acreedores mencionados en el artículo 6.3 del estatuto del Fondo de garantía de depósitos. En cualquier caso, se protegerán los depósitos hasta un máximo del 8,75% de los fondos propios, de acuerdo con la segunda y tercera frase del apartado (a).</li><li>A partir del 1 de enero de 2030: (i) 1 millón de euros para personas físicas y fundaciones con personalidad jurídica, independientemente de su duración, y (ii) 10 millones de euros para sociedades no financieras, organizaciones sin ánimo de lucro, asociaciones y organizaciones profesionales sin ánimo de lucro y otros acreedores mencionados en el artículo 6.3 del Estatuto del Fondo de garantía de depósitos. En cualquier caso, se protegerán los depósitos hasta un máximo del 8,75% de los fondos propios, de acuerdo con la segunda y tercera frase del apartado (a).</li><li>Para los depósitos que se hayan garantizado antes del 31 de diciembre de 2022, los límites de protección aplicables en ese momento continuarán aplicándose hasta que el depósito venza, se renueve o sea cancelado por el cliente por primera vez, o se transfiera a una sucursal o sucursales en el extranjero. Para los depósitos que se constituyan o renueven después del 31 de diciembre de 2022, se aplicarán los nuevos límites de garantía respectivos a partir de las fechas límite mencionadas anteriormente.</li></ol>', 'a4ed58ec-7bb4-4273-a622-40fee3f55c34');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6690bd56-5242-40bb-86ae-73af6a3febe1', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Maßgebend für die Entschädigung ist die Sicherungsgrenze, die der Bank als Ergebnis der Feststellung des Prüfungsverbandes mitgeteilt worden ist und im Internet unter http://www.bankenverband.de abgerufen werden kann. Die Sicherungsgrenze wird dem Kunden von der Bank auf Verlangen bekannt gegeben. Nicht geschützt werden insbesondere Einlagen von finanziellen Unternehmen, staatlichen Stellen einschließlich kommunaler Gebietskörperschaften, Einlagen, die im Zusammenhang mit Geldwäsche oder Terrorismusfinanzierung entstanden sind, und Inhaberschuldverschreibungen. Im Fall von Gläubigern nach Buchstaben (b)(ii), (c)(ii) und (d)(ii) werden Einlagen mit einer Laufzeit von mehr als 12 Monaten sowie Verbindlichkeiten aus Schuldscheindarlehen, Namenschuldverschreibungen und vergleichbaren Schuldtiteln ausländischen Rechts nicht geschützt.</p>', '9fc5d2f2-5d3a-4b4d-bfd7-711d79ec55e1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('10f91dac-82e0-43e1-a7a4-4e6be51045a7', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The compensation shall be based on the protection ceiling which has been notified to the Bank as the result of the assessment made by the Auditing Association and which is available on the internet at www.bankenverband.de. The protection ceiling shall be notified to the customer by the Bank on request. Not protected are, in particular, deposits of financial firms, public authorities including regional and local authorities, deposits that have arisen in connection with money laundering or terrorist financing, and bearer bonds. For creditors specified under point (b)(ii), (c)(ii) and (d)(ii), deposits with a term of more than 12 months and liabilities from promissory notes loans, registered bonds and comparable debt instruments under foreign law shall not be protected.</p>', '9fc5d2f2-5d3a-4b4d-bfd7-711d79ec55e1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2fccb8da-4cb3-4963-b5b0-8b15c0a4d272', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El límite de garantía notificado al Banco como resultado de la evaluación de la Asociación de auditoría y disponible en Internet en www.bankenverband.de será determinante para la compensación. El límite de garantía será comunicado por el Banco a solicitud del cliente. No están protegidos, en particular, los depósitos de empresas financieras, organismos gubernamentales, incluidas las autoridades locales, los depósitos que se hayan originado en relación con el lavado de activos o la financiación del terrorismo y los bonos al portador. Tratándose de los acreedores comprendidos en los incisos (b)(ii), (c)(ii) y (d)(ii), los depósitos con un plazo superior a 12 meses y los pasivos procedentes de préstamos con pagarés, bonos nominativos e instrumentos de deuda comparables según la legislación extranjera, no están protegidos.</p>', '9fc5d2f2-5d3a-4b4d-bfd7-711d79ec55e1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6ef53318-7523-45db-82c1-383671bf4e25', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Für Verbindlichkeiten von Banken, die bis zum Ablauf des 31. Dezember 2022 gemäß § 6 der am 18. November 2021 im Vereinsregister eingetragenen Fassung des Statuts des Einlagensicherungsfonds gesichert wurden, besteht die Sicherung nach Maßgabe dieser Vorschrift fort. Nach dem 31. Dezember 2022 entfällt dieser Bestandsschutz, sobald die betreffende Verbindlichkeit fällig wird, gekündigt oder anderweitig zurückgefordert werden kann, oder wenn die Verbindlichkeit im Wege einer Einzel- oder Gesamtrechtsnachfolge übergeht oder auf eine ausländische Zweigniederlassung oder Zweigstelle übertragen wird.</p>', '66baaf56-7dff-4ef8-9a7c-ada904ce7ab4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('30f19669-6456-4900-9d96-d79e01b5061b', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Liabilities of banks that were protected until the end of 31 December 2022 in accordance with Section 6 of the version of the By-laws of the Deposit Protection Fund registered with the Register of Associations on 18 November 2021 shall continue to be protected as provided for thereunder. After 31 December 2022, this grandfathered status shall cease to apply as soon as the liability concerned falls due, can be terminated or otherwise reclaimed, or if the liability is transferred by way of singular or universal succession or is transferred to a foreign branch.</p>', '66baaf56-7dff-4ef8-9a7c-ada904ce7ab4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ff2582df-373a-45fa-9a06-48f0ff0a5823', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>En cuanto a las obligaciones de los bancos que hayan sido garantizadas hasta la expiración del 31 de diciembre de 2022, de conformidad con el artículo 6 de la versión del Estatuto del Fondo de garantía de depósitos, inscrita en el Registro de asociaciones el 18 de noviembre de 2021, la garantía continuará de acuerdo con esta disposición. Después del 31 de diciembre de 2022, esta exención cesa en el momento en que la obligación en cuestión venza, se extinga o pueda reclamarse de otro modo, o si la obligación es transferida a título de sucesión singular o universal o es transferida a una sucursal o filial extranjera.</p>', '66baaf56-7dff-4ef8-9a7c-ada904ce7ab4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2b5b7507-7ae0-4794-8a93-8864e40a9aec', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Einzelheiten zum Schutzumfang einschließlich der Sicherungsgrenzen sind im Statut des Einlagensicherungsfonds, insbesondere dessen § 6 geregelt.</p>', '950bb7f9-e67d-4cb4-b2ee-2127a75331ee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bdf3b363-6f73-49e2-b5fc-9ec839597f5c', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Details on the scope of protection, including the protection ceilings, are set out in the By-laws of the Deposit Protection Fund, in particular Section 6 thereof.</p>', '950bb7f9-e67d-4cb4-b2ee-2127a75331ee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8b06c2ba-1aa1-4f6d-8622-36a81705262b', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>Los detalles sobre el alcance de la garantía, incluidos los límites de la misma, se regulan en el Estatuto del Fondo de garantía de depósitos, en particular en su artículo 6.</p>', '950bb7f9-e67d-4cb4-b2ee-2127a75331ee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ef5d7c1f-9fd1-4476-93aa-c293e4c1270d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Das Statut wird auf Verlangen zur Verfügung gestellt und kann auch im Internet unter www.bankenverband.de aufgerufen werden.</p>', 'c1e5de72-6c69-4179-a0d9-5633da2b111d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c3539d43-9fd8-47e6-a748-a1d0b654eda7', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The By-laws shall be made available on request and can also be accessed on the internet at www.bankenverband.de.</p>', 'c1e5de72-6c69-4179-a0d9-5633da2b111d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('974416a4-4cb9-444c-b90a-dbd15fdb833e', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El estatuto estará disponible previa solicitud y también está disponible en Internet www.bankenverband.de.</p>', 'c1e5de72-6c69-4179-a0d9-5633da2b111d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8f26f577-7b69-4b8e-aeea-a62c86394e07', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>20.4 Forderungsübergang</h2>', 'a411dc87-a5f8-4015-b233-79c664f6295a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('388f7015-a4ef-45f1-bd8b-83c0a5f006f6', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>20.4 Transfer of claims</h2>', 'a411dc87-a5f8-4015-b233-79c664f6295a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0b3a7929-ad63-4e51-b432-1ad2c537d881', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>20.4 Subrogación</h2>', 'a411dc87-a5f8-4015-b233-79c664f6295a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bac66437-075c-4b2c-892e-8e5ea67a9201', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Soweit der Einlagensicherungsfonds oder ein von ihm Beauftragter Zahlungen an einen Kunden leistet, gehen dessen Forderungen gegen die Bank in entsprechender Höhe mit allen Nebenrechten Zug um Zug auf den Einlagensicherungsfonds über.</p>', 'ffd5d07c-c80e-47b9-badc-840de61b8f89');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('98423a38-5425-4a97-9bdf-723ec2370813', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>To the extent that the Deposit Protection Fund or one of its representatives makes payments to a customer, the amount of the customer&#39;s claims against the Bank, together with all subsidiary rights, shall be transferred simultaneously to the Deposit Protection Fund.</p>', 'ffd5d07c-c80e-47b9-badc-840de61b8f89');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('09a7888b-25c6-4710-b664-37a2cbc48b0c', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>En la medida en que el Fondo de garantía de depósitos o uno de sus agentes efectúe pagos a un cliente, las demandas del cliente contra el Banco pasarán al Fondo de garantía de depósitos de forma simultánea y en la proporción correspondiente con todos los derechos accesorios.</p>', 'ffd5d07c-c80e-47b9-badc-840de61b8f89');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b54a8c75-0171-456e-9460-545450c5ae8d', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>20.5 Auskunftserteilung</h2>', '401fb3f5-4ab8-472e-939f-d78d05229a01');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f2e6a2cd-964f-4896-baa0-447b6e545af3', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>20.5 Disclosure of information</h2>', '401fb3f5-4ab8-472e-939f-d78d05229a01');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('92e348c6-a8c8-4e56-9a34-fed086550bda', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>20.5 Suministro de información</h2>', '401fb3f5-4ab8-472e-939f-d78d05229a01');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5b95deda-497b-4a78-8e79-c78cd0a319ae', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Die Bank ist befugt, dem Einlagensicherungsfonds oder einem von ihm Beauftragten alle in diesem Zusammenhang erforderlichen Auskünfte zu erteilen und Unterlagen zur Verfügung zu stellen.</p>', '87d87dcb-85b3-4cd6-bb27-6799e2963a70');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c640b17d-b97b-42ca-9226-0aecbbca9334', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>The Bank shall be entitled to disclose and make available to the Deposit Protection Fund or one of its representatives all necessary information and documents in this regard.</p>', '87d87dcb-85b3-4cd6-bb27-6799e2963a70');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('559d2dcd-14c7-4abd-aca4-4cf057064841', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El Banco estará encargado de facilitar al Fondo de garantía de depósitos, o a una persona autorizada por este, toda la información y los documentos que se requieran a este propósito.</p>', '87d87dcb-85b3-4cd6-bb27-6799e2963a70');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d0f16704-ebc3-4dd3-a0b7-11e0103539e9', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>Beschwerdemöglichkeiten/Ombudsmannverfahren</h2>', '9a1d4a63-b20c-4a15-b451-ebdc20b72e68');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('51cbb304-f8f0-4911-ba36-0d72ad021b46', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>Complaint Channels/ Ombudsman Scheme</h2>', '9a1d4a63-b20c-4a15-b451-ebdc20b72e68');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('45512564-a6ee-498a-ba66-ce56d0f16eb1', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>Posibilidades de reclamo / Procedimiento ante el Defensor del Pueblo</h2>', '9a1d4a63-b20c-4a15-b451-ebdc20b72e68');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('04e1b6d7-743a-48c6-9495-cf050d3a7db3', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<h2>21. Beschwerde- und Alternative Streitbeilegungsverfahren</h2>', 'b09f6c5d-0fa4-43b9-bb29-525286c268f7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9e44dc41-1b55-4276-b29f-f8a7f2ed6a22', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<h2>21. Complaints procedure and alternative dispute resolution</h2>', 'b09f6c5d-0fa4-43b9-bb29-525286c268f7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('40a7004d-5efc-4870-9560-747b30dcf28f', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<h2>21. Reclamos y procedimientos alternativos de resolución de conflictos</h2>', 'b09f6c5d-0fa4-43b9-bb29-525286c268f7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6f5c2b25-9d5f-401f-9010-ed759bc6b812', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<p>Der Kunde hat folgende außergerichtliche Möglichkeiten:</p>', '21ead0e2-b448-4b4d-ab41-0bc66101a094');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a9c6acc2-80b4-417b-9585-b4ba7149840d', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<p>Customers have the following out-of-court options:</p>', '21ead0e2-b448-4b4d-ab41-0bc66101a094');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b61d3fa4-b892-47ae-a501-b2900e24dc63', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<p>El cliente cuenta con las siguientes posibilidades extrajudiciales:</p>', '21ead0e2-b448-4b4d-ab41-0bc66101a094');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ee448d31-de95-475b-bbd5-e6ace192ad55', '2026-09-14 14:32:36.279', 'de', 1, 'DRAFT', '<ul><li>Der Kunde kann sich mit einer Beschwerde an die im &quot;Preis- und Leistungsverzeichnis&quot; genannte Kontaktstelle der Bank wenden. Die Bank wird Beschwerden in geeigneter Weise beantworten, bei Zahlungsdiensteverträgen erfolgt dies in Textform (zum Beispiel mittels Brief, Telefax oder E-Mail).</li><li>Die Bank nimmt am Streitbeilegungsverfahren der Verbraucherschlichtungsstelle &quot;Ombudsmann der privaten Banken&quot; (www.bankenombudsmann.de) teil. Dort hat der Verbraucher die Möglichkeit, zur Beilegung einer Streitigkeit mit der Bank den Ombudsmann der privaten Banken anzurufen. Betrifft der Beschwerdegegenstand eine Streitigkeit über einen Zahlungsdienstevertrag (§ 675f des Bürgerlichen Gesetzbuches), können auch Kunden, die keine Verbraucher sind, den Ombudsmann der privaten Banken anrufen. Näheres regelt die &quot;Verfahrensordnung für die Schlichtung von Kundenbeschwerden im deutschen Bankgewerbe&quot;, die auf Wunsch zur Verfügung gestellt wird oder im Internet unter www.bankenverband.de abrufbar ist. Die Beschwerde ist in Textform (z.B. mittels Brief oder E-Mail) an die Kundenbeschwerdestelle beim Bundesverband deutscher Banken e.V., Postfach 04 03 07, 10062 Berlin, Fax: (030) 1663-3169, E-Mail: schlichtung@bdb.de, zu richten.</li><li>Ferner besteht für den Kunden die Möglichkeit, sich jederzeit schriftlich oder zur dortigen Niederschrift bei der Bundesanstalt für Finanzdienstleistungsaufsicht, Graurheindorfer Straße 108, 53117 Bonn, über Verstöße der Bank gegen das Zahlungsdiensteaufsichtsgesetz (ZAG), die §§ 675c bis 676c des Bürgerlichen Gesetzbuches (BGB) oder gegen Artikel 248 des Einführungsgesetzes zum Bürgerlichen Gesetzbuche (EGBGB) zu beschweren.</li></ul>', '5aa78385-0593-4759-9f81-0a3cfc5d5d03');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8b3762a7-1e66-412f-a8bf-18f8b8f97a2b', '2026-09-14 14:32:36.279', 'en', 1, 'DRAFT', '<ul><li>Customers may address a complaint to the contact point specified by the Bank in its &quot;List of Prices and Services&quot;. The Bank will answer complaints in an appropriate manner; where payment services contracts are concerned, it will do so in text form (e.g. by letter, telefax or email).</li><li>The Bank participates in the dispute resolution scheme run by the consumer arbitration body &quot;The German Private Banks&#39; Ombudsman&quot; (www.bankenombudsmann.de). Consumers may have any disputes with the Bank resolved by the Ombudsman. Where disputes concerning a payment services contract (Section 675f of the German Civil Code) are involved, customers who are not consumers also may request their resolution by the Ombudsman. Further details are contained in the &quot;Rules of Procedure for the Settlement of Customer Complaints in the German Private Commercial Banking Sector&quot;, which are available on request or can be downloaded from the Internet at www.bankenverband.de. Complaints should be addressed in text form (e.g. by letter or email) to the Customer Complaints Office (Kundenbeschwerdestelle) at the Association of German Banks (Bundesverband deutscher Banken), P.O. Box (Postfach) 040307, 10062 Berlin; fax: +49 (0)30 16633169; email: schlichtung@bdb.de.</li><li>In addition, customers may make complaints at any time in writing or orally on the record to the German Federal Financial Supervisory Authority (Bundesanstalt für Finanzdienstleistungsaufsicht – BaFin), Graurheindorfer Strasse 108, 53117 Bonn, about breaches by the Bank of the German Payment Services Supervision Act (Zahlungsdiensteaufsichtsgesetz – ZAG), Sections 675c – 676c of the German Civil Code (Bürgerliches Gesetzbuch – BGB) or Article 248 of the Act Introducing the German Civil Code (Einführungsgesetz zum Bürgerlichen Gesetzbuch – EGBGB).</li></ul>', '5aa78385-0593-4759-9f81-0a3cfc5d5d03');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('346a30b5-eee9-466f-be0f-85fa1386035d', '2026-09-14 14:32:36.279', 'es', 1, 'DRAFT', '<ul><li>Puede dirigirse al punto de contacto del banco correspondiente para consultar &quot;el pliego de precios y condiciones&quot;. El banco responderá a las reclamaciones de forma adecuada; en el caso de contratos de servicios de pago, lo hará en forma textual (por ejemplo, mediante carta, fax o correo electrónico).</li><li>El banco participa del procedimiento de resolución de conflictos del centro de avenencia de los consumidores &quot;Ombudsmann de los bancos privados&quot; (www.banken-ombudsmann.de). En caso de conflictos con el banco, el consumidor tiene la posibilidad de contactar al Ombudsmann de los bancos privados para resolver un conflicto que él tiene con el banco. Si el objeto del reclamo es el conflicto sobre un contrato de servicios de pago (Artículo § 675f del Código Civil), también clientes que no son consumidores pueden contactar al Ombudsmann de los bancos privados. Mayor información se encuentra en el &quot;Ordenamiento del procedimiento sobre la avenencia de reclamos de clientes en la industria bancaria alemana&quot;, que se pone a disposición a solicitud del interesado o que se puede consultar bajo www.bankenverband.de. El reclamo se debe presentar en formato de texto (por ejemplo, vía carta, fax o e-mail) ante el Centro de reclamos de clientes de la Asociación Federal de los Bancos Alemanes (Kundenbeschwerdestelle beim Bundesverband deutscher Banken e. V.), Postfach 04 03 07, 10062 Berlin, Fax: (030) 1663-3169, E-Mail: schlichtung@bdb.de.</li><li>Además, también existe para el cliente la posibilidad de presentar un reclamo en cualquier momento por escrito o trascribiéndolo directamente en las oficinas de la Autoridad Federal de Supervisión Financiera alemana, en Graurheindorfer Straße 108, 53117 Bonn, sobre infracciones bancarias contra la Ley alemana de Servicios de Pago (ZAG, en sus siglas en alemán), los artículos 675c a 676c del Código Civil alemán (BGB, en sus siglas en alemán) o contra el artículo 248 de la Ley alemana de introducción al Código Civil (EGBGB, en sus siglas en alemán).</li></ul>', '5aa78385-0593-4759-9f81-0a3cfc5d5d03');
